/* 自动生成，勿手改：node tools/build_content_v2.mjs
   来源：book/lessons/lesson02.mjs … lesson20.mjs
   作用：把新正文并入 window.COURSE.content（第 1 课在 data.js 内）。 */
window.COURSE.content = Object.assign(window.COURSE.content || {}, {"2":{"title":"功能参数：十个指标决定能不能用","sub":"客户说“要一根耐压 1.6 兆帕、行程 10 毫米的波纹管”，这句话里其实藏着十个参数。少问一个，报价就会偏。","tags":["第1章","功能参数","刚度","有效面积","寿命"],"objectives":["分清功能参数和质量参数：一个决定能不能用，一个决定好不好检","记住载荷、位移、刚度、灵敏度、有效面积、寿命、密封、自振频率、温度这十个指标","会用 K=F/w、δ=w/F、A_e=F/p 做粗算，并知道单位怎么带","知道 125% 与 150% 两个超载界限，以及刚度允差 ±5% 与 ±50% 的差别","拿到客户一句话询价，能追问出缺的那几个参数"],"blocks":[{"t":"lead","x":"上一课我们把波纹管拆开看：它是一根会呼吸的金属管。这一课换一个角度：客户要买它，到底在买哪些“能力”？书里把这些能力分成两类——功能参数和质量参数。先把功能参数讲透，因为销售报错价，十次有八次是功能参数没问全。"},{"t":"figure","name":"params10","cap":"十个参数，少问一个就多一分报价风险"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["F","大写 F，读“力”","N","集中力：拉或压波纹管的力"],["p","小写 p，读“压”","MPa","压力：内压或外压"],["M","大写 M，读“力矩”","N·mm","让波纹管弯曲或扭转的力矩"],["w","小写 w，读“位移”","mm","波纹管被拉长或压短的长度"],["K_F","K 下标 F","N/mm","刚度：每压 1 mm 要多少力"],["δ","希腊字母 delta","mm/N","灵敏度：每 1 N 能走多少 mm"],["A_e","A 下标 e","mm²","有效面积：把压力换成力的“换算面积”"]]},{"t":"h2","x":"一、两类参数：一个管“能不能用”，一个管“好不好检”"},{"t":"p","x":"（书 §1.2）功能参数是判定元件能否满足使用要求的参数，设计时给出额定值和允差；质量参数是检测元件质量时测的参数，用来评价一批产品稳不稳定。简单说：功能参数是客户嘴里说的“我要它能顶多大压力、走多远”；质量参数是检验员手里测的“它的曲线直不直、回不回得去”。"},{"t":"table","head":["类别","回答什么问题","典型参数","谁最关心"],"rows":[["功能参数","能不能用","载荷、位移、刚度、灵敏度、有效面积、寿命、密封、自振频率、温度","客户、设计、销售"],["质量参数","好不好检、稳不稳","非线性度、迟滞、残余变形、热弹性误差、失稳","检验、质量、仪表校准"]]},{"t":"callout","kind":"key","title":"先记一句话","x":"功能参数决定“能不能接单”，质量参数决定“这批货会不会被退货”。销售先问功能，再谈质量。"},{"t":"h2","x":"二、载荷：不是只问“多大压力”"},{"t":"p","x":"（书 §1.2.1）载荷是作用在波纹管上的预期负荷，常见三种：集中力 F（N）、压力 p（MPa）、力矩 M（N·mm）。除了数值，还必须知道**方向**和**作用位置**。压力载荷还要说明：是内腔受压，还是外腔受压。"},{"t":"p","x":"为什么方向这么重要？同样 1 MPa，内压让波纹管“想伸直”，外压让它“想压扁”，两者的失稳模式和有效面积符号都不一样。很多现场事故不是压力超了，而是把外压当内压算。"},{"t":"callout","kind":"warn","title":"销售最常漏问的一句","x":"“这个压力是加在管子里面，还是外面？”——内压和外压，答案不同，选型和报价都可能不同。"},{"t":"h2","x":"三、公称载荷与超载：125% 和 150% 的界线"},{"t":"p","x":"（书 §1.2.1）公称载荷是正常工作条件下允许使用的最大载荷，也就是设计值或样机实测后修正的值。超载载荷是瞬间或试验期间允许超过额定值、但不损坏、不失效、不失稳的承载能力。"},{"t":"p","x":"书里给了两条硬界线：**仪表弹性敏感元件，超载能力一般限定为额定载荷的 125%**；**工程中使用的波纹管类组件，一般限定在 150%**。如果工程要求大的安全系数，还可能规定“不允许任何超载”，这时载荷必须小于或等于额定值。"},{"t":"callout","kind":"key","title":"报价时怎么用","x":"客户说“工作压力 1.6 MPa”，你要追问：“有没有瞬时冲击？最高到多少？”如果他说“偶尔到 2.4 MPa”，那就是 150%，得按工程件核；如果只到 2.0 MPa，是 125%，可以按仪表件的思路谈。"},{"t":"h2","x":"四、位移：轴向、横向、角向，别混成一个"},{"t":"p","x":"（书 §1.2.1）位移是元件上某一特定点（自由端或中心）的位置变化，分线位移和角位移。金属波纹管可能产生**轴向位移、角向位移、横向位移**三种。额定位移是额定载荷下产生的位移，也就是正常工作允许的工作位移；超载位移是瞬间或试验期间允许超过额定位移的能力，仪表件一般限定在额定位移的 125%。"},{"t":"p","x":"注意：**额定位移不是“最大压缩量”**。最大压缩量是波纹互相压死时的位移，材料已经进入塑性，工作不能用。书里后文给的工作位移上限是允许位移的 40%–50%，这个我们下一课讲性能参数时再展开。"},{"t":"callout","kind":"warn","title":"图纸上写“压缩 10 mm”","x":"要问清：是工作行程 10 mm，还是装配时压到 10 mm？是单向压缩，还是反复循环？循环次数多少？这三个答案，决定寿命和报价。"},{"t":"h2","x":"五、弹性特性：线性、递增、递减"},{"t":"p","x":"（书 §1.2.1）弹性特性是位移与载荷之间的关系，必须在材料的弹性范围内。它可以是线性的，也可以是非线性的；非线性还分**递增特性**（越压越硬）和**递减特性**（越压越软）。"},{"t":"p","x":"仪表和测量装置一般追求线性，因为线性可以用简单的传动机构做等分刻度；工程件反而不强求线性，有时还利用递增特性做限位、利用递减特性做跳跃。销售听到“你的曲线直不直”，说的就是这件事。"},{"t":"callout","kind":"note","title":"一句话区分","x":"线性 = 压 1 mm 要 10 N，再压 1 mm 还是要 10 N；递增 = 第二毫米要 12 N；递减 = 第二毫米只要 8 N。"},{"t":"h2","x":"六、刚度：单位位移要多少力"},{"t":"p","x":"（书 §1.2.1，式 1-1）刚度是使元件产生单位位移所需的载荷。线性特性下：**K_F = F / w**（集中力刚度，N/mm）；**K_p = p / w**（压力刚度，MPa/mm）；**K_M = M / φ**（力矩刚度，N·mm/rad）。"},{"t":"table","head":["符号","名称","公式","单位","什么时候用"],"rows":[["K_F","集中力刚度","F / w","N/mm","用砝码、弹簧、气缸加载"],["K_p","压力刚度","p / w","MPa/mm","内压/外压驱动，算压力-位移"],["K_M","力矩刚度","M / φ","N·mm/rad","角向位移、扭矩驱动"]]},{"t":"p","x":"如果特性是非线性的，刚度不再是常数，而是曲线上某一点的斜率：**K_F = dF/dw**，**K_p = dp/dw**，**K_M = dM/dφ**（式 1-2）。所以客户说“刚度 20 N/mm”时，你要问一句：这是哪一段的刚度？线性段，还是工作点附近？"},{"t":"callout","kind":"tip","title":"粗算示例","x":"K_F = 20 N/mm，压缩 2 mm，需要 F = 20 × 2 = 40 N。反过来，客户要求“压 2 mm 只要 30 N”，那 K_F 最多 15 N/mm，你得改波数、壁厚或波深。"},{"t":"h2","x":"七、公称刚度与刚度允差：±5% 和 ±50% 差在哪"},{"t":"p","x":"（书 §1.2.1）公称刚度是设计计算给出的刚度，但它和实测值有误差，特别是非线性元件。书里建议：公称刚度最好不要直接用设计计算值，而要用样机测试后的修正值。"},{"t":"p","x":"一批产品里，每个元件的刚度都不一样，有一个分散范围。为了保证使用性能，要限定这个范围：**弹性敏感元件，刚度允差限定在公称值的 ±5% 以内；一般工程用波纹管类元件，可放宽到 ±50%**。"},{"t":"table","head":["类型","刚度允差","含义","对销售的影响"],"rows":[["仪表敏感元件","±5%","一批里几乎一致","要筛选、要标定，成本高"],["一般工程件","±50%","允许较大分散","报价低，但客户要接受现场调整"]]},{"t":"callout","kind":"warn","title":"客户说“刚度必须准”","x":"先问用途：是仪表测量，还是工程补偿？如果是仪表，±5% 意味着要配对、标定、可能报废一部分；这部分成本要写进报价，不能按普通件报。"},{"t":"h2","x":"八、灵敏度：刚度的倒数"},{"t":"p","x":"（书 §1.2.1，式 1-3）灵敏度是单位载荷产生的位移，用 δ 表示：**δ_F = w / F**，**δ_p = w / p**，**δ_M = φ / M**。线性特性下，灵敏度就是刚度的倒数：**δ = 1 / K**。"},{"t":"p","x":"所以“这个管子很软”和“这个管子很灵敏”是同一件事的两种说法。仪表要灵敏，就希望 δ 大、K 小；工程件要抗压、抗振，就希望 K 大、δ 小。客户说“太硬了，压不动”，翻译过来就是“灵敏度不够”。"},{"t":"callout","kind":"tip","title":"单位不要写反","x":"K 的单位是 N/mm，δ 的单位是 mm/N。报价单上写“灵敏度 0.05 mm/N”，等于“每牛压 0.05 毫米”，也就是 K = 20 N/mm。"},{"t":"h2","x":"九、有效面积：压力变成力的“换算系数”"},{"t":"p","x":"（书 §1.2.1）有效面积 A_e 是弹性元件在单位压力作用下、位移为零时，能转换成集中力的大小，量纲是 cm²。定义式：**A_e = F / p**（式 1-7）；更一般地，**F = (p − p₀) · A_e**（式 1-8），p₀ 是元件与支承刚接触时的压力。"},{"t":"p","x":"它还可以写成刚度之比：**A_e = K_F / K_p**（式 1-6）。为什么？因为压力刚度 K_p = dp/dw，集中力刚度 K_F = dF/dw，两者相除，位移消掉，剩下的就是“力/压力”，也就是面积。"},{"t":"p","x":"有效面积不是恒定的：它随工作压力变化，书里叫“不衡定性”。在力平衡式仪表里，要求同一批元件的有效面积尽量相等，所以生产时要**配对筛选**。"},{"t":"callout","kind":"tip","title":"算一遍就懂","x":"A_e = 8 cm² = 800 mm²，p = 0.6 MPa = 0.6 N/mm²，则 F = 0.6 × 800 = 480 N（约 49 kgf）。如果 p₀ = 0.1 MPa，则实际输出 F = (0.6 − 0.1) × 800 = 400 N。"},{"t":"callout","kind":"warn","title":"常见错误","x":"把 cm² 直接乘 MPa 得到 N——单位不统一，会差 100 倍。先把 cm² 换成 mm²，或把 MPa 换成 N/cm²（1 MPa = 100 N/cm²）。"},{"t":"h2","x":"十、寿命：静态和循环，差三个数量级"},{"t":"p","x":"（书 §1.2.1）弹性元件有两种工作状态：静态工作（载荷、位移基本不变）和循环工作（载荷、位移周期往复）。仪表敏感元件基本在弹性范围内静态工作，寿命很长，**一般数万次到数十万次**；工程中的波纹管类组件有时工作在弹塑性范围或交变应力下，**寿命只有成百上千次**。"},{"t":"table","head":["工作状态","典型产品","应力状态","寿命量级"],"rows":[["静态","压力表、传感器","弹性范围","数万–数十万次"],["循环","膨胀节、阀门密封","弹塑性/交变","数百–数千次"]]},{"t":"p","x":"循环工作时，必须给定许用工作寿命：循环次数、时间、频率，三个都要。只写“寿命 10 万次”不够——10 万次/分钟和 10 万次/年，是完全不同的设计。"},{"t":"h2","x":"十一、密封性：压差下不漏"},{"t":"p","x":"（书 §1.2.1）密封性是指元件在一定的内、外压差下保证不泄漏的性能。检测方法有气压密封性试验、渗漏试验、液体加压试验、用氦质谱检漏仪检测等。"},{"t":"p","x":"密封性和寿命是绑在一起的：波纹管寿命的定义，常常就是“到泄漏为止的循环次数”。所以客户说“寿命 5 年”，你要追问：这 5 年里允许泄漏率是多少？检漏方法是什么？"},{"t":"h2","x":"十二、自振频率：别和系统共振"},{"t":"p","x":"（书 §1.2.1）在振动环境下，必须防止元件的自振频率（特别是基频）与系统中任何一个振动源的频率接近，避免共振损坏。书里给的原则是：**波纹管的固有频率应低于系统振动频率，或至少比系统振频高出 50%**。"},{"t":"p","x":"举例：系统振频 50 Hz。固有频率要么低于 50 Hz，要么高于 75 Hz。落在 50–75 Hz 之间，就是危险区。销售听到“装上去就响、管子会抖”，第一反应就应该是频率匹配。"},{"t":"h2","x":"十三、使用温度：从 −196℃ 到 400℃"},{"t":"p","x":"（书 §1.2.1）波纹管类组件的使用温度范围很宽，设计制造前就要给定。书里举了两个极端：特殊用途波纹管内腔通过液氧（−196℃）或更低温度的液氮，耐压可达 25 MPa；管网系统用的大型膨胀节（公称直径有时超过 1 m），要求承压 4 MPa、耐温 400℃，还要有一定的耐腐蚀稳定性。"},{"t":"p","x":"温度不只影响材料强度，还影响刚度：温度升高，弹性模量下降，刚度和耐压力跟着降。所以同一根管子，常温标定 20 N/mm，到了 300℃ 可能只剩十几 N/mm。报价时客户给“工作温度”，你要问是介质温度、环境温度，还是二者都要。"},{"t":"h2","x":"十四、把十个指标填进一张表"},{"t":"table","head":["参数","符号/单位","谁给","客户没说时怎么问"],"rows":[["载荷","F(N)/p(MPa)/M(N·mm)","客户","多大压力？有没有冲击？内压还是外压？"],["位移","w(mm)/φ(rad)","客户","工作行程多少？单向还是循环？"],["弹性特性","线性/递增/递减","客户/我们","要不要等分刻度？允许非线性吗？"],["刚度","K(N/mm 等)","我们算","压到工作点要多少力？允许 ±5% 还是 ±50%？"],["灵敏度","δ(mm/N 等)","我们算","客户说的“软/硬”具体指什么？"],["有效面积","A_e(cm²)","我们算","压力怎么变成力？有没有配对要求？"],["寿命","次数/时间/频率","客户","多少年？每天动作多少次？"],["密封","泄漏率","客户","允许漏多少？用什么检漏？"],["自振频率","Hz","我们算","系统振频多少？有没有共振史？"],["温度","℃","客户","介质温度、环境温度、要不要保温？"]]},{"t":"callout","kind":"key","title":"销售现场版","x":"客户只给“压力 + 尺寸”时，不要马上报价。先补三问：**走多远、走多少次、什么温度**。这三问补齐，报价误差能少一大半。"},{"t":"h2","x":"十五、三个最常见错误"},{"t":"list","ordered":true,"items":["把最大压缩量当工作位移：最大压缩时波纹已经压死，材料进入塑性；工作位移只能取允许位移的 40%–50%。","只给压力，不给位移和寿命：同样的压力，行程 1 mm 和 10 mm 是两个产品，寿命要求 1 万次和 100 万次也是两个价格。","忽略温度对刚度的影响：常温算出来的 K，到了高温会变小；仪表类客户会直接表现为“读数漂了”。"]},{"t":"h2","x":"本课小结"},{"t":"p","x":"功能参数不是背名词，而是**把客户的一句话翻译成十个格子**。载荷、位移、弹性特性、刚度、灵敏度、有效面积、寿命、密封、自振频率、温度——每格填上，你才知道能不能做、大概什么价、风险在哪。下一课讲质量参数：非线性、迟滞、残余变形、热弹性误差和失稳，也就是“这批货稳不稳、测不测得过”。"}],"exam":{"pass":70,"minutes":15,"intro":"12 道题，覆盖功能参数、公式、单位与现场追问。答错会看到解释。","questions":[{"q":"功能参数主要回答什么问题？","opts":["能不能用","好不好看","便不便宜","好不好包装"],"a":0,"why":"功能参数判定元件能否满足使用要求；质量参数用于检测与质量评定。"},{"q":"仪表弹性敏感元件的超载能力一般限定为额定载荷的？","opts":["110%","125%","150%","200%"],"a":1,"why":"书里：仪表件一般 125%，工程件一般 150%。"},{"q":"工程用波纹管类组件的超载能力一般限定为？","opts":["125%","150%","175%","300%"],"a":1,"why":"书里：工程中使用的波纹管类组件一般限定在额定载荷的 150%。"},{"q":"线性特性下，集中力刚度 K_F 等于？","opts":["F/w","w/F","F·w","p·A_e"],"a":0,"why":"刚度是单位位移所需的力：K_F=F/w。"},{"q":"压力刚度 K_p 的单位是？","opts":["N/mm","MPa/mm","N·mm/rad","mm/N"],"a":1,"why":"K_p=p/w，压力单位 MPa 除以位移 mm，得到 MPa/mm。"},{"q":"灵敏度 δ 与刚度 K 的关系是？","opts":["δ=K","δ=1/K","δ=K²","δ=K/2"],"a":1,"why":"灵敏度是刚度的倒数：δ=w/F=1/K。"},{"q":"弹性敏感元件的刚度允差一般控制在？","opts":["±1%","±5%","±50%","±100%"],"a":1,"why":"书里：敏感元件 ±5% 以内；一般工程件 ±50% 以内。"},{"q":"有效面积 A_e 的定义式是？","opts":["A_e=F/p","A_e=p/F","A_e=F·p","A_e=K_p/K_F"],"a":0,"why":"有效面积是单位压力转换成的集中力：A_e=F/p；也可写成 K_F/K_p。"},{"q":"A_e=8 cm²，p=0.6 MPa，F 约为？","opts":["4.8 N","48 N","480 N","4800 N"],"a":2,"why":"8 cm²=800 mm²；0.6 MPa=0.6 N/mm²；F=0.6×800=480 N。"},{"q":"仪表敏感元件的寿命量级一般是？","opts":["数百次","数千次","数万到数十万次","无限次"],"a":2,"why":"静态、弹性范围内工作，寿命数万到数十万次；工程循环件常只有数百到数千次。"},{"q":"波纹管固有频率与系统振频的关系，书里建议？","opts":["必须相等","低于系统振频，或至少高出 50%","只要高于 10% 即可","没有要求"],"a":1,"why":"书里：固有频率应低于系统振频，或至少比系统振频高出 50%。"},{"q":"客户只给“压力 1.6 MPa、内径 32”，销售下一步最该追问？","opts":["颜色","位移、循环次数、温度","包装","付款方式"],"a":1,"why":"位移、寿命、温度直接决定选型与报价；只凭压力无法判断。"}]},"sources":[{"t":"徐开先主编《波纹管类组件的制造及其应用》§1.2.1 功能参数（1998）","u":""},{"t":"同上 §2.1.2 波纹管的性能参数（工作位移、耐压力、寿命）","u":""}]},"3":{"title":"质量参数：非线性、迟滞、残余变形、失稳","sub":"同样一批波纹管，为什么有的装上去读数准、有的用三个月就漂？答案藏在四条曲线和一次失稳里。","tags":["第1章","质量参数","非线性","迟滞","残余变形","失稳"],"objectives":["分清非线性度、弹性迟滞、残余变形、热弹性误差四个质量指标","会读加载-卸载曲线，知道曲线围成的环在说什么","记住 η、ξ、λ 三个百分数的定义和算法","理解温度误差 η_t=β_E·t，知道为什么选低 β_E 材料","能区分平面失稳和柱失稳，知道怎么在图纸上避免"],"blocks":[{"t":"lead","x":"上一课讲功能参数，回答“能不能用”。这一课讲质量参数，回答另外两个问题：**这批货稳不稳？测不测得过？** 客户说“你的管子装上去读数漂”“用一段时间回不到零位”“一加压就歪”，说的都是这一课的内容。"},{"t":"figure","name":"qualityLoop","cap":"加载与卸载不是同一条线；η、ξ、λ 量的就是这条缝"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["η","希腊字母 eta","%","非线性度：曲线偏离直线多少"],["ξ","希腊字母 xi","%","弹性迟滞：加、卸载两条路差多少"],["λ","希腊字母 lambda","%","残余变形：卸荷后回不到零位多少"],["β_E","beta 下标 E","1/°C","热弹性系数：温度每变 1°C，模量变多少"],["E_t","E 下标 t","MPa","温度 t 时的弹性模量"],["w_max","w 下标 max","mm","最大位移，常做分母"]]},{"t":"h2","x":"一、先看一条曲线：加载和卸载不重合"},{"t":"p","x":"拿一根波纹管，从 0 加载到最大载荷，再卸载回 0，把“载荷-位移”点画出来。理想弹性元件，加载和卸载是同一条直线，原路去原路回。真实的波纹管，卸载曲线会落在加载曲线下方，围成一个环。"},{"t":"p","x":"这个环，书里叫**弹性迟滞**。环的宽度，就是同一载荷下加载与卸载的位移差；环没有完全闭合、回到零位需要等一会儿，叫**弹性后效**。实际测量时两者叠加，无法分开，统称滞后。"},{"t":"callout","kind":"key","title":"记住这张图","x":"加载走上面、卸载走下面，中间围出的面积就是能量损耗；环越宽，迟滞越大，仪表越不准、发热越多。"},{"t":"h2","x":"二、非线性度 η：曲线偏离直线多少"},{"t":"p","x":"（书 §1.2.2，式 1-9）当位移与载荷的关系偏离理想直线，就叫非线性。偏离量用**非线性度 η** 表示：实际特性与线性特性的最大偏差 Δ_max，除以最大位移 w_max，再乘 100%：**η = Δ_max / w_max × 100%**。"},{"t":"p","x":"非线性度是一个**系统误差**，测出来以后可以确知、可以补偿。工程用波纹管类组件，非线性常常可以忽略；但仪表用敏感元件，必须测试和补偿，否则读数精度上不去。"},{"t":"callout","kind":"tip","title":"算一遍","x":"最大位移 10 mm，曲线偏离直线最多 0.2 mm，则 η = 0.2 / 10 × 100% = 2%。客户说“精度 1%”，你就要问：是满量程 1%，还是读数 1%？"},{"t":"h2","x":"三、弹性迟滞 ξ：来回走不是同一条路"},{"t":"p","x":"（书 §1.2.2，式 1-10）弹性迟滞用相同载荷下加、卸载位移的最大差值 (w₁ − w₁′)_max，除以最大位移 w_max：**ξ = (w₁ − w₁′)_max / w_max × 100%**。"},{"t":"p","x":"迟滞的来源是材料微观结构缺陷、内摩擦、残余应力等。它和**弹性后效**同时发生：载荷停止变化或卸掉后，位移不是立刻到位，而是过一段时间才慢慢回复。仪表指针卸掉载荷后不能马上回零，就是后效。"},{"t":"p","x":"对销售意味着什么：客户如果做精密测量，迟滞是硬指标；如果只是做热膨胀补偿，迟滞大一点通常能接受，但会带来发热和寿命问题。"},{"t":"h2","x":"四、残余变形 λ：卸载后回不到原处"},{"t":"p","x":"（书 §1.2.2，式 1-11）加载产生位移，卸载后经过相当长时间仍不能回复原始位置，留下的永久变形叫残余变形。用零位偏移量 Δw₀ 与最大位移 w_max 的百分比表示：**λ = Δw₀ / w_max × 100%**。"},{"t":"p","x":"残余变形是判定“变形能力”的参数。对敏感元件，达到额定位移后如果残余位移大，测量精度就保不住；对工程件（比如膨胀节），有时故意让它工作在弹塑性区换大位移，只要寿命够、不失效，残余变形可以不再考虑。"},{"t":"callout","kind":"warn","title":"客户说“用久了短了一截”","x":"这就是残余变形。先问：工作位移是不是超过了允许位移的 40%–50%？有没有长期超载？安装时有没有预压缩过头？"},{"t":"h2","x":"五、热弹性误差：温度一高，刚度就变"},{"t":"p","x":"（书 §1.2.2，式 1-12）温度变化时，材料弹性模量随之变化：**E_t = E₀ (1 − β_E · Δt)**。E_t 是温度 t 时的模量，E₀ 是初始温度模量，β_E 是弹性模量温度系数，Δt = t − t₀。"},{"t":"p","x":"刚度 K = c·E（c 是比例常数），所以温度引起的相对误差可以写成：**η_t = β_E · t**（式 1-13）。也就是说，温度误差和 β_E 成正比：β_E 越小，温度漂移越小。"},{"t":"table","head":["材料","β_E（/℃）","100℃ 时的相对误差（近似）"],"rows":[["黄铜 H80","4.8×10⁻⁴","4.8%"],["锡磷青铜 QSn6.5-0.4","4.8×10⁻⁴","4.8%"],["铍青铜 QBe2","3.1×10⁻⁴","3.1%"],["不锈钢 1Cr18Ni9Ti","3.5×10⁻⁴","3.5%"],["精密弹性合金 3J1","2.0×10⁻⁴","2.0%"],["恒弹性合金 3J53","1.0×10⁻⁵","0.1%"]]},{"t":"p","x":"表的读法：用 1Cr18Ni9Ti 做仪表件，温度从 20℃ 升到 120℃，Δt=100℃，相对误差约 3.5%。如果客户要求 1% 精度，这个材料就不够，要换 3J53 一类低 β_E 合金，或者做温度补偿。"},{"t":"p","x":"（书 §1.2.2）另一头是线膨胀：l_t = l₀(1 + α·Δt)（式 1-14）。α 一般在 10⁻⁶ 量级，比 β_E 小两个数量级，所以热胀冷缩引起的尺寸误差通常可以忽略，**温度误差主要来自模量变化，不是尺寸变化**。"},{"t":"callout","kind":"key","title":"一句话","x":"温度漂移，先看 β_E，不要先怪热胀冷缩。选低 β_E 材料，比改结构更有效。"},{"t":"h2","x":"六、失稳：还没到屈服，形状先垮了"},{"t":"p","x":"（书 §1.2.2）弹性元件在载荷 F 或 p 作用下会失稳。波纹管有两种：**平面失稳**——波纹环板平面翘曲、变形、波距不均匀；**柱失稳**——整根波纹管轴线弯曲，偏离原来的直线。"},{"t":"p","x":"关键点：失稳发生的那一刻，应力常常**还没到屈服强度**，甚至低于弹性极限。所以它不是“压坏了”，而是“形状突然垮了”。除了跳跃膜片故意利用失稳做两位式开关，其它元件都要避免。"},{"t":"p","x":"书里给了三条防止措施：设计时避免元件过长过薄；长波纹管使用时用心轴或拉杆保护；承载时载荷加在中心位置，防止偏斜。"},{"t":"table","head":["类型","表现","典型原因","预防"],"rows":[["平面失稳","波纹翘曲、波距不均","壁厚太薄、压力高、波形不好","加厚、减小波深、加加强环"],["柱失稳","整根轴线弯曲","L₀/D 太大、侧向力、安装偏斜","L₀≤1.3D、加导向、心轴/拉杆"]]},{"t":"h2","x":"七、四个指标怎么测：一张验收表"},{"t":"table","head":["指标","符号","怎么测","常见验收写法"],"rows":[["非线性度","η","加载到满量程，画曲线，量最大偏差","≤2% FS（满量程）"],["弹性迟滞","ξ","加、卸载各一遍，量同载荷位移差","≤1.5% FS"],["残余变形","λ","加载到额定，卸载静置后量零位偏移","≤0.5% FS"],["热弹性误差","η_t","恒温箱里测不同温度的刚度/位移","−20–80℃ 内 ≤±2%"]]},{"t":"p","x":"注意：这些验收值不是书里给的统一标准，而是举例。真实项目要按客户图纸、GB/T 12777 或双方技术协议写。销售不要在报价单上随便写“精度 1%”，先问检验方法和环境。"},{"t":"h2","x":"八、质量参数和功能参数的关系"},{"t":"p","x":"功能参数是“设计目标”，质量参数是“实现得好不好”。比如：客户要 K=20 N/mm（功能），一批货做出来 18–22 N/mm，这是刚度允差；同时曲线弯、来回不重合、卸载回不到零，这些是质量参数。功能达标不代表质量达标，两者要分开验。"},{"t":"callout","kind":"tip","title":"销售问法","x":"“你们验收是按功能参数还是质量参数？抽检还是全检？有没有曲线报告？”这三个问题能看出客户是懂行还是只想压价。"},{"t":"h2","x":"九、三个常见误区"},{"t":"list","ordered":true,"items":["把非线性度当成“误差百分比”：η 是相对最大位移的，不是相对读数；满量程 1% 和读数 1% 差很多。","忽略迟滞和残余变形的区别：迟滞是来回不重合、会回复；残余变形是回不到零位、留下永久偏移。","把失稳当成强度不够：失稳时应力可能远低于屈服，加厚不一定解决，改 L₀/D、加导向往往更有效。"]},{"t":"h2","x":"本课小结"},{"t":"p","x":"质量参数是四条曲线加一次失稳：非线性度看曲线直不直，迟滞看来回重不重合，残余变形看卸载后回不回得去，热弹性误差看温度变了刚度变多少；失稳看形状什么时候突然垮。下一课讲材料和标准：同样叫“不锈钢”，304、316L、321 在波纹管里完全不是一回事。"}],"exam":{"pass":70,"minutes":15,"intro":"11 道题，覆盖四个质量指标、公式和失稳判断。","questions":[{"q":"非线性度 η 的定义是？","opts":["Δ_max/w_max×100%","w_max/Δ_max×100%","F/w","p/w"],"a":0,"why":"η 是实际特性对线性特性的最大偏差除以最大位移。"},{"q":"非线性度属于哪类误差？","opts":["随机误差","系统误差","人为误差","安装误差"],"a":1,"why":"书里：非线性度是一个系统误差，测试分析后可以确知并补偿。"},{"q":"弹性迟滞指的是？","opts":["加载和卸载曲线不重合","管子生锈","管子太长","压力太高"],"a":0,"why":"同一载荷下正反行程位移不一致，形成迟滞环。"},{"q":"残余变形 λ 用什么表示？","opts":["Δw₀/w_max×100%","w_max/Δw₀×100%","F·w","p·A_e"],"a":0,"why":"λ=零位偏移量/最大位移×100%。"},{"q":"残余变形主要判定什么能力？","opts":["变形能力","导电能力","焊接能力","抛光能力"],"a":0,"why":"书里：残余变形是判定弹性元件变形能力的参数。"},{"q":"温度引起弹性元件相对误差的近似式是？","opts":["η_t=β_E·t","η_t=α·t","η_t=E·t","η_t=K·t"],"a":0,"why":"式 1-13：η_t=β_E·t；β_E 是弹性模量温度系数。"},{"q":"下列材料中 β_E 最小、温度漂移最小的是？","opts":["黄铜 H80","铍青铜 QBe2","不锈钢 1Cr18Ni9Ti","恒弹性合金 3J53"],"a":3,"why":"3J53 的 β_E 约 1.0×10⁻⁵/℃，比其它几种小一个数量级以上。"},{"q":"1Cr18Ni9Ti 从 20℃ 升到 120℃，相对温度误差约？","opts":["0.35%","3.5%","35%","350%"],"a":1,"why":"β_E≈3.5×10⁻⁴/℃，Δt=100℃，η_t≈3.5×10⁻²=3.5%。"},{"q":"平面失稳的典型表现是？","opts":["整根轴线弯曲","波纹环板翘曲、波距不均","管子断裂","焊缝气孔"],"a":1,"why":"平面失稳是波纹环板平面翘曲、变形、波距不均匀；柱失稳才是整根轴线弯曲。"},{"q":"失稳发生时的应力通常？","opts":["已达到抗拉强度","还没到屈服强度","一定超过屈服","与应力无关"],"a":1,"why":"书里：失稳瞬间应力常未达到屈服强度，甚至低于弹性极限。"},{"q":"防止长波纹管柱失稳，书里建议？","opts":["加长","减薄","用心轴或拉杆保护","提高压力"],"a":2,"why":"书里：长波纹管使用时应采用心轴或拉杆保护，并避免过长过薄。"}]},"sources":[{"t":"徐开先主编《波纹管类组件的制造及其应用》§1.2.2 质量参数（1998）","u":""},{"t":"同上 §1.2.2 表 1-1 弹性模量温度系数","u":""}]},"4":{"title":"材料与标准：同样叫不锈钢，为什么报价差三倍","sub":"客户图纸上写 304、316L、321，价格能差一倍；写“不锈钢”三个字，等于没写。这一课把选材变成四个问题。","tags":["第1章","材料","不锈钢","铜合金","精密合金","标准"],"objectives":["用介质、温度、寿命、制造四个问题缩小材料范围","分清冷作硬化、淬火回火、弥散硬化三类材料","记住 304、316L、321 的区别和各自禁区","会做旧牌号到新牌号的对照","知道 GB/T 12777-2019 等现行标准怎么用"],"blocks":[{"t":"lead","x":"同样一张波纹管图纸，材料写 304 报一个价，写 316L 报另一个价，写 321 再贵一截。客户常问“不都是不锈钢吗，为什么差这么多？”这一课把“选材”拆成四个问题，让你能当场回答，而不是背牌号。"},{"t":"figure","name":"materialMap","cap":"先看工况，再看牌号；越往右上，价格越高"},{"t":"callout","kind":"note","title":"这一课接在哪","x":"第 3 课讲偏差从哪来；这一课讲材料为什么会让偏差、寿命和报价差三倍。"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["σ_s","sigma 下标 s","MPa","屈服强度：开始塑性变形的应力"],["σ_b","sigma 下标 b","MPa","抗拉强度：拉断前的最大应力"],["σ_0.2","sigma 下标 0.2","MPa","规定非比例伸长 0.2% 的应力"],["E","大写 E","MPa","弹性模量：材料有多“硬”"],["HV","H 加 V","—","维氏硬度，常用来估耐磨/加工性"]]},{"t":"h2","x":"一、选材先问四件事，不是先背牌号"},{"t":"p","x":"（书 §1.4.1）书里列了六项基本要求：良好的塑性、高的弹性极限和抗拉强度及疲劳强度、好的焊接性、弹性性能稳定、较好的耐腐蚀稳定性，以及成本可接受。翻译成销售能问的话，就是四件事："},{"t":"kv","items":[["介质","有没有氯离子、酸、碱、海水？会不会点蚀、应力腐蚀？"],["温度","最低多少、最高多少？有没有冷热交变？"],["寿命","静态补偿还是高频循环？要求多少万次？"],["制造","多薄、多深、要不要焊？焊后能不能固溶？"]]},{"t":"callout","kind":"key","title":"顺序不能反","x":"先定工况，再定材料，最后才谈价格。反过来先问“316L 多少钱一公斤”，很容易选错。"},{"t":"h2","x":"二、材料变硬的三条路"},{"t":"p","x":"（书 §1.4.4）弹性材料按“怎么获得弹性”分三类，这是理解所有牌号的骨架："},{"t":"table","head":["类型","怎么变硬","代表材料","特点","典型用途"],"rows":[["冷作硬化型","成形时塑性变形，加工硬化","黄铜 H80、锡青铜 QSn6.5、304/321 不锈钢","工艺简单、成形后一般不用专门热处理；弹性不高、残余应力大","普通波纹管、膜片、补偿器"],["淬火回火型","淬火 + 回火","65、75、65Mn、60Si2Mn、50CrVA","弹性和强度很高；塑性低，难做复杂形状","螺旋弹簧、片簧（不是波纹管）"],["弥散硬化型","淬火 + 时效析出","QBe2、3J1、3J21、3J53、Inconel 718","淬火态塑性好、可做复杂形状；时效后强度高、滞后小","精密波纹管、膜盒、仪表弹性元件"]]},{"t":"p","x":"记住一句话：**波纹管大多是冷作硬化型或弥散硬化型；淬火回火型主要做弹簧，不做波纹管。** 客户拿弹簧钢牌号来问波纹管，先确认他是不是把零件搞混了。"},{"t":"h2","x":"三、铜合金：便宜、好成形，但怕高温和腐蚀"},{"t":"table","head":["牌号","强化方式","书里典型性能","优点","边界"],"rows":[["H80 黄铜","冷作硬化","硬态 σb 610–680 MPa，软态 310 MPa；E 11.2×10⁴ MPa","塑性极好、可深拉、便宜","强度低、迟滞大；不耐氨和海水"],["QSn6.5-0.1/0.4 锡青铜","冷作硬化","硬态 σb 700–800 MPa，软态 350–450 MPa；E 11.2×10⁴ MPa","强度较高、耐蚀一般、焊接性好","高温蠕变；长期使用温度不宜太高"],["QBe2 铍青铜","弥散硬化","硬态 σb 1300–1400 MPa；E 13.5×10⁴ MPa；时效 300–350℃/2h","强度、弹性、疲劳、蠕变抗力都好","贵；铍粉尘有毒，加工要防护"],["NCu28-2.5-1.5 蒙乃尔","固溶/冷作","硬态 σb 590–770 MPa；耐蚀耐热到约 400℃","耐海水、耐多种介质","成本高；加工硬化快"]]},{"t":"p","x":"铜合金的报价优势很明显，但两个坑要提前说：① 氨、胺、海水里会应力腐蚀；② 温度一高就软，100℃ 以上长期用要重新算。"},{"t":"h2","x":"四、不锈钢：304、316L、321 到底差在哪"},{"t":"p","x":"（书 §1.4.4）书里的老牌号是 1Cr18Ni9Ti（≈321）、0Cr18Ni9（≈304）、00Cr17Ni14Mo2（≈316L）、Cr18Ni12Mo2Ti（≈316/316Ti）。先看这张对照表，再看区别："},{"t":"table","head":["书里旧牌号","现在常说","关键合金元素","核心优势","主要禁区"],"rows":[["1Cr18Ni9Ti","321","Ti 稳定化","耐晶间腐蚀、可焊、高温强度较好","不含 Mo，氯离子点蚀/缝隙腐蚀差"],["0Cr18Ni9","304 / 304L","18Cr-8Ni","通用、便宜、成形好","氯离子应力腐蚀开裂；焊接厚件需 304L"],["00Cr17Ni14Mo2","316L","Mo 2–3%，超低碳","耐点蚀、耐氯离子、焊后耐蚀好","不耐浓盐酸；成本高"],["Cr18Ni12Mo2Ti","316 / 316Ti","Mo + Ti","耐蚀 + 稳定化，适合高温焊接件","Ti 不是万能，仍怕高氯"]]},{"t":"p","x":"三个区别要能脱口而出："},{"t":"list","ordered":true,"items":["**321 有钛、没有钼**：耐晶间腐蚀和高温，但不耐氯离子点蚀。客户说“海边用 321”，要提醒。","**316L 有钼、超低碳**：耐氯离子点蚀和焊后晶间腐蚀，是化工/海水的常用选择；但浓盐酸、浓硫酸不行。","**304 最便宜、最通用**：室内、淡水、一般大气可以；含氯、焊接厚件、低温冲击要慎重。"]},{"t":"callout","kind":"warn","title":"304 的经典事故","x":"用 304 做海水或含氯清洗液里的波纹管，几个月就点蚀穿孔。不是“不锈钢”三个字不管用，是 304 的钼含量为 0，扛不住氯离子。"},{"t":"h2","x":"五、精密合金与高温合金：贵，但解决普通不锈钢解决不了的问题"},{"t":"table","head":["牌号","类型","书里典型性能","解决什么问题"],"rows":[["3J1 (Ni36CrTiAl)","铁基弥散硬化","σb 1196 MPa，σ0.2 980 MPa，E 21×10⁴ MPa，软态 δ 35%","高弹性、低滞后、可做复杂波纹管/膜盒"],["3J21","钴基弥散硬化","σb 2538 MPa，E 20.7×10⁴ MPa，无磁，约 400℃","高负荷、耐蚀、无磁的精密弹性元件"],["3J53","恒弹性合金","σb 1372 MPa，E 18.5×10⁴ MPa，β_E 约 1×10⁻⁵/℃","温度漂移极小的精密仪表、谐振元件"],["Inconel 718","镍基时效","高强度、耐疲劳、耐蚀，约 650℃ 以内","高温、高强、疲劳工况"],["Inconel 625","镍基固溶","耐点蚀/缝隙腐蚀、耐高温氧化","海水、化工、高温腐蚀"]]},{"t":"p","x":"精密合金贵在“稳定”：3J53 的弹性模量温度系数比 1Cr18Ni9Ti 小两个数量级，温度从 20℃ 到 120℃，普通不锈钢漂 3.5%，3J53 只漂约 0.1%。客户要求高精度，材料费不能省。"},{"t":"h2","x":"六、标准：客户写旧版，你要知道新版"},{"t":"p","x":"（书 §1.7）书是 1998 年的，引用的标准很多已经换版。报价和图纸评审时，先确认版本："},{"t":"table","head":["书里写的","现行版本","管什么"],"rows":[["GB/T 12777-91","GB/T 12777-2019","金属波纹管膨胀节通用技术条件"],["GB/T 14525-93","GB/T 14525-2010","波纹金属软管通用技术条件"],["—","ISO 10380:2012","波纹金属软管（国际）"],["—","ASTM E595","出气性能（航天/真空）"],["—","ASTM G28","镍基合金晶间腐蚀试验（C-22 等）"]]},{"t":"p","x":"标准不是拿来背的，是拿来“对答案”的：客户图纸引用哪个标准，你就查那个标准的版本、试验方法、合格判据。版本不对，检验方法可能完全不同。"},{"t":"callout","kind":"tip","title":"报价前一句话","x":"“您这张图引用的 GB/T 12777 是哪一版？焊缝检测按 RT 还是 PT？”这一问，能看出客户的技术底气，也能避免后面扯皮。"},{"t":"h2","x":"七、选材矩阵：把工况填进去"},{"t":"table","head":["工况","首选","备选","不要用"],"rows":[["干燥空气/氮气，常温","304","321","—"],["自来水/一般工业水","304L","316L","长期停滞的 304"],["含氯离子、海水","316L","625 / 钛","304、321"],["浓盐酸","钛/625/衬氟","—","304/316L"],["−196℃ 低温","304L/316L","321","普通碳钢"],["400–700℃","321/316Ti","625/718","304 长期高温"],["高周疲劳（10⁶ 次以上）","316L/3J1","718","焊缝质量不稳的薄壁件"],["精密仪表、低温度漂移","3J53","3J1","H80、304"],["超高真空","316L 电解抛光","625","多孔、未清洗件"]]},{"t":"callout","kind":"warn","title":"矩阵不是标准答案","x":"真实选材还要看浓度、温度、流速、缝隙、焊接、清洗。矩阵只用来快速排除明显错误，不能代替客户确认。"},{"t":"h2","x":"八、三个常见误区"},{"t":"list","ordered":true,"items":["**“不锈钢都不生锈”**：304 在氯离子环境会点蚀，316L 在浓盐酸里也不行；材料耐蚀是“针对介质”的。","**“321 比 316L 高级”**：321 耐高温晶间腐蚀，316L 耐氯离子点蚀，方向不同，不能互相替代。","**“牌号对就行”**：同一牌号有软态、硬态、不同冷作率，强度能差一倍；图纸要写状态和热处理，不能只写牌号。"]},{"t":"h2","x":"九、报价前怎么问"},{"t":"steps","items":["介质：具体成分、浓度、温度、是否含氯离子/酸碱。","工况：静态还是循环？压力、位移、频率、要求寿命。","制造：多薄、多深、是否焊接？焊后能否固溶/稳定化？","检验：按哪个标准、什么版本、RT/PT/氦检/腐蚀试验？","表面：酸洗、钝化、电解抛光、涂层？"]},{"t":"p","x":"这五个问题问完，材料基本就锁定了。下一课讲制造工艺：同样的材料，液压成形、焊接、电沉积做出来的波纹管，性能和价格完全不是一回事。"}],"exam":{"pass":70,"minutes":15,"intro":"12 道题，覆盖三类强化方式、常用牌号、标准版本和选材判断。","questions":[{"q":"波纹管最常用的两类材料强化方式是？","opts":["冷作硬化和弥散硬化","淬火回火和冷作硬化","渗碳和氮化","铸造成形"],"a":0,"why":"书里：波纹管多用冷作硬化型（不锈钢、铜合金）和弥散硬化型（铍青铜、精密合金）。"},{"q":"下列哪种材料主要做弹簧，不做波纹管？","opts":["QBe2","60Si2Mn","316L","3J53"],"a":1,"why":"60Si2Mn 是淬火回火型弹簧钢，塑性低，不适合复杂波纹管。"},{"q":"321 与 316L 的关键区别是？","opts":["321 含钼，316L 不含","321 含钛稳定化、不含钼；316L 含钼、超低碳","两者完全相同","321 是铜合金"],"a":1,"why":"321 用 Ti 稳定化，耐晶间腐蚀/高温；316L 用 Mo 提高耐氯离子点蚀，超低碳利于焊接。"},{"q":"海水环境优先选？","opts":["304","321","316L","H80"],"a":2,"why":"316L 含钼，耐氯离子点蚀；304/321 不含钼，易点蚀。"},{"q":"QBe2 的强化方式是？","opts":["冷作硬化","淬火回火","弥散硬化（时效）","固溶"],"a":2,"why":"铍青铜淬火后塑性好，时效析出强化，属于弥散硬化型。"},{"q":"3J53 的核心优势是？","opts":["最便宜","弹性模量温度系数极小","强度最低","耐浓盐酸"],"a":1,"why":"3J53 是恒弹性合金，β_E 约 1×10⁻⁵/℃，用于低温度漂移的精密元件。"},{"q":"书里的 1Cr18Ni9Ti 大致对应现在的？","opts":["304","316L","321","430"],"a":2,"why":"1Cr18Ni9Ti 含 Ti 稳定化，对应 321 系列。"},{"q":"书里的 00Cr17Ni14Mo2 大致对应？","opts":["304","316L","321","17-4PH"],"a":1,"why":"含 Mo 2–3%、超低碳，对应 316L。"},{"q":"GB/T 12777 的现行版本是？","opts":["1991","2019","2010","2023"],"a":1,"why":"GB/T 12777-2019 现行，替代 1991 版。"},{"q":"316L 在下列哪种介质中仍可能不耐蚀？","opts":["自来水","海水","浓盐酸","大气"],"a":2,"why":"316L 耐氯离子点蚀，但浓盐酸会破坏钝化膜，需用钛/625/衬氟。"},{"q":"同牌号材料，为什么强度能差一倍？","opts":["颜色不同","冷作硬化状态/热处理不同","产地不同","包装不同"],"a":1,"why":"软态、半硬、硬态的冷作率不同，强度和塑性差别很大；图纸要写状态。"},{"q":"选材矩阵的作用是？","opts":["替代客户确认","快速排除明显错误","决定价格","替代标准"],"a":1,"why":"矩阵只是快速筛选，真实选材还要看浓度、温度、焊缝、清洗等具体条件。"}]},"sources":[{"t":"徐开先主编《波纹管类组件的制造及其应用》§1.4 材料（1998）","u":""},{"t":"同上 §1.7 标准简介；GB/T 12777-2019、GB/T 14525-2010、ISO 10380:2012","u":""}]},"5":{"title":"制造工艺总览：同样一张图，为什么有人报 800、有人报 3000","sub":"材料一样、尺寸一样，价格差三倍，差在“用什么方法把它做出来”。这一课把成形、连接、热处理、检测四条线一次讲清。","tags":["第1章","制造工艺","液压成形","焊接","电沉积","成本"],"objectives":["说出波纹管制造的两大步骤：成形 + 组装","分清液压、机械、焊接、电沉积四条成形路线及适用边界","理解熔焊与钎焊的差别，知道焊缝为什么是薄弱点","知道热处理和稳定化处理各自解决什么问题","拿到图纸能判断大致工艺路线和报价差异来源"],"blocks":[{"t":"lead","x":"客户拿同一张图问三家，一家报 800，一家报 1800，一家报 3000。材料都一样，尺寸都一样，差别不在“谁想多赚”，而在**工艺路线**：是用液压胀出来，还是焊出来，还是电沉积做出来；焊缝检不检；热处理做不做。这一课把路线图铺开。"},{"t":"figure","name":"processChoice","cap":"先看硬约束，再选路线；路线错，价格和交期差一个数量级"},{"t":"callout","kind":"note","title":"这一课接在哪","x":"第 4 课选材料；这一课讲同样的材料怎么变成波纹，以及为什么同样一张图交期差这么多。"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["k","小写 k","无量纲","波深系数 k=D/d"],["h₀","h 下标 0","mm","单层壁厚，不是总厚"],["D","大写 D","mm","外径"],["d","小写 d","mm","内径"],["t","小写 t","mm","波距；普通图纸里 t 是厚度，别混"],["L₀","L 下标 0","mm","有效长度，不含端部"]]},{"t":"h2","x":"一、所有波纹管都分两步：先成形，再组装"},{"t":"p","x":"（书 §1.3）书里说得很清楚：弹性元件的制造工艺一般包括两个步骤，一是元件的**成形工艺**，二是把成形元件**组装为成品**。成形通过冲压、拉伸、弯曲、绕制等工序，得到形状和尺寸；组装包括与端部配件、法兰、接管的连接。"},{"t":"p","x":"成形时有两个必须考虑的点：① 冷作硬化型材料必须达到一定的塑性变形量，才能保证强度；② 要考虑材料的弹性回复，模具要留回弹量。这两点决定了“同样的图，不同厂做出来不一样”。"},{"t":"h2","x":"二、成形四条主路线"},{"t":"table","head":["路线","怎么做","最适合","优点","代价/边界"],"rows":[["液压成形","管坯放进模具，两端轴向压缩 + 内部充液，让管壁胀进波谷","薄壁、长管、k=1.3–1.5 的浅波","整体无缝、成形质量好、适合批量","模具和液压设备贵；壁厚减薄、起皱要控制"],["机械成形（滚压/胀形/旋压）","用滚轮、芯模或旋压头逐段压出波形","短件、浅波、小批量","模具简单、调整灵活","回弹和椭圆度难控；深波易裂"],["焊接成形","薄板卷管焊纵缝，再胀形；或直接焊成波纹（焊接波纹管）","k≥2 的深波、大直径、特殊材料","可做很深/很大的波；材料选择宽","焊缝是薄弱点；要检漏、检熔深；工时高"],["电沉积（电铸）","在芯模上电沉积镍/钴，再脱模","极薄、极小直径、无缝、高精度","无焊缝、壁厚均匀、可做极薄","周期长、成本高、槽液环保要求高"]]},{"t":"callout","kind":"key","title":"k 值是第一道分流","x":"k=D/d≤1.5 优先液压；1.6–1.9 深波要考虑两次成形或焊接；k≥2 液压很难，通常走焊接或电沉积。"},{"t":"p","x":"书里还提到，冷作硬化型材料成形后一般不需要专门热处理，但残余应力大、弹性特性随时间温度变化；弥散硬化型材料（铍青铜、精密合金）淬火态塑性好，成形后再时效，能得到高弹性、低滞后。这就是为什么同样形状，材料不同，工艺顺序完全不同。"},{"t":"h2","x":"三、连接：熔焊、钎焊，还是先焊后成形？"},{"t":"p","x":"（书 §1.3）薄壁件焊接大多采用滚轮短脉冲焊、氩弧焊、电容储能焊，电子束焊也有应用；壁厚更薄时可用微束等离子焊、激光焊、光束焊。原则是：**让板材只在一个窄小区域受热**，不使其它部位组织变化。"},{"t":"table","head":["方法","热输入","强度/气密","适用","注意"],"rows":[["滚轮短脉冲焊","低、局部","好","薄板纵缝、批量","焊轮压力/脉冲参数要稳"],["氩弧焊（TIG）","中","好","接管、法兰、修补","薄壁易烧穿；要背面保护"],["电容储能焊","很低、极短","较好","薄片点焊/缝焊","适合搭接，不适合对接"],["电子束/激光","很集中","好","精密、薄壁、深熔","设备贵；装夹精度要求高"],["钎焊","低","较低","单件小批、异种材料","焊剂可能腐蚀基体；强度低"]]},{"t":"p","x":"顺序也是成本点：先焊法兰再成形，焊缝要跟着变形，容易裂；先成形再焊，工装复杂但焊缝质量好。客户图纸如果规定“先焊后胀”，报价要加钱。"},{"t":"h2","x":"四、热处理：三个目的，别混在一起"},{"t":"p","x":"（书 §1.3）热处理要防止变形，元件应放在专用器具里；为避免氧化，要在保护气氛炉或真空炉中做。热处理规范选错，性能反而更差。"},{"t":"list","ordered":true,"items":["**固溶/恢复塑性**：300 系不锈钢常规在 1040–1120℃ 固溶后快冷，把加工硬化和析出物溶回去，恢复塑性和耐蚀性。","**稳定化**：321/347 这类含 Ti/Nb 的钢，在 850–900℃ 保温，让碳化钛/铌析出，避免晶界贫铬。","**时效强化**：QBe2 约 300–350℃/2h；3J1 约 650–750℃/2–4h；3J53/3J58 约 500–650℃/2–4h（书表 1-30）。"]},{"t":"callout","kind":"warn","title":"别把“去应力”当万能","x":"去应力退火温度不够，残余应力还在；温度过高，材料又软化。客户要求“处理后不变形”，要问清是去应力、固溶还是时效。"},{"t":"h2","x":"五、稳定化处理：让产品“用久了不变”"},{"t":"p","x":"（书 §1.3）为消除制造过程中的内应力，波纹管通常要进行稳定化处理，方法有交变载荷处理、长期超载处理、机械稳定处理。规范（温度、时间、加载方式、循环次数）要根据工作条件定。"},{"t":"p","x":"直白说：就是在出厂前，先让零件“经历一遍它以后要受的罪”，把会发生的塑性变形和应力松弛提前释放掉，这样客户装上去零位才稳。"},{"t":"h2","x":"六、检测：成品要过几道关"},{"t":"p","x":"（书 §1.3）成品要经过尺寸检查和性能检验，包括弹性特性、强度、工作温度和压力、位移量等；特殊环境还要做气密性、耐蚀性、疲劳强度、抗超载和极限应用数据等试验。"},{"t":"table","head":["检验项","怎么检","常见判据（举例，按协议）"],"rows":[["尺寸/外观","卡尺、投影仪、目视","波距、波深、总长、焊缝成形"],["刚度/弹性特性","加载测位移，画曲线","K 在允差内（仪表 ±5%、工程 ±50%）"],["气密/漏率","氦检、气泡、压降","按客户要求，UHV 可到 1E-9–1E-10 mbar·L/s"],["耐压/爆破","水压/气压逐步升压","耐压 1.5×设计压力，爆破≥规定值"],["疲劳","循环加载到泄漏/破裂","按标准或客户寿命要求"],["耐蚀","盐雾、晶间腐蚀、点蚀电位","按 GB/T 12777、ASTM G28 等"]]},{"t":"h2","x":"七、工艺选择表：拿到图纸先勾"},{"t":"table","head":["图纸特征","优先路线","要追加的成本"],"rows":[["k≤1.5、长径比大、批量","液压成形","模具、液压设备摊销"],["k=1.6–1.9、中等批量","液压两次成形 / 滚压","中间退火、模具修正"],["k≥2、大直径、特殊材料","焊接成形","焊缝检测、校形、热处理"],["极小直径、极薄、无缝","电沉积","芯模、电铸工时、脱模"],["带法兰/接管、异种材料","成形 + 焊接/钎焊","工装、焊后处理、检漏"],["超高真空/洁净","316L + 电解抛光 + 氦检","清洗、抛光、包装、检测"]]},{"t":"h2","x":"八、报价为什么差三倍：成本结构"},{"t":"p","x":"同样一张图，价格差通常来自五块："},{"t":"list","ordered":true,"items":["**模具/工装**：液压模、焊接工装、电沉积芯模，一次性投入差很多。","**材料利用率**：深波、大直径、薄壁，废料和合格率差很多。","**工时**：液压一件几分钟，电沉积一件几小时到几天。","**检测**：只做尺寸，还是 RT/PT/氦检/疲劳/腐蚀全做。","**良率**：薄壁深波、焊缝多、热处理变形，返工和报废都算进价格。"]},{"t":"callout","kind":"tip","title":"销售用法","x":"客户嫌贵时，不要立刻降价，先把五块拆给他看：哪一块可以减（比如检测项目）、哪一块不能减（比如焊缝检漏）。这比“我再申请一下”专业得多。"},{"t":"h2","x":"九、常见缺陷：知道怎么坏的，才会报价"},{"t":"table","head":["缺陷","在哪一步发生","原因","怎么防"],"rows":[["起皱","液压/机械成形","轴向压缩过大、内压不足、间隙大","调压力/进给曲线、修模"],["减薄/破裂","深波成形","k 太大、材料塑性不够、圆角太小","分两次成形、中间退火、加大圆角"],["回弹/椭圆","机械成形","模具回弹补偿不足","修模、增加校形"],["焊缝气孔/未熔合","焊接","保护气不足、参数不稳、表面污染","清理、背面保护、焊后检测"],["晶间腐蚀","焊接/热处理","敏化温度区间停留、未固溶","低碳/稳定化材料、焊后固溶"],["残余应力/零位漂移","成形/焊接","冷作、焊接热应力","稳定化处理、去应力"],["尺寸超差","热处理","夹具不当、温度不均","专用夹具、保护气氛炉"]]},{"t":"h2","x":"十、问工厂的五个问题"},{"t":"steps","items":["这个波是液压、滚压、焊接还是电沉积做的？","焊缝在哪里？纵缝还是环缝？怎么检？","成形后做不做热处理？固溶、稳定化还是时效？","出厂检哪些项？氦检漏率多少？","这种结构的良率大概多少？哪些尺寸最容易超差？"]},{"t":"p","x":"这五个问题问完，你对价格的判断就从“感觉”变成“结构”。下一课进入第 2 章：金属波纹管的结构类型——U 型、C 型、Ω 型、多层，为什么长成那样。"}],"exam":{"pass":70,"minutes":15,"intro":"12 道题，覆盖成形路线、焊接、热处理、检测和成本判断。","questions":[{"q":"波纹管制造的两大步骤是？","opts":["成形和组装","熔炼和轧制","涂装和包装","设计和销售"],"a":0,"why":"书里：一是元件成形工艺，二是把成形元件组装为成品。"},{"q":"k=1.4 的浅波、长管、批量生产，优先？","opts":["电沉积","液压成形","钎焊","电子束焊"],"a":1,"why":"浅波、长管、批量最适合液压成形。"},{"q":"k≥2 的深波，液压很难，通常改？","opts":["焊接或电沉积","钎焊","冲压","拉拔"],"a":0,"why":"书里：k≥2 液压成形困难，宜采用焊接波纹管；极薄小件可电沉积。"},{"q":"电沉积波纹管的最大特点是？","opts":["有纵缝","无缝、极薄、可做小直径","最便宜","只能做铜"],"a":1,"why":"在芯模上沉积再脱模，无焊缝、壁厚均匀，适合极薄极小件。"},{"q":"薄壁件焊接应遵循什么原则？","opts":["大面积加热","只让窄小区域受热","越高温度越好","不用保护气"],"a":1,"why":"书里：板材只在一个窄小区域内受热，不使其它部位组织变化。"},{"q":"下列哪种焊接热输入最集中？","opts":["氩弧焊","电子束/激光焊","钎焊","气焊"],"a":1,"why":"电子束/激光能量集中、热影响区小，适合精密薄壁。"},{"q":"钎焊的主要缺点是？","opts":["设备太复杂","强度较低、焊剂可能腐蚀基体","不能单件生产","只能焊铝"],"a":1,"why":"书里：钎焊设备简单，但焊缝强度较低，焊剂可能造成基体腐蚀。"},{"q":"321 不锈钢稳定化处理的目的是？","opts":["提高硬度","让碳化钛析出、避免晶界贫铬","降低强度","增加磁性"],"a":1,"why":"Ti 稳定化钢在 850–900℃ 保温，使碳化钛析出，减少晶间腐蚀风险。"},{"q":"QBe2 的时效温度大致是？","opts":["100–150℃","300–350℃","700–800℃","1000℃ 以上"],"a":1,"why":"书表 1-12：QBe2 淬火后 300–350℃ 保温 2h 时效。"},{"q":"稳定化处理不包括下列哪项？","opts":["交变载荷处理","长期超载处理","机械稳定处理","酸洗钝化"],"a":3,"why":"书里列的稳定化方法是交变载荷、长期超载、机械稳定；酸洗钝化是表面处理。"},{"q":"报价差三倍，通常不是因为？","opts":["模具/工装不同","检测项目不同","良率不同","材料颜色不同"],"a":3,"why":"颜色不影响成本；模具、工时、检测、良率才是主因。"},{"q":"下列哪种缺陷最容易在深波成形时出现？","opts":["起皱或破裂","焊缝气孔","晶间腐蚀","椭圆度"],"a":0,"why":"深波 k 大、减薄严重，易起皱或破裂；气孔属焊接，晶间腐蚀属热处理/焊接。"}]},"sources":[{"t":"徐开先主编《波纹管类组件的制造及其应用》§1.3 制备工艺（1998）","u":""},{"t":"同上 §1.4.4 材料与表 1-30 精密合金热处理规范","u":""}]},"6":{"title":"几何参数：k、壁厚、波距、有效长度的边界","sub":"第 1 课认了八个字母，这一课把四个比值算成判据：k=D/d、h₀/d、t/d、L₀/D。四个数一出来，这张图能不能做、该走哪条工艺、哪里会出问题，基本就有答案了。","tags":["第2章","几何参数","波深系数","壁厚","波距","有效长度"],"objectives":["能从图纸上准确读出 d、D、t、a、h₀、z、n、L₀、L，不再把 t 当壁厚","会算 k=D/d，并按 1.5、2.0 两个界判断浅波、深波和工艺路线","会算 h₀/d，知道 0.0006–0.05 的边界和“太薄/太厚”各自的后果","会算 t/d，知道 8%–18% 的取值规律和小直径为什么取上限","会算 L₀/D，知道 1.3 是稳定性红线，超了要导向、分段或改结构","拿到一张图，能按四个比值做一次 10 分钟可行性初判"],"blocks":[{"t":"lead","x":"客户发来一张图：外径 Ø40，内径 Ø32，单层壁厚 0.12，波距 4.8，12 个波，有效长度 60。你看着都“不大”，但先别报价——把四个比值算出来，才知道这单是“常规件”还是“要加导向、要改工艺、要加钱”的件。这一课只做一件事：把几何参数变成判据。"},{"t":"figure","name":"ratios","cap":"四个比值先过关，再看别的尺寸"},{"t":"callout","kind":"note","title":"这一课接在哪","x":"第 5 课总览四条工艺；这一课把 k、h₀/d、t/d、L₀/D 四个比值算成判据：这张图能不能做、该走哪条工艺。"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["k","小写 k","无量纲","k=D/d，波深系数"],["h₀/d","h 下标 0 除以 d","无量纲","壁厚比，看薄不薄"],["t/d","t 除以 d","无量纲","波距比，看密不密"],["L₀/D","L 下标 0 除以 D","无量纲","长径比，看稳不稳"],["n","小写 n","个","波数"]]},{"t":"h2","x":"一、先把十个几何量认全：每个量到底量哪里"},{"t":"p","x":"（书 §2.1.1，图 2-1）第 1 课已经认过一遍，这一课加上“怎么量、图纸上容易错在哪”。先把表看一遍，后面四个比值都从这里取数。"},{"t":"table","head":["符号","名称","定义/量法","图纸上最容易错"],"rows":[["d","内径","波纹部分最内边缘的直径，量波谷到波谷","把端部内孔当成 d；端部有配合段时 d 只算波纹段"],["D","外径","波纹部分最外边缘的直径，量波峰到波峰","把法兰外径当成 D；法兰通常比 D 大"],["t","波距","相邻两个同侧波峰（或同侧波谷）的轴向距离","把 t 当成壁厚；波纹管图里 t 是波距，壁厚是 h₀"],["a","波厚","外波纹部分轴向面上的最大宽度","把 a 当波距；a 影响波形角和圆角"],["h₀","单层壁厚","一层材料的厚度；多层时不是总厚","把多层总厚当成 h₀；z 层要乘回去"],["z","层数","管壁由几层材料组成，常见 1、2、3 层","漏看 z，把 2 层当 1 层算刚度"],["n","波数","波纹的个数，按波峰或波谷数","多数或少数一个；起点/终点定义要跟客户对齐"],["L₀","有效长度","波纹部分的轴向总长，不含端部直段","把总长 L 当 L₀；L₀ 只算有波纹的那一段"],["L","总长","自由状态下的总长度，含两端接口","把 L 当 L₀ 去算 L₀/D，会高估稳定性"],["H₁","波高","波峰到波谷的径向高度，H₁=(D−d)/2","把 H₁ 当波距；一个径向、一个轴向"]]},{"t":"callout","kind":"warn","title":"t 的双重身份","x":"普通机加工图纸里 t 常表示厚度；波纹管图纸里 t 是波距，壁厚写 h₀。看到 t 先看它标在哪：标在两个波峰之间就是波距，标在管壁上才是厚度。"},{"t":"figure","name":"anatomy","cap":"图 1 波纹管的 d、D、t、a、h₀、L₀：先认位置，再量尺寸。这一课重点看 t 与 L₀ 的位置。"},{"t":"h2","x":"二、k=D/d：第一道工艺分流"},{"t":"p","x":"（书 §2.1.1）波深系数 k 是外径与内径之比：k=D/d。它决定波有多深，也决定成形有多难。k 越大，波越高、越软、行程越大，但越难做。"},{"t":"kv","items":[["公式","k = D ÷ d"],["浅波","k = 1.3–1.5，成形较容易，刚度大、承压好"],["深波","k = 1.6–1.9，成形较难，有时要两次成形，刚度小、灵敏度高"],["很难","k ≥ 2，液压成形相当困难，宜改用焊接波纹管"],["分界","书里以 k=1.5 为浅波/深波分界"]]},{"t":"p","x":"把客户图代进去：D=40、d=32，k=40÷32=1.25，属于浅波，液压成形容易，优先液压。如果 D=40、d=25，k=1.6，进深波区，要问工厂“一次成形还是两次”，两次就要加中间退火和模具修正。如果 D=40、d=20，k=2.0，液压很难，报价要按焊接波纹管走。"},{"t":"table","head":["k","波深","工艺","性能倾向","典型用途"],"rows":[["1.3–1.5","浅","液压/滚压容易","刚度大、承压好、位移小","压力为主的工程件、补偿器"],["1.6–1.9","深","液压可能两次成形","刚度小、灵敏度高、位移大","仪表、传感器、小行程精密件"],["≥2.0","很深","液压困难，焊接/电沉积","更软、行程更大","特殊结构、焊接波纹管"]]},{"t":"callout","kind":"key","title":"k 不是“越大越好”","x":"深波软、行程大，但承压差、容易失稳；浅波硬、承压好，但行程小。选 k 是选“要行程还是要承压”，不是选高级。"},{"t":"p","x":"【2026】书里的 k 分界是经验判据，今天仍然好用，但不是唯一条件：同样 k=1.6，材料塑性好、模具精度高、设备吨位够，也可能一次成形；薄壁深波还要看减薄和起皱。k 负责“第一道筛选”，最终能不能做，要工厂用工艺仿真或试模确认。"},{"t":"h2","x":"三、h₀/d：壁厚是最敏感的参数"},{"t":"p","x":"（书 §2.1.1）书里给了一个很宽的边界：内径 Ø10–1000 mm 的波纹管，单层壁厚与内径之比一般控制在 0.0006–0.05。太厚，柔软性差；太薄，承压能力不够。"},{"t":"kv","items":[["公式","h₀/d（单层壁厚 ÷ 内径）"],["常规范围","0.0006–0.05"],["太薄的后果","承压不足、容易失稳、成形时易裂"],["太厚的后果","刚度大、行程小、成形回弹大"],["多层","总壁厚 = z×h₀；总壁厚/内径一般也不大于 0.05"]]},{"t":"p","x":"例：d=32、h₀=0.12，h₀/d=0.12÷32=0.00375，落在范围内，偏薄但可用；d=50、h₀=0.02，比值 0.0004，低于下限，承压要打问号；d=50、h₀=3，比值 0.06，超过上限，太硬，压不动。"},{"t":"p","x":"多层结构要特别小心：2 层、每层 0.10，h₀ 写 0.10，总壁厚是 0.20；算总壁厚/内径要用 0.20，不能只拿 0.10 算。多层的目的，是在总壁厚不变太多的前提下，降低每一层的弯曲刚度、提高承压和疲劳寿命。"},{"t":"callout","kind":"warn","title":"名义壁厚不等于最薄处","x":"成形后波峰/波谷会减薄，深波尤其明显。图纸写 h₀=0.12 是名义值，强度校核要看实测最小壁厚；报价时如果客户只给名义值，要问“减薄率按多少控制”。"},{"t":"p","x":"【2026】今天薄壁精密件常用激光/电子束焊、电沉积或高精度液压；壁厚公差：刚度不是主要指标时一般 ±10%，刚度要求高时 ±5%（书 §1.4）。来料实测要沿圆周取 3–4 点，波峰、波谷各测一次，记录最小值。"},{"t":"h2","x":"四、t/d：波距不是随便取的"},{"t":"p","x":"（书 §2.1.1）波距 t 影响有效长度、刚度和成形难度。规律是：t/d 随内径增大而减小；小直径成形困难，百分比取大些。书里给的范围是 t=(8–18)%·d。"},{"t":"kv","items":[["公式","t/d ×100%"],["范围","8%–18%"],["小直径","取上限，例 Ø10 取 18%，t=1.8"],["大直径","取下限，例 Ø65 取 8.9%，t≈5.8"],["作用","t 越大，波越疏、L₀ 越长、刚度越低；t 越小，波越密、越硬"]]},{"t":"p","x":"客户图 D=40、d=32、t=4.8，t/d=4.8÷32=15%，在范围内，偏疏，成形难度中等。若 t=2.0，t/d=6.25%，低于 8%，波太密，模具和回弹都难控；若 t=7.0，t/d=21.9%，超过 18%，波太疏，L₀ 会变长，稳定性要重算。"},{"t":"p","x":"波厚 a 和波距 t 是一对：t 定了，a 直接影响波形角和波峰/波谷圆角。a 太大，波峰圆角小、应力集中；a 太小，波谷太尖、成形易裂。图纸只给 t 不给 a 时，要问工厂按什么波形角做。"},{"t":"callout","kind":"tip","title":"现场快速判断","x":"拿卡尺量相邻两个波峰的距离，就是 t；量波峰外径是 D，量波谷内径是 d；量一层材料的厚度是 h₀。三个尺寸一量，k、h₀/d、t/d 三个比值当场就能算。"},{"t":"h2","x":"五、L₀/D≤1.3：稳定性红线"},{"t":"p","x":"（书 §2.1.1）为了保证工作时有可靠的稳定性，有效长度与外径的关系应为：L₀≤1.3D。超过这个值，波纹管太细长，受压时容易发生柱失稳（整体侧弯），不是波被压坏，而是整根管子弯了。"},{"t":"kv","items":[["公式","L₀ ÷ D"],["红线","≤1.3"],["超了怎么办","内部或外部加导向零件；或分成两段/多段焊接；或缩短 L₀、改波数"],["注意","L₀ 是波纹段长度，不是总长 L；用 L 算会虚高"]]},{"t":"p","x":"客户图 D=40、L₀=60，L₀/D=60÷40=1.5，超过 1.3。结论：几何上做得出来，但必须加导向，或者把 12 个波拆成两段、中间加支撑；如果不加，客户装上受压后可能整体侧弯，行程和寿命都不对。"},{"t":"p","x":"反过来，D=40、L₀=52，52÷40=1.3，正好压线；D=40、L₀=45，1.125，安全。长波纹管不是“多焊几个波”就行，书里明确：除金属软管外的长波纹管，必须在内部或外部设置导向零件。"},{"t":"callout","kind":"warn","title":"L₀/D 和 k 要一起看","x":"k 大、壁厚薄、L₀/D 又大，三个因素叠加，柱失稳风险最高。这种图不要只报“能做”，要同时报“需要导向/需要校核”。"},{"t":"h2","x":"六、四个比值一起看：一张图的 10 分钟初判"},{"t":"p","x":"不要一个一个孤立地看。按下面顺序算，四步走完，初判就出来了。"},{"t":"steps","items":["算 k=D/d：定浅波/深波/焊接，先分流工艺。","算 h₀/d：看是否在 0.0006–0.05，判断“太薄/太厚”。","算 t/d：看是否在 8%–18%，判断波距是否合理。","算 L₀/D：看是否 ≤1.3，判断要不要导向/分段。","四步都过，再进入位移、压力、寿命校核（下一课）。"]},{"t":"table","head":["检查项","客户图数值","计算","结果","判断"],"rows":[["k=D/d","D=40，d=32","40÷32","1.25","浅波，液压优先"],["h₀/d","h₀=0.12，d=32","0.12÷32","0.00375","范围内，偏薄"],["t/d","t=4.8，d=32","4.8÷32","15%","范围内，偏疏"],["L₀/D","L₀=60，D=40","60÷40","1.5","超 1.3，需导向/分段"]]},{"t":"p","x":"这张图的结论不是“不能做”，而是“能做，但要加导向或分段，报价和交期要包含这部分”。这就是销售最容易漏的地方：只报波纹管本体，漏了导向、支撑、分段焊接和校形的成本。"},{"t":"h2","x":"七、多层与波型：参数会怎么变"},{"t":"p","x":"（书 §2.1.1、§2.2）同样 d、D，改成多层，几何参数不变，但性能变了：总壁厚增加，承压提高；每层更薄，弯曲刚度下降，整体更柔。层数 z 要写进图纸，不能只写总厚。"},{"t":"table","head":["波型","几何特征","刚度/行程","承压","常见用途"],"rows":[["U 型","波峰波谷圆弧过渡，最常见","行程大、刚度中等","一般","通用波纹管、补偿器"],["C 型","波较浅、开口小","刚度大、行程小","较好","密封隔离、挠性连接"],["Ω/S 型","波更深、带加强","行程小、刚度可调","高","高压阀门、密封隔离"],["多层 U 型","多层薄壁叠合","更柔、行程大","高","高压 + 大位移"]]},{"t":"p","x":"波型变了，t 与 L₀ 的对应关系也变：同样波数，不同波型的轴向长度不同；同样 L₀，不同波型对应的波数和波距也不同。所以不能拿 U 型的 t/d 经验直接套 Ω 型，图纸上是什么波型，就按什么波型核。"},{"t":"h2","x":"八、测量与图纸核对：五个最容易错的地方"},{"t":"list","ordered":true,"items":["**D 量波峰，d 量波谷**：不要量法兰、不要量端部直段；端部有配合段时，d 只算波纹部分。","**h₀ 是单层，不是总厚**：多层图要确认 z；总厚 = z×h₀，总厚/d 也要 ≤0.05。","**t 是波距，不是壁厚**：图纸上 t 和 h₀ 经常同时出现，看标注位置。","**L₀ 不含端部**：L₀ 是波纹段长度，L 是总长；算 L₀/D 用 L₀，不要用 L。","**n 的起点要统一**：从第一个波峰到最后一个波峰，还是波谷到波谷，客户和工厂要一致，否则波数差一个，L₀ 和刚度都偏。"]},{"t":"callout","kind":"key","title":"图纸没标全怎么办","x":"只给 D、d、L，没给 h₀、t、n，不要自己猜。按书里的比例范围给一个“建议值”，并注明“待客户确认”；报价按建议值算，交期按确认后重算。"},{"t":"h2","x":"九、五个常见错误"},{"t":"list","ordered":true,"items":["把 k 算成 d/D：k 一定 ≥1，算出小于 1 就是反了。","把 h₀/d 的分母写成 D：书里用内径 d 作基准，别混。","t/d 不看内径大小：Ø10 和 Ø65 的合理百分比不一样，小直径取上限。","L₀/D 用总长 L 算：L 含端部，会把安全的图算成超限，或把超限的图算成安全。","看到 L₀/D>1.3 直接说“不能做”：其实加导向、分段就能做，关键是报价要包含。"]},{"t":"h2","x":"十、今天作业：拿一张真图填四格"},{"t":"p","x":"找一张你手上的波纹管图纸（客户的、MW 的都可以），填下面四行；填完拍给我，我帮你看判断对不对。"},{"t":"table","head":["项目","图纸数值","你的计算","你的判断"],"rows":[["k=D/d","","","浅波/深波/焊接"],["h₀/d","","","太薄/合适/太厚"],["t/d","","","太密/合适/太疏"],["L₀/D","","","稳定/需导向/需分段"]]},{"t":"p","x":"下一课进入性能参数：位移、压力、寿命、稳定性。几何是“能不能做”，性能是“能用多久、会不会坏”。两课合起来，才是一张完整的技术判断。"}],"exam":{"pass":70,"minutes":15,"intro":"12 道题，覆盖十个几何量、四个比值、边界判断和测量易错点。","questions":[{"q":"波纹管图纸上 t 通常表示？","opts":["壁厚","波距","总长","波数"],"a":1,"why":"波纹管图里 t 是波距；壁厚是 h₀。普通机加工图的 t 才常表示厚度。"},{"q":"k=D/d=1.4，属于？","opts":["浅波","深波","焊接波纹管","多层波纹管"],"a":0,"why":"书里 k=1.3–1.5 为浅波，1.4 在浅波区。"},{"q":"k≥2 时，液压成形通常？","opts":["更容易","相当困难，宜改焊接","不用模具","只能电沉积"],"a":1,"why":"书里明确：k≥2 液压成形相当困难，宜采用焊接波纹管。"},{"q":"深波相比浅波，通常？","opts":["刚度大、行程小","刚度小、灵敏度高、行程大","承压更高","更难成形但更硬"],"a":1,"why":"深波软、灵敏度高、允许位移大；浅波硬、承压好。"},{"q":"h₀/d 的常规范围是？","opts":["0.0006–0.05","0.05–0.5","0.1–0.2","1–2"],"a":0,"why":"书里：内径 Ø10–1000 mm，壁厚与内径之比一般 0.0006–0.05。"},{"q":"多层波纹管总壁厚与内径之比，一般？","opts":["不得大于 0.05","必须大于 0.1","没有限制","等于层数"],"a":0,"why":"书里：多层总壁厚与内径之比一般也不得大于 0.05。"},{"q":"t/d 的范围通常是？","opts":["1%–2%","8%–18%","30%–50%","50%–100%"],"a":1,"why":"书里：t=(8–18)%·d；小直径取上限，大直径取下限。"},{"q":"Ø10 的波纹管，t/d 常取？","opts":["约 18%","约 8.9%","约 1%","约 50%"],"a":0,"why":"书里例：Ø10 取 18%，Ø65 取 8.9%；小直径成形难，百分比取大。"},{"q":"L₀/D 的稳定性红线是？","opts":["≤1.3","≤0.5","≥2.0","≤10"],"a":0,"why":"书里：为保证稳定性，L₀≤1.3D。"},{"q":"L₀/D 超限，最合理的处理是？","opts":["直接说不能做","加导向、分段或缩短 L₀","把 D 改小","把壁厚加倍"],"a":1,"why":"超限不是不能做；书里说长波纹管要设内部/外部导向，也可分段焊接。"},{"q":"计算 L₀/D 时，L₀ 应该用？","opts":["总长 L","波纹段有效长度","端部直段长度","波距×波数再随便估"],"a":1,"why":"L₀ 是波纹部分轴向总长，不含端部；用 L 会算错。"},{"q":"下列哪个说法是错误的？","opts":["D 量波峰、d 量波谷","h₀ 是单层壁厚","t 越大波越密","L₀/D>1.3 要导向或分段"],"a":2,"why":"t 越大，波越疏、L₀ 越长；t 越小才越密。"}]},"sources":[{"t":"徐开先主编《波纹管类组件的制造及其应用》§2.1.1 几何参数（1998）","u":""},{"t":"同上 §2.2 结构与类型；§1.4 壁厚公差","u":""},{"t":"现行标准对照：GB/T 12777-2019、GB/T 14525-2010（尺寸与验收以最新标准/图纸为准）","u":""}]},"7":{"title":"性能参数：位移、压力、寿命、稳定性","sub":"客户说“行程 10 mm、压力 1.6 MPa、用 10 万次”，这三个数不是同一层意思。这一课把位移、压力、刚度、有效面积、寿命、稳定性拆开，告诉你每个数在图纸和询价单里该问什么。","tags":["第2章","性能参数","位移","压力","寿命","稳定性"],"objectives":["分清最大压缩位移、允许位移、工作位移，知道 40%–50% 这条工程红线","分清耐压力、工作压力、破裂压力，知道为什么工作压力只取耐压的 40%–50%","理解刚度 K、灵敏度 δ、有效面积 A_e 三者的关系，会做简单换算","知道寿命的定义是“到泄漏为止的循环次数”，以及影响寿命的六个因素","拿到询价单，能追问行程、压力、循环次数、温度、介质、安装导向"],"blocks":[{"t":"lead","x":"客户发来一句话：“行程 10 mm，压力 1.6 MPa，寿命 10 万次，报个价。”你不能直接乘单价。先问清楚：10 mm 是工作行程还是最大压缩行程？1.6 MPa 是工作压力还是耐压？10 万次是仪表级静态微动，还是工程级交变循环？这三个问题的答案不同，报价和工艺可能差一倍。"},{"t":"figure","name":"pressureLadder","cap":"工作值只能用到耐压/允许值的一半"},{"t":"callout","kind":"note","title":"这一课接在哪","x":"第 6 课看几何；这一课看这些几何做出来以后，位移、压力、寿命、稳定性到底怎么样。"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["w_max","w 下标 max","mm","最大压缩位移，已到塑性，不能当工作位移"],["w_B","w 下标 B","mm","工作位移，通常 ≤(0.4–0.5)w"],["p_n","p 下标 n","MPa","耐压力：波形开始塑性变形的压力"],["p_g","p 下标 g","MPa","工作压力，通常 ≤(0.4–0.5)p_n"],["p_b","p 下标 b","MPa","破裂压力，最后一道底线"],["A_e","A 下标 e","mm²","有效面积"]]},{"t":"h2","x":"一、位移的三个层次：最大、允许、工作"},{"t":"p","x":"（书 §2.1.2）波纹管被压缩到波纹彼此紧密接触时的长度叫最大压缩长度 L₀′，对应的位移叫最大压缩位移 w_max：w_max = L₀ − L₀′。这个位置材料已经进入塑性，工作状态不允许用到。"},{"t":"kv","items":[["最大压缩长度 L₀′","波纹相互接触时的长度，是结构极限，不是工作位置"],["最大压缩位移 w_max","w_max = L₀ − L₀′，到这个位置往往已塑性"],["允许位移 w","不产生塑性变形时能达到的最大位移"],["工作位移 w_B","工作过程中实际使用的最大位移"],["工程红线","w_B ≤（0.4–0.5）w"]]},{"t":"callout","kind":"warn","title":"最大行程不是工作行程","x":"客户说“能压 40 mm”，可能指的是 w_max。你按 40 mm 工作行程去算寿命，会把一个本来只能工作 15 mm 的件报成“没问题”。正确问法：“你实际工作行程是多少？最大压缩只是装配时用一下，还是每次循环都压到？”"},{"t":"p","x":"例（教学示例，不是标准值）：L₀=60、L₀′=20，则 w_max=40。按书里的经验，允许位移 w 取 w_max 的一部分，工作位移再取允许位移的 40%–50%。如果允许位移定为 12，工作位移就只能到 4.8–6.0。客户要 10 mm 工作行程，这个结构就不够，要加波数、加 L₀ 或改波型。"},{"t":"table","head":["概念","符号","定义","能不能当工作行程"],"rows":[["最大压缩位移","w_max","压到波纹相互接触","不能，已塑性"],["允许位移","w","不产生塑性变形的上限","只能作为上限，不能长期用满"],["工作位移","w_B","实际循环中使用的位移","可以，且 ≤0.4–0.5w"],["额定位移","w_n","设计给出的名义值","看合同，通常应小于允许位移"]]},{"t":"h2","x":"二、压力的三个层次：耐压、工作、破裂"},{"t":"p","x":"（书 §2.1.2）耐压力 p_n 是波纹管在保持稳定、不产生塑性变形条件下能承受的最大静压力；工作压力 p_g 是整个工作过程的最大压力；破裂压力 p_b 是管壁被压裂的临界压力。三者不是一回事。"},{"t":"kv","items":[["耐压力 p_n","保持稳定、不塑性变形的最大静压力"],["工作压力 p_g","工作过程实际承受的最大压力"],["工程红线","p_g ≤（0.4–0.5）p_n"],["破裂压力 p_b","管壁破裂的临界压力，工作压力远小于它"],["注意","p_n 是“稳定/不塑性”的边界，不是“破裂”边界"]]},{"t":"p","x":"例：p_n=4 MPa，则 p_g 只能取 1.6–2.0 MPa。客户说工作压力 1.6 MPa，刚好在 40% 这一端；如果他还要求 10 万次寿命，就要把压力、位移、温度一起核，不能只看“没超过耐压”。"},{"t":"callout","kind":"key","title":"40%–50% 不是随便打的折扣","x":"书里给的是经验窗口：工作位移取允许位移的 40%–50%，工作压力取耐压力的 40%–50%。目的是让波纹管在弹性范围内工作、性能稳定、寿命够。它不是安全系数 2 的精确计算，而是工程上留余量的起点；真正寿命要按疲劳数据核。"},{"t":"p","x":"【2026】今天客户常把“耐压”和“工作压力”混在一张表里。报价前必须让他写清楚：哪一栏是工作压力、哪一栏是试验压力、试验压力保压多久、允不允许塑性变形。试验压力通常高于工作压力，但不能拿试验压力当工作压力去算寿命。"},{"t":"h2","x":"三、刚度、灵敏度、有效面积：三个数其实是一组"},{"t":"p","x":"（书 §2.1.2）刚度是产生单位位移所需的力或压力；灵敏度是刚度的倒数；有效面积是把压力换算成轴向力的等效面积。三者关系可以用两个式子串起来。"},{"t":"kv","items":[["集中力刚度","K_F = F / w，单位 N/mm"],["压力刚度","K_p = p / w，单位 MPa/mm"],["灵敏度","δ = w / F = 1 / K_F，单位 mm/N"],["有效面积","A_e = F / p = K_F / K_p，单位 mm²"],["物理意义","压力 p 作用在 A_e 上，产生轴向力 F=(p−p₀)A_e"]]},{"t":"p","x":"例：某波纹管 K_F=20 N/mm，K_p=0.05 MPa/mm，则 A_e=20÷0.05=400 mm²。注意 A_e 不是波纹管的几何投影面积，也不是内孔面积；它是“压力折算成力”的等效面积，通常介于内孔面积和外形面积之间，靠实测或经验公式确定。"},{"t":"callout","kind":"warn","title":"有效面积会随位移变","x":"波纹管压缩时，波形的几何在变，A_e 也会变。用于力平衡或压力测量的场合，书里特别提醒：要保证工作范围内 A_e 不变或变化很小，否则压力读数会漂。询价时要问“A_e 的允许变化量”，不能只给一个名义值。"},{"t":"h2","x":"四、寿命：不是“能用几年”，是“到漏为止多少次”"},{"t":"p","x":"（书 §2.1.2）波纹管寿命的定义很硬：从开始使用，到因疲劳产生泄漏为止的负荷变化次数。不是“装上去多久”，也不是“没断就算”。寿命是一个多元函数，和位移、压力、介质、温度、刚度、频率、工艺、安装、材料都有关。"},{"t":"table","head":["使用场景","典型寿命量级","主要控制因素"],"rows":[["仪表、传感器（静态微动）","数万–数十万次","位移小、应力低、材料弹性好"],["工程补偿器、阀门密封（交变/弹塑性）","数百–数千次","位移大、压力高、应力幅大"],["真空/半导体（小位移、高洁净）","不在本书范围，按客户规范/疲劳数据","表面质量、清洁度、安装对中"]]},{"t":"p","x":"书里特别强调：要求高寿命的波纹管应设计在弹性范围内工作，例如仪表元件和轴密封。一旦工作位移进入塑性，寿命会从“数万次”掉到“数百次”量级，这不是线性下降，是断崖式下降。"},{"t":"callout","kind":"warn","title":"寿命问三件事","x":"① 循环次数；② 每次循环的位移幅和压力幅；③ 频率和介质温度。只给“10 万次”不够——10 万次微动和 10 万次大幅交变，是两个产品。"},{"t":"h2","x":"五、稳定性、密封性、零位偏移：三个“会坏”的方式"},{"t":"list","ordered":true,"items":["**稳定性**：外压或轴向力过大时，波纹可能局部塌陷（平面失稳）或整体侧弯（柱失稳）。书里用 L₀≤1.3D 做长径比初判，超了要加导向、分段或改结构。","**密封性**：波纹管必须在内外压差下不泄漏。它是底线指标，不是“可选”。真空/半导体场合还要看漏率和出气。","**零位偏移**：压缩到某位移、保压一分钟、卸载后，长度回不到自由长度，差值就是零位偏移。它和材料、位移量有关，仪表件尤其敏感。"]},{"t":"p","x":"这三个指标对应的现场问题很具体：稳定性差，装上去一抽真空就扁；密封性差，氦检漏率超标；零位偏移大，压力表不回零、传感器零点漂。报价时如果客户只给尺寸，没给这三项，要主动问使用工况。"},{"t":"h2","x":"六、温度：所有性能的“隐形乘数”"},{"t":"p","x":"（书 §2.1.3）波纹管工作温度范围可到 −253–600℃。温度升高，材料弹性模量 E 下降，刚度、耐压力、疲劳寿命都跟着降；低温下材料变脆，对表面缺陷非常敏感。书里给的液氧/液氮例子是 −196℃，膨胀节可到 400℃/4 MPa。"},{"t":"p","x":"所以同一张图，常温 20℃ 和 400℃ 是两个产品：高温要选耐热合金、考虑蠕变和氧化；低温要选低温韧性好的材料、控制表面缺陷。报价时温度不写，等于没报价。"},{"t":"h2","x":"七、询价五问：把一句话变成可报价的参数"},{"t":"table","head":["要问的","为什么问","客户常怎么答错"],"rows":[["工作位移还是最大压缩位移？","决定寿命和波数","把装配压到底的 40 mm 当工作行程"],["工作压力还是耐压/试验压力？","决定壁厚、层数、波型","把 1.5 倍试验压力当工作压力"],["循环次数、频率、幅值？","决定疲劳寿命和材料","只说“经常动”，没有次数"],["温度、介质、清洗？","决定材料、腐蚀、清洁度","只说“常温”，不提清洗剂"],["安装方式、有无导向？","决定稳定性、对中、寿命","只给外形，不给接口和支撑"]]},{"t":"callout","kind":"key","title":"报价前的“三不签”","x":"行程没说清不签；压力性质没说清不签；寿命/温度/介质没说清不签。不是刁难客户，是这三个数决定你报的是“能用的件”还是“装上去就坏的件”。"},{"t":"h2","x":"八、五个常见错误"},{"t":"list","ordered":true,"items":["把 w_max 当工作位移：压到波纹接触，材料已塑性，寿命按“次”算，不是“万次”。","把耐压力当工作压力：p_n 是稳定/不塑性边界，p_g 只能取 40%–50%。","把 A_e 当几何面积：A_e 是压力折算成力的等效面积，会随位移变。","寿命只写次数：不给幅值、频率、温度，寿命数字没有意义。","忽略安装导向：L₀/D 超 1.3 还不加导向，波纹管会侧弯，寿命断崖。"]},{"t":"h2","x":"九、今天作业：把客户一句话拆成六格"},{"t":"p","x":"拿一条真实的客户询价（微信、邮件都行），拆成下面六格；缺的格子就是你要追问的。"},{"t":"table","head":["参数","客户原话","你要确认的","缺了会怎样"],"rows":[["位移","","工作/最大/循环幅","寿命算错"],["压力","","工作/耐压/试验","壁厚和波型选错"],["寿命","","次数/频率/温度","材料选错"],["介质","","腐蚀/清洁/温度","腐蚀穿孔"],["安装","","导向/对中/接口","侧弯、漏"],["验收","","标准/漏率/外观","货到扯皮"]]},{"t":"p","x":"下一课讲波型：U、C、Ω、S 和多层、加强环。性能参数告诉你“要多少”，波型告诉你“用什么结构去实现”。"}],"exam":{"pass":70,"minutes":15,"intro":"10 道题，覆盖位移、压力、刚度/有效面积、寿命、稳定性。","questions":[{"q":"最大压缩位移 w_max 对应的状态是？","opts":["波纹相互接触，已塑性","弹性上限","工作位移","额定工况"],"a":0,"why":"书里：压到波纹相互紧密接触，往往已产生塑性变形，工作不允许达到。"},{"q":"工作位移 w_B 一般取允许位移 w 的？","opts":["10%–20%","40%–50%","80%–90%","100%"],"a":1,"why":"书里：w_B≤(0.4–0.5)w。"},{"q":"工作压力 p_g 一般取耐压力 p_n 的？","opts":["40%–50%","60%–70%","90%–100%","120%"],"a":0,"why":"书里：p_g≤(0.4–0.5)p_n。"},{"q":"耐压力 p_n 的准确定义是？","opts":["管壁破裂的压力","保持稳定、不塑性变形的最大静压力","工作压力","试验压力"],"a":1,"why":"书里：保持稳定或不产生塑性变形条件下能承受的最大静压力。"},{"q":"刚度 K_F、灵敏度 δ 的关系是？","opts":["δ=K_F","δ=1/K_F","δ=K_F²","没有关系"],"a":1,"why":"灵敏度是刚度的倒数。"},{"q":"有效面积 A_e 等于？","opts":["内孔面积","外圆面积","K_F/K_p","πD²/4"],"a":2,"why":"A_e=F/p=K_F/K_p；它是等效面积，不是几何投影面积。"},{"q":"波纹管寿命的定义是？","opts":["使用年限","到泄漏为止的负荷变化次数","到断裂为止的次数","保修期"],"a":1,"why":"书里：用直至不密封泄漏时为止的负荷变化次数表示。"},{"q":"要求高寿命的波纹管应设计在？","opts":["塑性范围","弹性范围","破裂压力附近","最大压缩位置"],"a":1,"why":"书里：高寿命应设计在弹性范围内工作，如仪表元件和轴密封。"},{"q":"L₀/D 超过 1.3，最合理的处理是？","opts":["直接判不能做","加导向、分段或改结构","把壁厚减半","把压力提高"],"a":1,"why":"书里用 L₀≤1.3D 控制稳定性，超了要设导向、分段等。"},{"q":"温度升高对波纹管的影响，正确的是？","opts":["E 升高、刚度升高","E 下降、刚度/耐压/寿命下降","只影响外观","没有影响"],"a":1,"why":"书里：温度升高，材料弹性模量下降，刚度、耐压力和疲劳寿命降低。"}]},"sources":[{"t":"徐开先主编《波纹管类组件的制造及其应用》§2.1.2 性能参数（1998）","u":""},{"t":"同上 §2.1.3 材料与温度；§2.3 设计计算开篇","u":""},{"t":"现行标准对照：GB/T 12777-2019、GB/T 14525-2010（验收以最新标准/图纸为准）","u":""}]},"8":{"title":"波型：U、C、Ω、S 与加强环","sub":"同样内径、同样长度，换个波型，承压、位移、刚度、寿命全变。这一课把书里表 2-1 的波型翻译成“什么工况选什么形状”，再讲多层和端部怎么配。","tags":["第2章","波型","U型","Ω型","加强环","端部"],"objectives":["说出 U、C、Ω、S 四种基本波型的截面差别和性能取舍","知道 U 型为什么最常用，C 型为什么不能拿来做测量元件","理解加强环、多层结构各自解决什么问题、代价是什么","认全 N/W/D/QD/Qd 五种端部，知道 W 为什么优先、N 风险在哪","拿到工况，能按“压力–位移”矩阵做第一轮波型选择"],"blocks":[{"t":"lead","x":"客户要一根 Ø50、L₀=80 的波纹管，压力 4 MPa，位移 3 mm。你按 U 型报，工厂说“这个压力 U 型壁厚要加，位移就没了”；换 Ω 型，压力够了，但位移更小。波型不是外观，它是承压和位移的“结构解”。这一课把选择顺序讲清楚。"},{"t":"figure","name":"waveTypes","cap":"波型决定刚度、承压、位移和工艺"},{"t":"callout","kind":"note","title":"这一课接在哪","x":"第 7 课讲性能；这一课讲改变波型会怎样改变性能。同样的内径和长度，换个波型，承压、位移、刚度全变。"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["U","字母 U","—","最常用波型，位移大、承压一般"],["C","字母 C","—","刚度大、灵敏度差，多作密封隔离"],["Ω","希腊字母 Omega","—","高压小位移"],["S","字母 S","—","高压小位移，加工更难"],["z","小写 z","层","层数；多层降低刚度、提高承压"],["N/W/D/QD/Qd","端部代号","—","五种端部结构"]]},{"t":"h2","x":"一、波型到底是什么：看轴向剖面的形状"},{"t":"p","x":"（书 §2.2）波型是沿轴向剖开后看到的波纹形状。基本型有 U、C、Ω、S 四种；为了提高承压或降低刚度，又派生出带加强环的 U 型、多层 U 型等。书里表 2-1 把每种波型的承压能力、允许位移、工艺性列在一起，结论很直接：没有全能型，只有取舍。"},{"t":"table","head":["波型","承压能力","允许位移","工艺性","一句话"],"rows":[["U 型","中等","一般（较大）","一般","最常用，位移和承压的折中"],["U 型外加强环","高","一般","很好","外面加环，扛压提升"],["U 型内加强环","高","一般","很好","里面加环，扛压提升"],["C 型","高","差","一般","刚、硬、灵敏度差"],["S 型","中等","一般","良好","形状可设计，兼顾"],["Ω 型（外压/内压）","很高","差","很好","高压小位移"],["Ω 型外加强环","很高","差","很好","更高压，位移更小"],["V 型（形状可改变）","低","良好","一般","低压、大位移"],["U 型外“T”加强环","高","一般","很好","高压，工艺成熟"]]},{"t":"p","x":"书里有一段总结，值得背下来：圆环形横截面承受高压的能力优越，但许用位移小；U 型横截面允许较大位移，但承压能力相对低。国内最普遍的是 U 型；压力高、位移又大时，用多层 U 型。"},{"t":"h2","x":"二、U 型：默认答案，但不是唯一答案"},{"t":"p","x":"U 型是最常见的波型，原因是它把“能压”和“能扛”折中得最好：位移比 C/Ω 大，承压比 V 型高，工艺也成熟。大多数通用补偿、密封、仪表隔离，先看 U 型。"},{"t":"p","x":"但 U 型不是越深越好。波深 k 大了，位移大、刚度低，承压和稳定性下降；壁厚薄了，柔软但耐压差。所以 U 型的选型，最后还是回到第 6 课的四个比值：k、h₀/d、t/d、L₀/D。"},{"t":"callout","kind":"key","title":"U 型的“默认”是有条件的","x":"压力不高、位移中等、成本敏感——U 型优先。压力上去了，先考虑加强环或多层；位移很小、压力很高，才轮到 Ω/S。"},{"t":"h2","x":"三、C 型：刚、硬、不灵敏"},{"t":"p","x":"（书 §2.2）C 型波纹管的刚度较大、灵敏度差、非线性误差大，所以它一般不做测量元件，而是做密封隔离元件或挠性联接件。书里表 2-1 也把它列为承压高、位移差。"},{"t":"p","x":"为什么？C 型的截面更“拱”，抵抗变形的能力强，所以刚度大；但一受压，几何非线性明显，位移和压力的关系不直，做压力表会读数不准。它的优势是“扛得住、不漏”，不是“测得准”。"},{"t":"callout","kind":"warn","title":"别拿 C 型做传感器","x":"客户说“要个弹性元件，压力转换成位移”，你给 C 型，线性度大概率不合格。测量用途优先 U 型、S 型或专门设计的测量波纹管，且要校非线性度。"},{"t":"h2","x":"四、Ω 型与 S 型：高压小位移的答案"},{"t":"p","x":"（书 §2.2）Ω 型和 S 型主要用在工作压力较高、工作位移较小的场合，例如高压阀门上作密封隔离元件。Ω 型的圆环截面承压能力很高，但许用位移小；S 型介于 U 和 Ω 之间，形状可以设计，兼顾承压和位移。"},{"t":"p","x":"高压阀门的典型需求是：压力 10–40 MPa，位移只有 1–3 mm，要求不泄漏、寿命够。这时候 U 型要么壁厚加到压不动，要么波数多到 L₀ 超限；Ω 型用圆环截面把压力扛住，位移小正好匹配。"},{"t":"table","head":["工况","优先波型","理由"],"rows":[["低压、大位移、通用补偿","U 型 / V 型","位移能力优先"],["中高压、中等位移","U 型 + 加强环","承压和位移折中"],["高压、小位移、阀门密封","Ω 型 / S 型","圆环截面承压高"],["高压 + 大位移","多层 U 型","多层降刚度、提承压"],["测量、力平衡","U 型 / S 型（校线性）","非线性度要可控"]]},{"t":"h2","x":"五、加强环：给 U 型“加骨头”"},{"t":"p","x":"（书 §2.2）U 型外加强环、U 型内加强环、U 型外“T”加强环，都是在 U 型波上加一圈环状加强件。作用是提高承压能力，代价是结构变复杂、工艺变多、成本上升，位移能力基本不变或略降。"},{"t":"list","ordered":true,"items":["**外加强环**：环在波峰外侧，限制波峰向外鼓，提升外压/内压下的稳定性；外部空间要够。","**内加强环**：环在波谷内侧，限制波谷向内塌，适合外压或安装空间受限的场合；内孔通流会受影响。","**外“T”加强环**：T 形环卡在波峰外，抗弯更强，适合高压；工艺成熟，但模具和装配更复杂。"]},{"t":"callout","kind":"warn","title":"加强环不是“免费加厚”","x":"加环能提高承压，但会增加零件数、焊缝/装配点、重量和成本，还可能影响通流和清洁。客户只给压力、不给空间和清洁要求时，不要默认“加环就行”。"},{"t":"h2","x":"六、多层：高压 + 大位移的折中"},{"t":"p","x":"（书 §2.2）在承受较高工作压力和较大位移的条件下，采用多层 U 型波纹结构。多层不是简单把壁厚分几层：每层更薄，弯曲刚度低，整体柔度好；层与层之间的摩擦和间隙又能耗能、提高阻尼；总壁厚增加，承压提高。"},{"t":"p","x":"代价是：制造和装配更复杂，层间可能有间隙/滑动，真空场合要关注层间出气，寿命和泄漏路径也更难分析。报价时要把层数、每层厚度、总厚、层间处理写清楚。"},{"t":"table","head":["结构","承压","位移","成本","典型场景"],"rows":[["单层 U 型","中等","较大","低","通用"],["多层 U 型（2–3 层）","高","大","中高","高压 + 大位移"],["U 型 + 加强环","高","中等","中","高压、位移一般"],["Ω 型","很高","小","高","高压阀门密封"]]},{"t":"h2","x":"七、端部 N/W/D/QD/Qd：五种基本结构，14 种组合"},{"t":"p","x":"（书 §2.2）波纹管两端要跟零件焊接，端部结构有五种基本型式：N 内配合、W 外配合、D 封闭底、QD 波峰处切断、Qd 波谷处切断。两端可以任意组合，同一种波纹管能组合出 14 种端部结构。"},{"t":"table","head":["代号","端部形式","特点","风险/备注"],"rows":[["N","内配合","端部插入配合件","工艺性较差；D₁/L₁ 选大了，成形时容易破裂"],["W","外配合","配合件套在外面","工艺性最好，优先采用"],["D","封闭底","一端封底，像“盲管”","用于封闭端；注意排气/清洁"],["QD","波峰切断","没有直壁段，在波峰处切断","端部是波峰，焊接/密封要专门设计"],["Qd","波谷切断","没有直壁段，在波谷处切断","端部是波谷，同上"]]},{"t":"p","x":"书里明确建议：W 型工艺性最好，优先采用；N 型工艺性较差，直径和长度最好按标准/样本选，不能随意放大，否则成形时容易在端部破裂。"},{"t":"p","x":"端部还决定焊接方法：黄铜、锡青铜、铍青铜用钎焊或银焊；不锈钢、Inconel 718 可用氩弧焊、滚焊、电子束焊。端部结构没定，焊接方式和报价都没法定。"},{"t":"h2","x":"八、选型顺序：先压力、再位移、再端部"},{"t":"list","ordered":true,"items":["先看压力：低压/中压/高压；高压先排除单层 U 型。","再看位移：大位移优先 U/多层 U；小位移才用 Ω/S。","再看介质/温度：腐蚀、洁净、高温会推翻前面的选择。","再看端部/安装：W 优先；N 要按标准；空间决定外环/内环。","最后看成本/交期：加强环、多层、Ω 型都会加钱，报价要写清。"]},{"t":"callout","kind":"key","title":"一句话选型","x":"低压大位移 U；高压小位移 Ω/S；高压大位移多层 U；要扛压又不想太贵，U 型加加强环。"},{"t":"h2","x":"九、五个常见错误"},{"t":"list","ordered":true,"items":["只看压力选波型：压力够、位移不够，装上去就压不动。","拿 C 型做测量：刚度大、非线性大，读数不准。","Ω 型配大行程：许用位移小，硬压会失稳/裂。","多层当单层算刚度：层数、层间间隙都会改变整体刚度。","端部随手写 N：N 的 D₁/L₁ 放大后，成形易裂。"]},{"t":"h2","x":"十、今天作业：给三个工况各选一个波型"},{"t":"table","head":["工况","压力","位移","介质/温度","你的选择"],"rows":[["A 通用补偿","0.6 MPa","8 mm","空气/常温",""],["B 高压阀门密封","16 MPa","2 mm","水/80℃",""],["C 真空隔离","外压 0.1 MPa","5 mm","洁净/150℃",""]]},{"t":"p","x":"下一课讲多层与端部的深入选型，再把“刚度怎么算”接上。波型是结构，刚度是数字，两者要一起看。"}],"exam":{"pass":70,"minutes":12,"intro":"10 道题，覆盖四种基本波型、加强环、多层和端部结构。","questions":[{"q":"国内最普遍使用的波型是？","opts":["C 型","U 型","Ω 型","V 型"],"a":1,"why":"书里：一般情况下国内普遍应用的波型是 U 型波纹。"},{"q":"U 型波纹的主要特点是？","opts":["承压很高、位移很小","允许较大位移、承压相对较低","刚度最大","只能用于测量"],"a":1,"why":"书里：U 型允许较大位移，承压能力相对较低。"},{"q":"C 型波纹管通常用于？","opts":["压力测量","密封隔离或挠性联接","大位移补偿","高频疲劳"],"a":1,"why":"书里：C 型刚度大、灵敏度差、非线性误差大，一般作密封隔离或挠性联接。"},{"q":"Ω 型和 S 型主要用在？","opts":["低压大位移","高压小位移","常温自来水","大口径通风"],"a":1,"why":"书里：主要用在工作压力较高、工作位移较小的场合，如高压阀门密封隔离。"},{"q":"承受较高压力和较大位移时，书里推荐？","opts":["单层 U 型","多层 U 型","C 型","V 型"],"a":1,"why":"书里：在较高工作压力和较大位移条件下，采用多层 U 型波纹结构。"},{"q":"U 型加强环的主要作用是？","opts":["提高承压能力","增大位移","降低成本","消除焊缝"],"a":0,"why":"加强环用来提高承压能力，位移基本不变或略降。"},{"q":"端部结构 W 的特点是？","opts":["内配合，工艺性差","外配合，工艺性最好","封闭底","波峰切断"],"a":1,"why":"书里：W 外配合，工艺性最好，建议优先采用。"},{"q":"N 型端部的主要风险是？","opts":["不能焊接","D₁/L₁ 选大了成形时容易破裂","不能做密封","只能用于塑料"],"a":1,"why":"书里：N 型工艺性较差，D₁、L₁ 过大会在成形过程中破裂。"},{"q":"波纹管端部基本结构有几种？","opts":["3 种","5 种","8 种","14 种"],"a":1,"why":"书里：N、W、D、QD、Qd 五种基本结构；两端组合可得 14 种。"},{"q":"高压、小位移、阀门密封，优先选？","opts":["U 型","Ω 型/S 型","V 型","C 型"],"a":1,"why":"Ω/S 型承压高、许用位移小，适合高压阀门密封隔离。"}]},"sources":[{"t":"徐开先主编《波纹管类组件的制造及其应用》§2.2 结构与类型、表 2-1（1998）","u":""},{"t":"同上 §2.1.1 几何参数；§2.1.2 性能参数","u":""},{"t":"现行标准对照：GB/T 12777-2019、GB/T 14525-2010（端部尺寸以最新标准/图纸为准）","u":""}]},"9":{"title":"多层与端部：N/W/D/QD/Qd 怎么选","sub":"同样一根波纹管，端部写成 N 还是 W，价格和良率可能差一截；多层结构能同时扛高压和大位移，但层间怎么封、怎么检，决定它会不会漏。这一课把端部和多层拆开讲。","tags":["第2章","端部","多层","N/W","焊接","工艺性"],"objectives":["认全 N、W、D、QD、Qd 五种端部，知道各自的配合方式和工艺风险","理解为什么 W 工艺性最好、N 的 D₁/L₁ 不能随意放大","知道 14 种端部组合是怎么来的，能按配合件反推端部","理解多层结构解决什么问题，以及层间间隙/焊接/检漏的代价","拿到图纸，能判断端部是否可焊、可检、可装"],"blocks":[{"t":"lead","x":"客户图纸上端部写了个 N，旁边标 D₁=28、L₁=12。工厂看一眼说：“这个 N 做不了，改成 W 或者把 D₁ 缩到 24。”你不懂端部，只能把话原样转给客户，一来一回三天。这一课把五种端部讲透，让你自己就能判断问题出在哪。"},{"t":"figure","name":"endTypes","cap":"端部是连接方案，不是收口"},{"t":"callout","kind":"note","title":"这一课接在哪","x":"第 8 课选波型；这一课选端部和层数。端部写 N 还是 W、做几层，决定价格、良率和会不会漏。"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["N","字母 N","—","内配合，端部插入件内孔"],["W","字母 W","—","外配合，工艺性最好"],["D","字母 D","—","封闭底，一端封死"],["QD","Q 加 D","—","波峰切断，无直壁"],["Qd","Q 加 d","—","波谷切断，无直壁"],["z","小写 z","层","层数，影响刚度与承压"]]},{"t":"h2","x":"一、端部不是“收口”，是连接方案"},{"t":"p","x":"（书 §2.2）波纹管两端必须与相联接的零件焊接。端部结构决定三件事：怎么配合、怎么焊、成形时会不会裂。书里给了五种基本结构，两端任意组合，同一种波纹管可以组合出 14 种端部结构。"},{"t":"table","head":["代号","中文","配合方式","工艺性","主要风险"],"rows":[["N","内配合","波纹管端部插入配合件内孔","较差","D₁/L₁ 放大后，成形时端部易破裂"],["W","外配合","配合件套在波纹管端部外面","最好","外部空间要够；焊接可达性要看结构"],["D","封闭底","一端做成封闭底，像盲管","一般","封闭端排气/清洁困难；不能通流"],["QD","波峰切断","没有直壁段，在波峰处切断","一般","端部是波峰，焊接/密封面要专门设计"],["Qd","波谷切断","没有直壁段，在波谷处切断","一般","端部是波谷，同上"]]},{"t":"p","x":"书里明确排序：W 型工艺性最好，建议优先采用；N 型工艺性较差，直径和长度最好按有关标准/产品样本选取，不能随意放大。原因不神秘：N 型的端部要插进配合件，成形时端部受约束，D₁、L₁ 越大，材料流动越困难，容易在过渡区撕裂。"},{"t":"h2","x":"二、N 型：为什么“按标准选”不是废话"},{"t":"p","x":"N 型的端部是一段直壁，插进配合件的内孔，再沿环缝焊接。它的好处是径向空间小、配合件在外，适合外径受限的场合。坏处是成形时端部被直壁“锁住”，波谷到直壁的过渡区应力集中。"},{"t":"p","x":"书里说 N 的 D₁、L₁ 选大了会在成形过程中破裂。实际报价时，如果客户给的 N 型 D₁/L₁ 明显大于标准样本，不要直接报“能做”，先问工厂：这个端部是否要改 W、是否要加过渡圆弧、是否要分两道成形。改端部往往比改波型便宜。"},{"t":"callout","kind":"warn","title":"N 型不是“不能做”","x":"书里说的是工艺性较差、不能随意放大，不是绝对禁止。按标准/样本选尺寸、加过渡、控制成形速度，N 型仍可做；但报价要包含更高的模具和良率风险。"},{"t":"h2","x":"三、W 型：为什么优先"},{"t":"p","x":"W 型的配合件套在波纹管端部外面，波纹管端部是“外配合”。它的工艺性最好：成形时端部约束小，材料流动顺；焊接时外面可达，夹具好做；配合件在内，波纹管外径就是配合尺寸，容易保证同轴。"},{"t":"p","x":"代价是外部空间：配合件套在外面，外径会变大；如果客户的外壳空间很紧，W 可能装不进去。这时候才考虑 N，或者把配合件做成台阶。"},{"t":"callout","kind":"key","title":"默认写 W，除非空间不允许","x":"新设计没有特殊理由，端部优先 W；客户给 N 且尺寸超样本，先评估改 W 的可能性，再谈模具费。"},{"t":"h2","x":"四、D、QD、Qd：三种“特殊端”"},{"t":"list","ordered":true,"items":["**D 封闭底**：一端封死，像盲管。用于只从一端通入介质、另一端要封闭的场合。注意：封闭端容易积气/积液，真空和洁净场合要问清洗和排气。","**QD 波峰切断**：没有直壁段，直接在波峰处切断。端部就是波峰，焊接面窄，夹具要专门设计；优点是短、省空间。","**Qd 波谷切断**：在波谷处切断。端部是波谷，和 QD 一样属于“无直壁”结构，焊接/密封面要专门做。"]},{"t":"p","x":"QD/Qd 常见于小直径、短安装长度的仪表件。它们省掉了直壁段，但把“焊接可达性”推给了下游：你不能按普通 N/W 的夹具去焊，报价时要确认工厂有没有对应工装。"},{"t":"h2","x":"五、14 种组合怎么来的：两端可以不一样"},{"t":"p","x":"（书 §2.2）五种基本端部，两端各选一种，书里说同一种波纹管可以组合成 14 种端部结构——不是所有排列都常用，具体以标准/样本为准。实际图纸常见的是 NN、WW、WD、QD-Qd 等。"},{"t":"table","head":["组合","典型用途","注意"],"rows":[["WW","通用、两端外配合","工艺性最好，优先"],["NN","两端内配合、外径受限","D₁/L₁ 按标准，别放大"],["WD","一端外配合、一端封闭","封闭端排气/清洁"],["QD-Qd","短长度、仪表件","无直壁，焊接工装专用"]]},{"t":"p","x":"报价时端部要写到“代号 + D₁/L₁ + 配合件材料 + 焊接方法”，只写“N 型”不够。端部尺寸和配合公差决定了夹具、焊前清洗、焊接参数，都是成本。"},{"t":"h2","x":"六、端部材料与焊接方法要匹配"},{"t":"p","x":"（书 §2.2）黄铜、锡青铜、铍青铜采用钎焊或银焊；不锈钢、Inconel 718 可采用氩弧焊、滚焊、电子束焊。端部结构不同，焊接方法也不同：N 型是插入后环缝焊，W 型是外套后环缝焊，QD/Qd 是无直壁的端面焊。"},{"t":"table","head":["母材","常用焊接","注意"],"rows":[["黄铜/锡青铜/铍青铜","钎焊、银焊","钎料/焊剂残留要清洗，避免腐蚀"],["不锈钢","氩弧焊、滚焊、电子束","控制热输入，避免晶粒长大和变形"],["Inconel 718","氩弧焊、电子束","焊后热处理/时效要匹配"],["异种材料","按工艺评定","热膨胀差、脆性相、电偶腐蚀"]]},{"t":"callout","kind":"warn","title":"端部写了，焊接方法没写","x":"同一 N 型，钎焊和激光焊的夹具、成本、热影响区完全不同。客户只给端部代号时，要追问焊接方法或“按什么标准焊”。"},{"t":"h2","x":"七、多层：为什么要“一层变几层”"},{"t":"p","x":"（书 §2.2）在较高工作压力和较大位移的条件下，采用多层 U 型波纹结构。逻辑是：总壁厚要够承压，但单层太厚会太硬、压不动；把总厚分成几层薄壁，每一层更容易弯曲，整体就柔；层数多了，承压路径也多，泄漏要穿过层层屏障。"},{"t":"p","x":"但多层不是“免费变软”。（书式 2-7）在总壁厚相同的前提下，多层刚度是单层的 1/Z^1.5——2 层约 0.354，3 层约 0.192；不是简单的 1/Z。层与层之间还有间隙，压缩时层间会摩擦、滑动，实际刚度会偏离这个经验值；层间如果进液/进气，清洁和真空出气会变差；端部要把多层全部焊透/封住，否则会从层间漏。经验公式只做初判，最终要实测或做有限元。"},{"t":"table","head":["项目","单层","多层","影响"],"rows":[["承压","靠总壁厚","总壁厚大，承压高","层数增加可提高耐压"],["柔度","壁厚大则硬","每层薄，整体更柔","高压大位移的关键"],["层间","无","有间隙/摩擦","刚度、阻尼、清洁度都受影响"],["端部","一次焊接","多层都要封","漏路径多，检漏要严"],["成本","低","高","装配、焊接、检测工时增加"]]},{"t":"callout","kind":"key","title":"多层的三个必问","x":"① 几层、每层多厚、总厚多少；② 层间要不要清洗/抽真空/填充；③ 端部怎么封、怎么检漏。三个有一个没写清，报价就是赌。"},{"t":"h2","x":"八、端部 + 多层：最容易漏的组合"},{"t":"p","x":"多层波纹管的端部要把所有层焊到一起，形成一道连续密封。常见问题：层间未完全熔合、层间夹渣/油污、焊接热输入把薄层烧穿、端部过渡区应力集中。真空/半导体场合，层间还会藏气，抽真空时缓慢出气，漏率下不去。"},{"t":"list","ordered":true,"items":["焊前：多层端部要逐层清洗、去油、干燥；不锈钢可用超声+纯水+烘干。","焊接：优先激光/电子束等热输入可控的方法；氩弧焊要控制热输入和层间温度。","焊后：按标准做气密/氦检；真空件要做烘烤出气测试。","端部：W 型比 N 型好焊；多层 + N 型的组合要特别小心。"]},{"t":"h2","x":"九、报价前的端部检查表"},{"t":"table","head":["看到","要问","会影响"],"rows":[["N 型 + D₁/L₁ 超样本","能否改 W/加过渡/按标准缩尺寸","模具、良率、交期"],["QD/Qd","焊接工装、端面密封面","工装费、焊接良率"],["D 封闭底","排气/清洁/是否要通流","清洗、真空出气"],["多层","层数/层厚/层间处理/端部封焊","成本、检漏、寿命"],["异种材料","焊接工艺评定、热膨胀差","裂纹、泄漏"]]},{"t":"callout","kind":"key","title":"端部是“设计—工艺—成本”的交汇点","x":"同一个波型，端部改一个字母，模具、夹具、焊接、检漏全变。销售不懂端部，就只能被工厂和客户来回推。"},{"t":"h2","x":"十、五个常见错误"},{"t":"list","ordered":true,"items":["把端部当收口：端部是配合+焊接结构，不是随便缩一下。","N 型尺寸照客户图直接报：D₁/L₁ 超样本，成形会裂。","W 型不看外部空间：配合件套在外面，外壳可能装不下。","多层按单层除以 Z 算：书里经验式是 1/Z^1.5，且实际还受层间摩擦/端部约束影响。","端部写了但焊接方法没写：钎焊和激光焊成本差很多。"]},{"t":"h2","x":"十一、今天作业：把一张图的端部拆成四行"},{"t":"table","head":["项目","图纸写法","你的判断","要追问的"],"rows":[["端部代号","","N/W/D/QD/Qd","是否可按标准/改 W"],["D₁/L₁","","是否超样本","能否缩/加过渡"],["配合件材料","","钢/铜/异种","焊接方法/工艺评定"],["层数","","单层/多层","层间处理/端部封焊"]]},{"t":"p","x":"下一课进入刚度计算：书里的能量法公式 2-1 到 2-4，把“软硬”算成一个数。端部和多层定结构，刚度定数字，两课接起来才是完整设计。"}],"exam":{"pass":70,"minutes":12,"intro":"10 道题，覆盖五种端部、14 种组合、多层结构和焊接匹配。","questions":[{"q":"书里工艺性最好的端部结构是？","opts":["N","W","D","QD"],"a":1,"why":"书里：W 型外配合工艺性最好，建议优先采用。"},{"q":"N 型端部的主要风险是？","opts":["不能焊接","D₁/L₁ 选大了成形时易破裂","不能密封","只能用于塑料"],"a":1,"why":"书里：N 型工艺性较差，D₁、L₁ 过大会在成形过程中破裂。"},{"q":"D 型端部的特点是？","opts":["两端通流","一端封闭底","波峰切断","内配合"],"a":1,"why":"D 是封闭底，一端封死，像盲管。"},{"q":"QD 表示？","opts":["波谷切断","波峰切断","内配合","封闭底"],"a":1,"why":"QD 是在波峰处切断；Qd 是波谷处切断。"},{"q":"五种基本端部两端组合，书里说可得？","opts":["5 种","10 种","14 种","25 种"],"a":2,"why":"书里：五种基本结构任意组合，同一种波纹管可组合成 14 种端部结构。"},{"q":"不锈钢波纹管常用的焊接方法不包括？","opts":["氩弧焊","滚焊","电子束焊","银焊"],"a":3,"why":"书里：不锈钢/718 可用氩弧焊、滚焊、电子束；银焊/钎焊多用于铜合金。"},{"q":"多层 U 型主要用在？","opts":["低压小位移","高压大位移","只做装饰","只做真空"],"a":1,"why":"书里：较高工作压力和较大位移时采用多层 U 型。"},{"q":"在总壁厚相同的前提下，书里经验式给的多层刚度是单层的多少？","opts":["1/Z","1/Z^1.5","1/Z²","Z 倍"],"a":1,"why":"书里式 2-7：K₂/K₁=1/Z^1.5；2 层约 0.354，3 层约 0.192。"},{"q":"多层波纹管端部最怕什么？","opts":["层间未完全封焊/夹渣","外径太大","波数太多","颜色不统一"],"a":0,"why":"多层端部要把所有层封住，层间未熔合/夹渣会形成漏路径。"},{"q":"客户给 N 型且 D₁/L₁ 超样本，最合理的做法是？","opts":["直接报能做","评估改 W/加过渡/按标准缩尺寸","把壁厚加倍","忽略端部"],"a":1,"why":"N 型尺寸放大易裂；改 W 或按标准缩尺寸通常比硬做便宜。"}]},"sources":[{"t":"徐开先主编《波纹管类组件的制造及其应用》§2.2 结构与类型（1998）","u":""},{"t":"同上 §2.1.3 材料；§2.4 制造工艺相关章节","u":""},{"t":"现行标准对照：GB/T 12777-2019、GB/T 14525-2010（端部尺寸以最新标准/图纸为准）","u":""}]},"10":{"title":"刚度计算：能量法与经验公式","sub":"书里的刚度不是拍脑袋，是从薄壳应变能推出来的。这一课把公式 2-1 到 2-4 拆开：每个符号什么含义、哪一项主导、为什么手算和实测会差。","tags":["第2章","刚度","能量法","公式","设计计算"],"objectives":["知道波纹管刚度分轴向、弯曲、扭转，为什么轴向最常用","理解能量法的三个前提：薄壳、直法线、忽略 σ₃","能读懂式 2-1 到 2-4，说出每个符号和单位","知道 K 随 E、h₀、n 的变化趋势，以及为什么不是简单线性","知道手算与实测差异的四个来源，报价时敢留余量"],"blocks":[{"t":"lead","x":"客户问：“这根波纹管刚度多少？”你翻书，看到一长串 A₀、A₁、A₂、B₀、α，头就大了。其实不用背公式，只要知道：刚度由材料、壁厚、波数、波形角决定；公式只是把这些关系写严谨。这一课把公式拆成“人话 + 单位 + 趋势”。"},{"t":"figure","name":"energyMethod","cap":"一个波的能量，再按 n 个波串联"},{"t":"callout","kind":"note","title":"这一课接在哪","x":"第 9 课定结构；这一课算刚度，回答“这根管子到底多硬”。公式里的每个字母先认全，再代入。"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["K","大写 K","N/mm","刚度：每压 1 mm 要多少力"],["E","大写 E","MPa","弹性模量"],["μ","希腊字母 mu","—","泊松比，不锈钢约 0.3"],["h₀","h 下标 0","mm","单层壁厚"],["n","小写 n","个","波数"],["A₀/A₁/A₂/B₀","A 下标 0/1/2、B 下标 0","—","与 k、m 有关的系数，查图 2-4"],["k / m","小写 k / m","—","k=(D−h₀)/(d+h₀)，m=(a−h₀)/(d+h₀)"]]},{"t":"h2","x":"一、刚度分三种，先认轴向"},{"t":"p","x":"（书 §2.3.1）波纹管受力可以是轴向力、压力、弯矩，所以刚度分轴向刚度、弯曲刚度、扭转刚度。绝大多数应用是轴向载荷、线位移，所以书里重点讲轴向刚度，通常说“刚度”就是指它。"},{"t":"kv","items":[["轴向刚度 K_F","F/w，单位 N/mm；最常用"],["压力刚度 K_p","p/w，单位 MPa/mm；用于内压/外压驱动"],["弯曲刚度 K_M","M/φ，单位 N·mm/rad；用于横向/角向"],["灵敏度 δ","1/K_F，单位 mm/N；刚度越小越灵敏"]]},{"t":"callout","kind":"key","title":"先问“哪种刚度”","x":"客户只说“刚度 20”，你要问单位：N/mm 是轴向，MPa/mm 是压力，N·mm/rad 是弯曲。单位不对，数就完全不是一回事。"},{"t":"h2","x":"二、能量法：把“变形”变成“能量最小”"},{"t":"p","x":"（书 §2.3.1）能量法也叫变分法，B. I. 费奥多谢夫首先用于波纹管，用板壳理论的李兹法求解。思路是：波纹管由圆环和圆环板组成；假设一个位移函数，算它的应变能和外力功；真实位移使总势能最小。"},{"t":"list","ordered":true,"items":["**直法线假设**：变形前在中曲面法线上的点，变形后仍在同一法线上，且间距不变。","**忽略 σ₃**：与中曲面平行的截面正应力相对很小，取 σ₃=0。","**薄壳精度**：假设带来的误差量级是 h₀/R；薄壳 h₀/R 一般小于 5%，所以够用。"]},{"t":"p","x":"总势能 X = 变形势能 U + 外力势能（−Fw）。对 X 取一阶变分并令其为零（δX=0），就得到位移 w 和载荷 F 的关系。书里把这一步做完，得到式 2-1。"},{"t":"h2","x":"三、式 2-1：位移和力的关系"},{"t":"p","x":"（书式 2-1）"},{"t":"kv","items":[["式 2-1","w = F·(1−μ²)/(E·h₀) · n / [A₀ − αA₁ + α²A₂ + B₀·h₀²/((d+h₀)/2)²]"],["w","轴向位移，mm"],["F","轴向力，N"],["μ","泊松系数，无量纲；不锈钢约 0.3"],["E","弹性模量，MPa（N/mm²）"],["h₀","单层壁厚，mm"],["n","波数"],["d","内径，mm"],["α","波形角，由式 2-3 算"],["A₀、A₁、A₂、B₀","与 k、m 有关的系数，查图 2-4"]]},{"t":"p","x":"式 2-3 是波形角：α = [2(a−h₀) − t] / (D−d−2a)。其中 a 是波厚、t 是波距、D 是外径、d 是内径。k 和 m 分别是 k=(D−h₀)/(d+h₀)、m=(a−h₀)/(d+h₀)，用来查 A₀、A₁、A₂、B₀ 四条曲线。"},{"t":"callout","kind":"warn","title":"公式里的 k 不是第 6 课的 k","x":"第 6 课定义 k=D/d；式 2-1 体系里 k=(D−h₀)/(d+h₀)，m=(a−h₀)/(d+h₀)。两个 k 长得像，定义不同，查图时别拿错。"},{"t":"h2","x":"四、式 2-2 与 2-4：单波刚度与总刚度"},{"t":"p","x":"（书式 2-2、2-4）单波刚度 K_i 是式 2-1 分母的倒数乘系数；总刚度 K = K_i / n。直观理解：n 个波串联，每个波分担 1/n 的位移，所以总刚度是单波的 1/n。"},{"t":"kv","items":[["单波刚度","K_i = E·h₀/(1−μ²) · [A₀ − αA₁ + α²A₂ + B₀·h₀²/((d+h₀)/2)²]"],["总刚度","K = K_i / n"],["含义","波数越多，越软；单波越厚，越硬"],["单位检查","E(MPa)×h₀(mm) = N/mm；括号内无量纲；K 单位 N/mm"]]},{"t":"p","x":"式 2-2 括号里四项各有分工：A₀ 是膜应力主项；−αA₁+α²A₂ 是波形角修正；B₀·h₀²/((d+h₀)/2)² 是弯曲项，壁厚越大、半径越小，这项越大。它不是简单的“壁厚越厚越硬”，而是膜项和弯曲项一起变。"},{"t":"h2","x":"五、经验公式：不想查图时，先用它看趋势"},{"t":"p","x":"（书 §2.3.1 第 2 条）能量法要查图 2-4，现场报价来不及。书里还给了一个经验公式，知道材料、d、D、h₀、t、n、Z 就能直接算近似值。它不如下面的能量法严谨，但趋势判断够用。"},{"t":"kv","items":[["式 2-5","K = E(1+0.013t²)·h₀^2.5·Z / [0.4·n·D²·(1−d/D)³]"],["式 2-6","K = E(1+0.013t²)·D·h₀^2.5·Z / [3.2·n·H³]"],["h₀","单层壁厚，mm；多层时总壁厚 = Z·h₀"],["Z","层数；单层 Z=1"],["H","波深，mm；H=(D−d)/2"],["t","波距，mm"]]},{"t":"p","x":"把式 2-6 拆开看，四个趋势最值钱：K 与 h₀ 的 2.5 次方成正比（不是一次方）；与波深 H 的 3 次方成反比（波越深越软）；与 D 成正比；与波数 n 成反比。这四条足够你在报价时判断“加厚/加深/加波数”哪个方向有效。"},{"t":"callout","kind":"key","title":"多层：1/Z^1.5，不是 1/Z","x":"（书式 2-7）在总壁厚相同的前提下，多层波纹管的刚度是单层的 1/Z^1.5。比如 2 层是 1/2^1.5≈0.354，3 层是 1/3^1.5≈0.192。层数越多越软，但端部封焊、层间摩擦会让实际值偏离，公式只做初判。"},{"t":"p","x":"经验公式的局限：它把波形简化成理想几何，没算端部约束、壁厚减薄、层间接触；所以算出来是“参考刚度”，不是验收值。书里也明确说它是“近似计算”。"},{"t":"h2","x":"六、趋势：先记住三个方向"},{"t":"table","head":["变量","增大时 K 怎么变","为什么","工程含义"],"rows":[["E（材料）","近似正比增大","材料越硬，变形越难","高温 E 下降，刚度下降"],["h₀（壁厚）","增大（非线性）","膜项线性、弯曲项二次","加厚最有效，但位移变小"],["n（波数）","近似 1/n 减小","n 个波串联","加波数变软、行程大"],["d/D（直径）","通常增大","周长和半径变大","大口径更难做得软"],["α（波形角）","影响修正项","几何角度改变膜/弯比例","深波、波距变，α 变"]]},{"t":"callout","kind":"key","title":"不要用“线性比例”报价","x":"壁厚从 0.10 加到 0.12，刚度不是简单加 20%，弯曲项还会变；波数从 10 加到 12，总刚度约降到 10/12，但端部约束和层间摩擦会让实测偏离。手算只做初判，最终以试件为准。"},{"t":"h2","x":"七、手算五步：从图纸到 K"},{"t":"list","ordered":true,"items":["**第一步**：读 d、D、h₀、a、t、n，确认单位统一 mm。","**第二步**：算 k=(D−h₀)/(d+h₀)、m=(a−h₀)/(d+h₀)。","**第三步**：用 k、m 查图 2-4，得 A₀、A₁、A₂、B₀。","**第四步**：算 α=[2(a−h₀)−t]/(D−d−2a)，代入式 2-2 得 K_i。","**第五步**：K=K_i/n；再用 K_p=K_F/A_e 换算压力刚度。"]},{"t":"p","x":"这套流程的难点不在算术，在查图：图 2-4 是曲线族，k、m 落在两条线之间要插值；读错一点，K 可能差 10%–20%。所以书里的公式适合“方案比较”，不适合“精确验收”。"},{"t":"h2","x":"八、手算和实测为什么差"},{"t":"list","ordered":true,"items":["**壁厚减薄**：成形后波峰/波谷减薄，名义 h₀ 偏大，实际更软。","**边界条件**：端部固支/简支/焊接约束，公式按理想边界，实际在两者之间。","**层间摩擦**：多层结构层间摩擦耗能，实测刚度可能高于/低于单层叠加。","**残余应力与几何缺陷**：成形残余应力、波形不均、圆度误差，都会让曲线偏离。","**系数读数**：图 2-4 插值误差，尤其是 k、m 在曲线密集区。"]},{"t":"p","x":"【2026】今天可以用有限元（轴对称/壳单元）做参数化扫描，比手算快，但材料模型、壁厚分布、接触（多层）仍要标定。有限元不是“真值”，它只是比手算更细；最终仍要试件实测。"},{"t":"h2","x":"九、一个“只算趋势”的例子"},{"t":"p","x":"假设某波纹管手算 K=20 N/mm（教学示例，不是书里数据）。把波数从 10 加到 20，其他不变，K 约降到 10 N/mm；把单层壁厚从 0.10 加到 0.12，K 会升到约 24 N/mm 以上（弯曲项还会额外增加）；把材料从 304 换成 316L，E 差不多，K 变化很小；把温度从 20℃ 升到 400℃，E 下降，K 明显下降。"},{"t":"callout","kind":"warn","title":"例子只用于理解趋势","x":"上面的 20→10、20→24 是比例示意，不是精确公式结果；真实值要用图 2-4 系数和实际壁厚算，再实测修正。"},{"t":"h2","x":"十、五个常见错误"},{"t":"list","ordered":true,"items":["把式 2-1 的 k 当成第 6 课的 D/d：定义不同，查图会全错。","忘记 n：算完单波刚度直接当总刚度，结果大 n 倍。","壁厚用总厚：多层要把 h₀ 定义清楚，公式按单层。","忽略温度对 E 的影响：常温算的 K，400℃ 下可能差一截。","手算值直接写进合同：没有实测/试件，最多写“参考值”。"]},{"t":"h2","x":"十一、今天作业：把一张图的 K 算成“范围”"},{"t":"p","x":"拿一张图，按五步算一次 K；不要只写一个数，写“手算范围 + 可能偏差 + 建议实测”。例如：“K≈18–22 N/mm（图 2-4 插值 + 壁厚减薄），建议试件实测确认。”"},{"t":"table","head":["项目","数值","来源","不确定度"],"rows":[["k=(D−h₀)/(d+h₀)","","图纸","h₀ 名义值"],["m=(a−h₀)/(d+h₀)","","图纸","a 测量"],["A₀/A₁/A₂/B₀","","图 2-4","插值误差"],["K_i","","式 2-2","计算"],["K=K_i/n","","式 2-4","端部约束"]]},{"t":"p","x":"下一课讲强度与稳定性：刚度回答“压下去要多少力”，强度回答“会不会压塌/压裂”。两个校核都过，才算能用的设计。"}],"exam":{"pass":70,"minutes":15,"intro":"12 道题，覆盖能量法假设、式 2-1 到 2-4、经验式 2-5～2-7、趋势和误差来源。","questions":[{"q":"波纹管最常用的刚度是？","opts":["弯曲刚度","扭转刚度","轴向刚度","剪切刚度"],"a":2,"why":"书里：绝大多数应用是轴向载荷、线位移，重点讲轴向刚度。"},{"q":"能量法用到的薄壳假设不包括？","opts":["直法线假设","忽略 σ₃","h₀/R 很小","材料必须塑性"],"a":3,"why":"能量法基于薄壳弹性理论，不要求材料塑性。"},{"q":"式 2-1 中 w 与 F 的关系是？","opts":["w 与 F 成正比","w 与 F 成反比","w 与 F² 成正比","没有关系"],"a":0,"why":"线弹性下 w=F/K，位移与力成正比。"},{"q":"式 2-1 中的 k 定义为？","opts":["D/d","(D−h₀)/(d+h₀)","(d+h₀)/(D−h₀)","t/d"],"a":1,"why":"式 2-1 体系里 k=(D−h₀)/(d+h₀)，与第 6 课的 D/d 不同。"},{"q":"总刚度 K 与单波刚度 K_i、波数 n 的关系是？","opts":["K=K_i·n","K=K_i/n","K=K_i+n","K=K_i−n"],"a":1,"why":"书里式 2-4：K=K_i/n。"},{"q":"波数增加，总刚度通常？","opts":["增大","减小","不变","先增后减"],"a":1,"why":"n 个波串联，K=K_i/n，波数越多越软。"},{"q":"壁厚 h₀ 增加，刚度通常？","opts":["减小","增大（非线性）","不变","先减后增"],"a":1,"why":"膜项随 h₀ 增大，弯曲项随 h₀² 增大，总体增大。"},{"q":"温度升高，材料 E 下降，刚度通常？","opts":["增大","下降","不变","先增后减"],"a":1,"why":"刚度与 E 相关，E 下降则 K 下降。"},{"q":"手算刚度与实测有差异，原因不包括？","opts":["壁厚减薄","端部边界条件","层间摩擦","颜色不同"],"a":3,"why":"颜色与刚度无关；前三个都会影响。"},{"q":"式 2-2 括号中 B₀ 项主要反映？","opts":["膜应力","弯曲影响","温度","密封"],"a":1,"why":"B₀·h₀²/((d+h₀)/2)² 是弯曲项，壁厚/半径影响大。"},{"q":"经验式 2-6 中，刚度 K 与波深 H 的关系是？","opts":["与 H 成正比","与 H 成反比","与 H³ 成反比","与 H³ 成正比"],"a":2,"why":"式 2-6 分母有 H³，波深越大越软。"},{"q":"总壁厚相同的前提下，多层波纹管刚度是单层的？","opts":["1/Z","1/Z^1.5","Z 倍","不变"],"a":1,"why":"书里式 2-7：K₂/K₁=1/Z^1.5；2 层约 0.354。"}]},"sources":[{"t":"徐开先主编《波纹管类组件的制造及其应用》§2.3.1 刚度计算、式 2-1～2-4、图 2-4（1998）","u":""},{"t":"同上 §2.1.2 刚度与灵敏度；§2.2 波型与多层","u":""},{"t":"现行标准对照：GB/T 12777-2019（刚度试验与验收以标准/图纸为准）","u":""}]},"11":{"title":"强度与稳定性：1.6 MPa 是“扛得住”，还是“不塌”","sub":"客户问“这个波纹管能不能扛 1.6 MPa”，答案不是一个“能”字。强度、耐压、爆破、失稳、允许位移是五道不同的门。这一课把书里 §2.3.2 和 §2.3.4 拆成现场能用的校核顺序。","tags":["第2章","强度","耐压","稳定性","允许位移","校核"],"objectives":["分清强度、耐压力、爆破压力、失稳、允许位移五件事","知道强度判据 σ_max ≤ [σ]，以及许用应力里的安全系数怎么来","会用经验公式 2-50 估算耐压力，并知道它只适用于 L≤1.5D","理解柱失稳的欧拉公式，知道 L₀/D 和导向装置的作用","会用式 2-54 估算单波允许压缩位移，并知道压缩比拉伸更耐用","拿到工况，能按“强度→耐压→稳定→位移→寿命”的顺序做初判"],"blocks":[{"t":"lead","x":"客户发来一句话：“1.6 MPa，能不能做？”你不能只回“能”或“不能”。先问：这是工作压力还是试验压力？是内压还是外压？保压多久？允许不允许塑性变形？有没有轴向压缩？因为 1.6 MPa 可能离耐压很远，也可能已经让波纹管侧弯失稳。这一课把“扛得住”拆成五道门。"},{"t":"figure","name":"failureModes","cap":"五种坏法，五种不同的校核"},{"t":"callout","kind":"note","title":"这一课接在哪","x":"第 10 课算刚度；这一课算强度、耐压、稳定和允许位移，回答“会不会坏、会不会塌”。"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["σ_s","sigma 下标 s","MPa","屈服强度"],["p_n","p 下标 n","MPa","耐压力"],["p_b","p 下标 b","MPa","破裂压力"],["K₁/K₂/K₃","K 下标 1/2/3","—","经验系数，查表 2-3"],["F_k","F 下标 k","N","临界失稳力"],["w_y","w 下标 y","mm","允许压缩位移"]]},{"t":"h2","x":"一、五道门：强度、耐压、爆破、稳定、位移"},{"t":"table","head":["门","问的问题","书里的判据/公式","过了会怎样"],"rows":[["强度","最大应力是否超过许用应力","σ_max ≤ [σ]=σ_limit/n","屈服、塑性变形、疲劳"],["耐压","波形是否发生塑性变形","p_n=K₁K₂K₃σ_s h₀/D（L≤1.5D）","波形压塌、尺寸走样"],["爆破","管壁会不会被压裂","p_b≈2h_wσ_b/D","破裂、泄漏"],["稳定","会不会侧弯或局部塌陷","F_k=π²B/(k₄L₀)²","柱失稳、平面失稳"],["位移","压/拉多少会塑性","w_y=3.25K_aσ_sD²/(K_bE h₀)","零位偏移、寿命断崖"]]},{"t":"callout","kind":"key","title":"先分清“坏”的方式","x":"强度不够是“应力超了”，耐压不够是“波形塑性了”，爆破是“裂了”，失稳是“形状塌了”，位移不够是“压不到”。五种坏的机理不同，校核公式也不同。客户只说“扛 1.6 MPa”，你要先判断他担心的是哪一种。"},{"t":"h2","x":"二、强度：σ_max ≤ [σ]，许用应力不是材料强度本身"},{"t":"p","x":"（书 §2.3.2）波纹管作为弹性密封件，首先要满足强度条件：管壁上的最大应力 σ_max 不超过许用应力 [σ]。许用应力由极限应力除以安全系数 n 得到：[σ]=σ_limit/n。"},{"t":"kv","items":[["强度判据","σ_max ≤ [σ]"],["许用应力","[σ] = σ_limit / n"],["σ_limit 取什么","屈服强度、失稳临界应力、疲劳强度，按工况选"],["安全系数 n","由工况、材料、失效后果定；书里设计示例要求 n>1.7"],["注意","n 不是越大越好；太大说明结构没算准或材料没选对"]]},{"t":"p","x":"为什么许用应力不直接取屈服强度？因为波纹管的失效不一定是“屈服”：反复位移会疲劳，细长会失稳，腐蚀会提前开裂。不同失效模式对应不同的极限应力。强度校核的第一步不是代公式，而是先判断“这个件最可能怎么坏”。"},{"t":"h2","x":"三、应力从哪来：压力一圈，变形一弯"},{"t":"p","x":"（书 §2.3.2）波纹管上的应力由系统压力和波纹管变形共同产生。压力主要产生环向（周向）应力；在波的侧壁、波谷、波峰处产生径向的薄膜应力和弯曲应力。变形则产生径向薄膜应力和弯曲应力。"},{"t":"kv","items":[["环向薄膜应力 σ₂₀","内压把管壁“撑圆”产生，通常在内压时最大"],["径向薄膜应力 σ₁₀","轴向力/压力在子午方向产生，通常较小"],["径向弯曲应力 σ₁w","波纹圆环部分被压弯/拉弯产生，是危险点主项"],["环向弯曲应力 σ₂w","≈ μ·σ₁w，泊松效应带来的配套项"],["主应力","σ₁=σ₁₀+σ₁w；σ₂=σ₂₀+σ₂w"],["等效应力","σ_d=√(σ₁²+σ₂²−σ₁σ₂)（第四强度理论，式2-34）"]]},{"t":"p","x":"书里特别提醒：径向薄膜应力在波纹各点都很小，环向薄膜应力通常在极值截面达到最大；而弯曲应力的最大值出现在圆弧部分；薄壁时，最大弯曲应力会移到环壳与平板的连接处。也就是说，危险点不是固定的，跟壁厚、波形、载荷方式都有关。"},{"t":"callout","kind":"warn","title":"不要拿“薄壁圆筒公式”硬套波纹管","x":"波纹管不是直圆筒。直筒的环向应力是 pD/(2h)，但波纹管的波峰、波谷、侧壁曲率不断变化，弯曲应力往往比薄膜应力大一个量级。书里用的是数值法/曲线图（图2-16～2-35），参数是 k=D/d、m=r_n/R_n、δ=h₀/R_n。手算只能做趋势判断，精确值要靠曲线图、软件或试验。"},{"t":"h2","x":"四、危险点：拉伸看波峰内侧，压缩看波谷外侧"},{"t":"p","x":"（书 §2.3.2）在内压 p 和轴向力 F 同时作用时，危险点位置由 F 与 pA_e 的大小关系决定："},{"t":"list","ordered":true,"items":["**F < pA_e**：波纹管整体伸长，最大应力点通常出现在波峰内表面。","**F > pA_e**：波纹管整体压缩，最大应力点通常出现在波谷外表面。","**F = pA_e（力平衡）**：最大应力点可能在圆环部分或平直部分；薄壁时移向平板与圆环的连接处。","**壁厚越薄**：弯曲应力极值越向连接处集中，危险点越“尖”。"]},{"t":"p","x":"这条规律对报价很实用：客户说“我这件是压缩使用”，你就要重点看波谷外侧；说“拉伸使用”，重点看波峰内侧。方向不同，同样的压力/位移，危险点不同，寿命也不同。"},{"t":"p","x":"书里还给了一个重要结论：在同样压力下，力平衡条件（F=pA_e，位移被限制）的最大应力，比自由位移（F=0）的最大应力小一个数量级。这就是为什么力平衡式仪表波纹管的精度和可靠性可以做得很高——它几乎不动，弯曲应力小。"},{"t":"h2","x":"五、耐压力：经验公式 2-50 和它的边界"},{"t":"p","x":"（书 §2.3.4）耐压力 p_n 是常温、波形不发生塑性变形时能承受的最大静压力。当波纹管长度 L≤1.5D 时，可用经验公式估算："},{"t":"callout","kind":"key","title":"式 2-50","x":"p_n = K₁ · K₂ · K₃ · σ_s · h₀ / D。K₂=d/D；K₃=(a−h₀)/d；K₁ 查表 2-3。"},{"t":"table","head":["材料","屈服强度 σ_s / MPa","K₁"],"rows":[["黄铜 H80","412","4.80"],["锡青铜 QSn6.5-0.1/0.4","490","4.80"],["铍青铜 QBe1.9/QBe2","940","4.80"],["不锈钢 1Cr18Ni9Ti","588","10.40"],["弹性合金 Ni36CrTiAl","980","4.80"]]},{"t":"p","x":"例（按书里公式，教学示例）：D=51、d=38、a=2、h₀=0.14、材料 1Cr18Ni9Ti（σ_s=588、K₁=10.4）。K₂=d/D=38/51=0.745；K₃=(a−h₀)/d=(2−0.14)/38=0.049；p_n=10.4×0.745×0.049×588×0.14/51≈0.61 MPa。正好是书里寿命例子的 p_n=0.61 MPa。"},{"t":"callout","kind":"warn","title":"p_n 不是“工作压力”","x":"书里明确：工作压力 p_g 只取耐压力的 40%–50%，即 p_g≤(0.4–0.5)p_n。而且这条经验公式只适用于 L≤1.5D；细长波纹管、带横向载荷、带温度载荷的，不能直接套。外压的稳定性通常比内压好，同一件外压耐压更高。"},{"t":"h2","x":"六、爆破压力：最后一道底线，不是工作点"},{"t":"p","x":"（书 §2.3.4）当两端固定、内腔压力足够大时，波峰处可能爆破。爆破压力用无力矩理论近似："},{"t":"callout","kind":"key","title":"式 2-51","x":"p_b = 2 · h_w · σ_b / D。h_w 是波峰处壁厚，σ_b 是抗拉强度。"},{"t":"p","x":"书里给的范围：爆破压力大约是允许工作压力的 3–10 倍；当波纹长度小于或等于外径时，式 2-51 与实际较接近；细长型（L₀>D）实际爆破压力会低于计算值，有时低很多。所以细长波纹管不能只按 2-51 算安全。"},{"t":"callout","kind":"key","title":"报价时怎么用 p_b","x":"客户如果问“会不会爆”，你先看 p_b/p_g 的倍数；如果小于 3，说明工作点离爆破太近，要改结构或降压力。p_b 不是让你拿来当试验压力的，试验压力要按标准/客户规范另定。"},{"t":"h2","x":"七、稳定性：细长波纹管会像压杆一样侧弯"},{"t":"p","x":"（书 §2.3.4）当波纹管两端受轴向集中力 F 达到某一值时，会像受压螺旋弹簧一样发生侧弯失稳。临界集中力和临界压力可以用欧拉长柱公式估算，把长柱的弯曲刚度换成波纹管的弯曲刚度 B："},{"t":"callout","kind":"key","title":"式 2-52 / 2-53","x":"F_k = p_k·A_e = π²B/(k₄L₀)²；p_k = π²B/[(k₄L₀)²A_e]。B 是波纹管弯曲刚度；k₄ 与两端固定方式有关，两端刚性固定时 k₄=0.5。"},{"t":"p","x":"式子里最敏感的是 L₀：长度翻倍，临界力降到 1/4。所以书里反复强调 L₀≤1.3D；超过 1.3D 要考虑导向，超过 1.8D 更要在波纹管内/外设导向零件。阀用波纹管一般都有导向装置，就是因为行程长、怕侧弯。"},{"t":"p","x":"除了柱失稳，还有平面失稳：内压过大时，波峰/波谷局部压塌，波形不能恢复。柱失稳是“整体弯”，平面失稳是“局部塌”，两者的预防手段不同：前者加导向、缩短 L₀；后者加壁厚、加加强环、改波型、多层。"},{"t":"h2","x":"八、允许位移：压比拉耐用，但都有上限"},{"t":"p","x":"（书 §2.3.4）波纹管不产生塑性变形时能获得的最大位移叫允许位移。最大压缩位移 w_max=L−L′（或 L₀−L₀′），是波纹相互接触的结构极限，不是工作位移。允许压缩位移 w_y 可按单波公式估算："},{"t":"callout","kind":"key","title":"式 2-54","x":"w_y = 3.25 · K_a · σ_s · D² / (K_b · E · h₀)。K_a=√((a−h₀)/d)；K_b 按 k=D/d 查表 2-6。"},{"t":"p","x":"书里给了完整算例：D=51、d=38、a=2、h₀=0.14、n=19、1Cr18Ni9Ti。K_a=√((2−0.14)/38)=0.22；k=D/d=51/38=1.34（OCR 里印成 51/58，是错的）；查表 K_b≈57.1；w_y=3.25×0.22×588×51²/(57.1×2.0×10⁵×0.14)=0.68 mm；总允许位移 w=w_y×n=0.68×19=12.92 mm。"},{"t":"callout","kind":"key","title":"压缩位移是拉伸的 1.5 倍","x":"书里通过实验发现：同材料、同规格，允许压缩位移约为允许拉伸位移的 1.5 倍（w_y=1.5w₁）。所以设计时尽量让波纹管在压缩状态下工作，不要拿它当拉伸弹簧用。阀门、真空开关的波纹管，都是压缩/复位循环。"},{"t":"p","x":"位移还有一条“工作位移”红线：书里建议 w_g≤0.5w；如果按这个规范工作，寿命大致可达 5 万次左右。客户要 10 万次，就不能把工作位移用到允许位移的一半，要再留余量或改多层。"},{"t":"h2","x":"九、校核五步：拿到工况先做什么"},{"t":"list","ordered":true,"items":["**定失效模式**：客户最怕漏、怕变形、怕失稳，还是怕寿命不够？先选对应的门。","**算几何参数**：k=D/d、δ=h₀/R_n、m=r_n/R_n；这三个参数决定查哪张曲线图。","**算耐压/爆破**：L≤1.5D 用式 2-50；再用式 2-51 算 p_b，看 p_b/p_g 是否≥3。","**算稳定**：L₀/D 是否≤1.3；超了算 F_k/p_k，看工作力/工作压力是否接近临界值。","**算位移/寿命**：用式 2-54 算 w_y，工作位移是否≤0.5w；再按压力/位移百分比查寿命。"]},{"t":"callout","kind":"warn","title":"五个最常见的错","x":"① 把耐压当工作压力；② 把最大压缩位移当工作行程；③ 细长管不加导向；④ 只算强度不算稳定；⑤ 用直筒公式套波纹管。这五个错，每一个都能让报价从“能做”变成“退货”。"},{"t":"h2","x":"十、自测"}],"sources":["书 §2.3.2 应力计算","书 §2.3.4 耐压力、稳定性、允许位移","式 2-34、2-50、2-51、2-52、2-53、2-54","表 2-3、表 2-4、表 2-6"],"exam":{"pass":70,"minutes":15,"intro":"11 道题，覆盖本课的概念、数字与现场判断。答错会看到解释。","questions":[{"q":"客户说工作压力 1.6 MPa，你算出耐压 p_n=3.2 MPa。按书里的 40%–50% 窗口，这个工作点合适吗？","opts":["合适，刚好 50%","不合适，工作压力应≤1.28–1.6 MPa，1.6 已在窗口上限，需看寿命/温度","不合适，必须 p_n≥16 MPa","无法判断"],"a":1,"why":"p_g≤(0.4–0.5)p_n=1.28–1.6 MPa。1.6 正好在上限，若还有交变、温度、腐蚀，余量不够，要再核寿命或降压力。"},{"q":"同样压力下，为什么力平衡式波纹管的最大应力比自由位移式小一个数量级？","opts":["因为材料更好","因为位移被限制，弯曲应力小","因为压力更小","因为壁厚更厚"],"a":1,"why":"力平衡时 w≈0，波纹管主要承受薄膜应力，弯曲应力很小；自由位移时波纹被反复弯折，弯曲应力占主导。"},{"q":"L₀ 从 60 增加到 120，其他不变，柱失稳临界力大约变成原来的多少？","opts":["1/2","1/4","2 倍","不变"],"a":1,"why":"F_k∝1/L₀²，长度翻倍，临界力降到 1/4。所以长波纹管必须加导向或分段。"},{"q":"书里算例 D=51、d=38、a=2、h₀=0.14、n=19，单波允许压缩位移约 0.68 mm，总允许位移约多少？","opts":["0.68 mm","6.8 mm","12.92 mm","19 mm"],"a":2,"why":"w=w_y×n=0.68×19=12.92 mm。注意这是允许位移，不是工作位移；工作位移还要≤0.5w。"},{"q":"细长型波纹管（L₀>D）的爆破压力，用式 2-51 算出来的值通常：","opts":["比实际高","比实际低","完全一致","无法计算"],"a":0,"why":"书里明确：细长型实际爆破压力低于式 2-51 的计算值，有时低很多，不能直接按公式判安全。"},{"q":"下面哪一项不是“强度”问题？","opts":["波峰内表面应力超过许用应力","波纹管侧弯失稳","波谷外表面屈服","疲劳裂纹"],"a":1,"why":"侧弯失稳是稳定性问题，不是强度问题；强度看应力是否超过许用应力。"},{"q":"外压和内压，同一波纹管的耐压能力通常：","opts":["外压更高","内压更高","一样","与压力方向无关"],"a":0,"why":"书里明确：同一波纹管受外压时稳定性更好，最大耐压力比内压高。"},{"q":"工作位移 w_g 与允许位移 w 的关系，书里建议：","opts":["w_g≤w","w_g≤0.5w","w_g≤0.8w","w_g 可以略大于 w"],"a":1,"why":"书里建议 w_g≤0.5w，配合 p_g≤0.5p_n，寿命大致可达 5 万次；要用满 w 会显著缩短寿命。"},{"q":"客户只给“1.6 MPa”，你最该先追问什么？","opts":["颜色","工作/试验、内压/外压、温度、位移、寿命","包装","运输方式"],"a":1,"why":"压力性质、方向、温度、位移、寿命决定五道门怎么校核；只给一个压力数，无法判断。"},{"q":"式 2-50 的适用条件是：","opts":["任意长度","L≤1.5D","L≥1.5D","只适用于外压"],"a":1,"why":"书里写明：波纹管长度 L≤1.5D 时，才可用该经验公式估算最大耐压力。"},{"q":"安全系数 n 越大，说明：","opts":["设计一定越好","结构可能没算准或材料没选对，要结合工况看","耐压一定越高","寿命一定越长"],"a":1,"why":"n 是手段不是目的。过大往往意味着模型保守、材料性能没用足，或者工况没搞清；要结合失效模式判断。"}]}},"12":{"title":"疲劳寿命：10 万次是承诺，还是条件","sub":"客户说“我要 10 万次”，这句话只有配上压力、位移、温度、介质、频率才成立。这一课按书里 §2.3.4 的寿命图和三条工程红线，教你把“次数”拆成可核的条件。","tags":["第2章","寿命","疲劳","压力","位移","工况"],"objectives":["知道寿命的严格定义：到泄漏为止的循环次数","记住三条寿命红线：w_g≤0.5w、p_g≤0.5p_n、轴向位移取 L₀ 的 10%–40%","会按 p% 和 w% 查单层/多层寿命图的思路，不靠拍脑袋","知道交变压力比恒定压力更伤寿命，80% 位移下 1 万次时压力上限差 3 倍","拿到“10 万次”询价，能追问五个条件并判断要不要改结构"],"blocks":[{"t":"lead","x":"客户说：“我要 10 万次。”你先别答应。10 万次在仪表里是常规，在阀门里是高标准，在真空开关里是另一个量级。书里给了三个真实例子：管路补偿只要几次；恒温控制器要 1 万次；真空开关要 3 万次。同样是“波纹管”，寿命要求差四个数量级。这一课讲清楚：寿命不是材料的一个固定数，是工况的函数。"},{"t":"figure","name":"lifeCurve","cap":"位移越大，寿命越短；10 万次有条件"},{"t":"callout","kind":"note","title":"这一课接在哪","x":"第 11 课讲单次受载；这一课讲重复受载：同样 1.6 MPa，动一次和动十万次，寿命不是一回事。"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["N","大写 N","次","循环次数，到泄漏为止"],["w%","w 加百分号","%","位移占允许位移的比例"],["p%","p 加百分号","%","压力占耐压力的比例"],["w_g","w 下标 g","mm","工作位移"],["p_g","p 下标 g","MPa","工作压力"]]},{"t":"h2","x":"一、寿命的定义：到漏为止，不是到断为止"},{"t":"p","x":"（书 §2.3.4）波纹管的寿命是：在工作条件下，能保证正常工作的最短工作期限或循环次数。对弹性密封系统，更硬的定义是“从开始使用，到因疲劳产生泄漏为止的负荷变化次数”。不是“装上去几年”，也不是“没断就算”。"},{"t":"kv","items":[["补偿安装偏差","几次循环就够，寿命不是主要矛盾"],["恒温控制器（开关频繁）","约 10,000 次"],["真空开关（真空密封）","约 30,000 次"],["仪表静态微动","可达数万–数十万次"],["工程交变/弹塑性","可能只有数百–数千次"]]},{"t":"callout","kind":"warn","title":"“10 万次”必须带条件","x":"同样一件波纹管，工作在 10% 位移和 80% 位移，寿命可能差两个数量级；恒定压力和交变压力，同一位移下允许压力差 3 倍。客户只说“10 万次”，你无法判断能不能做。"},{"t":"h2","x":"二、寿命由什么决定：材料、应力、表面、工况"},{"t":"p","x":"（书 §2.3.4）波纹管寿命与材料的疲劳特性有关，也取决于成形后的残余应力、应力集中、表面质量；还跟工作位移、压力、温度、介质、振动、频率、冲击等工况有关。"},{"t":"table","head":["因素","怎么影响寿命","现场怎么问"],"rows":[["最大应力","应力幅越大，寿命越短；是主控因素","工作压力、位移、温度一起给"],["残余应力","成形/焊接/热处理留下的应力，叠加工作应力","是否做过去应力/稳定化处理"],["应力集中","波谷/波峰圆角小、壁厚不均，局部应力高","波型、圆角、壁厚公差"],["表面质量","划伤、裂纹、腐蚀坑是疲劳源","表面处理、洁净度、介质"],["位移幅","幅值越大，寿命断崖式下降","工作位移/允许位移的百分比"],["压力性质","交变比恒定更伤；压力冲击更伤","恒定/交变、冲击次数"],["温度/介质","高温降低材料强度，腐蚀加速裂纹","温度、介质、浓度"],["频率/振动","频率高、共振会加速失效","开关频率、系统振动"]]},{"t":"p","x":"书里有一句很重的话：波纹管在工作过程中，寿命长短主要取决于工作过程中产生的最大应力。为了降低应力，一般通过减少工作位移和降低工作压力来实现。这不是“保守”，是疲劳的物理规律：应力幅降一点，寿命升很多。"},{"t":"h2","x":"三、三条红线：0.5w、0.5p_n、10%–40%L₀"},{"t":"p","x":"（书 §2.3.4）一般设计中规定：工作位移应小于允许位移的一半，工作压力应小于耐压力的一半。"},{"t":"kv","items":[["位移红线","w_g ≤ 0.5w"],["压力红线","p_g ≤ 0.5p_n"],["经验结果","按这两条规范工作，寿命大致可达 5 万次左右"],["轴向位移范围","只承受轴向载荷时，允许位移可在 L₀ 的 10%–40% 选用"],["复合载荷","横向力、扭矩、综合受力时，允许位移要再减小"]]},{"t":"callout","kind":"key","title":"为什么是 0.5，不是 0.9","x":"疲劳寿命和应力幅不是线性关系。把位移从 50% 用到 90%，应力幅可能翻倍，寿命可能掉一个数量级。书里用 0.5 作为“长寿命设计”的起点；客户要 10 万次以上，往往还要再留余量，或者改多层、加波数、降刚度。"},{"t":"h2","x":"四、单层寿命图：p% 和 w% 两把尺"},{"t":"p","x":"（书 §2.3.4）单层波纹管承受压力并产生轴向位移时，寿命可以用图 2-42 估算。图的用法是：先算工作压力占最大耐压力的百分比 p%，再算工作位移占最大允许位移的百分比 w%，在左右刻度上找到两点，连线与中间刻度线的交点就是寿命。"},{"t":"p","x":"书里的算例：p_n=0.61 MPa、w=13.2 mm；实际 p_g=0.1 MPa、w_g=8 mm。p%=0.1/0.61×100%=16.4%；w%=8/13.2×100%=60.6%；查图得寿命约 50 万次。注意：这组数字里 w% 已经 60.6%，超过 0.5 红线，但压力很低（16.4%），所以寿命仍然很长。说明两个百分比要一起看，不能只看一个。"},{"t":"table","head":["工况","p%","w%","查图寿命（书例）","解读"],"rows":[["低压、中位移","16.4%","60.6%","约 50 万次","压力低，位移略超红线仍可接受"],["中压、大位移","30%","60%","多层约 1.3 万次","多层图更保守，按最低寿命画"],["高压、大位移",">50%",">50%","迅速下降","进入短寿命区，要改结构"]]},{"t":"callout","kind":"warn","title":"图是估算，不是保证","x":"书里的寿命图来自试验统计，单层图是平均值/经验曲线，多层图按试验最低寿命绘制、安全系数较大。真正报价要留裕度，并要求样品/批次试验。不要把查图值直接写成合同承诺。"},{"t":"h2","x":"五、多层为什么更长寿：刚度低、应力小"},{"t":"p","x":"（书 §2.3.4）多层波纹管可以降低刚度和变形引起的应力，因而能在很大程度上提高寿命。书里给了多层寿命图 2-43：在工作压力为最大耐压力 30%、工作位移为最大允许位移 60% 时，寿命约 13,000 次。"},{"t":"p","x":"注意这个例子和单层的差别：同样 60% 位移，单层在 16.4% 压力下能到 50 万次；多层在 30% 压力下只有 1.3 万次。不是多层更差，而是多层图按“最低寿命”画、且压力更高。多层解决的是“高压+大位移”下的应力问题，不是无条件延长寿命。"},{"t":"kv","items":[["多层刚度","同总壁厚下约为单层的 1/Z^1.5（书式2-7）"],["多层应力","变形应力降低，寿命提高"],["多层代价","层间摩擦、封焊、检漏、端部结构复杂，成本高"],["适用","高压 + 大位移 + 长寿命，三者同时要"],["不适用","低压小位移，多层是浪费"]]},{"t":"h2","x":"六、恒定压力 vs 交变压力：差 3 倍"},{"t":"p","x":"（书 §2.3.4）其它条件相同，交变载荷下寿命比恒定载荷短。书里给了图 2-44 的例子：要求位移为最大允许位移的 80%、工作 1 万次。"},{"t":"list","ordered":true,"items":["**恒定压力**：查图得工作压力不应超过最大耐压力的 60%。","**交变压力**：同样 80% 位移、1 万次，工作压力不应超过最大耐压力的 20%。","**差别**：60% vs 20%，正好 3 倍。","**现场含义**：客户说“压力 1 MPa”，要追问是稳定压力、脉动压力，还是每次开关都从 0 到 1 MPa。"]},{"t":"callout","kind":"key","title":"压力性质决定报价","x":"同样 1 MPa、同样 10 万次，恒定压力和交变压力的可选结构完全不同。交变压力下，你要么降压力、要么加波数/多层、要么缩短位移；否则寿命不够，售后必然来找你。"},{"t":"h2","x":"七、询价时怎么问：五个条件"},{"t":"list","ordered":true,"items":["**循环次数**：总寿命要求多少次？有没有试验验证要求？","**位移幅**：每次循环从哪到哪？是压缩、拉伸，还是拉压交替？","**压力幅**：恒定、脉动、交变？最大/最小压力各多少？","**温度/介质**：最高温度、腐蚀性、是否有颗粒？","**频率/安装**：开关频率、是否共振、有没有导向、同轴度多少？"]},{"t":"p","x":"这五个条件里，缺一个都可能让寿命估算失真。尤其是“位移幅”和“压力性质”：客户常给最大压力、最大行程，却不给循环中的最小值。疲劳看的是幅值，不是最大值。"},{"t":"callout","kind":"warn","title":"不要把“5 万次”写成万能承诺","x":"书里说按 0.5w、0.5p_n 规范工作，寿命“基本上可达 5 万次左右”。这是经验值，不是保证值。合同里要写清试验条件、判定标准（漏率/外观/尺寸），并留批次分散度。"},{"t":"h2","x":"八、寿命不够时，先改什么"},{"t":"list","ordered":true,"items":["**降位移**：最有效。位移降到 0.4w，寿命通常显著上升。","**降压力**：次有效。把 p_g 从 0.6p_n 降到 0.3p_n。","**加波数/加长 L₀**：同样位移分摊到更多波，单波应力下降；但要注意 L₀/D 稳定。","**改多层**：高压大位移场景，降低刚度/应力，但成本上升。","**改材料/热处理**：提高疲劳强度、消除残余应力；不是万能，先看失效模式。","**改波型/圆角**：降低应力集中；需要模具投入。"]},{"t":"p","x":"顺序很重要：先降工况，再改结构，最后换材料。很多“寿命不够”其实是客户把最大行程当工作行程、把试验压力当工作压力。先把工况问清楚，可能不用改产品。"},{"t":"h2","x":"九、自测"}],"sources":["书 §2.3.4 寿命","图 2-42、2-43、2-44","式 2-7 多层刚度关系"],"exam":{"pass":70,"minutes":15,"intro":"11 道题，覆盖本课的概念、数字与现场判断。答错会看到解释。","questions":[{"q":"波纹管寿命的严格定义是：","opts":["装上去能用几年","到因疲劳产生泄漏为止的循环次数","波纹管断裂前的次数","保修期"],"a":1,"why":"书里定义：从开始使用到因疲劳产生泄漏为止的负荷变化次数。"},{"q":"书里建议的长寿命设计红线是：","opts":["w_g≤0.9w，p_g≤0.9p_n","w_g≤0.5w，p_g≤0.5p_n","w_g≤w，p_g≤p_n","w_g≤0.1w，p_g≤0.1p_n"],"a":1,"why":"工作位移≤允许位移一半，工作压力≤耐压力一半；按此规范寿命大致可达 5 万次。"},{"q":"单层寿命图查图需要哪两个百分比？","opts":["p% 和 w%","温度和湿度","波数和层数","材料牌号和硬度"],"a":0,"why":"工作压力占最大耐压力的百分比 p%，工作位移占最大允许位移的百分比 w%。"},{"q":"书例 p_n=0.61、w=13.2、p_g=0.1、w_g=8，查图寿命约：","opts":["5 千次","5 万次","50 万次","500 万次"],"a":2,"why":"p%=16.4%，w%=60.6%，查图约 50 万次。"},{"q":"同样 80% 位移、1 万次，恒定压力允许的工作压力约为耐压的 60%，交变压力约为：","opts":["60%","40%","20%","10%"],"a":2,"why":"书里例子：交变压力下只能到 20%，正好是恒定压力的 1/3。"},{"q":"多层波纹管为什么能提高寿命？","opts":["材料更贵","降低刚度和变形应力","壁厚一定更厚","不需要焊接"],"a":1,"why":"多层降低刚度/变形应力，从而降低应力幅；但成本、封焊、检漏代价高。"},{"q":"客户说“10 万次”，最不该少问的是：","opts":["颜色","位移幅、压力性质、温度、介质、频率","包装箱材质","运输距离"],"a":1,"why":"寿命是工况函数，缺位移幅/压力性质/温度/介质/频率就无法判断。"},{"q":"寿命不够时，通常最先改的是：","opts":["换更贵的材料","降位移/降压力","加厚包装","改颜色"],"a":1,"why":"降工况最有效、成本最低；改结构/材料是后手。"},{"q":"多层寿命图 2-43 的数值为什么偏保守？","opts":["按试验最低寿命绘制","按理论最大值绘制","按材料手册抄的","按客户要求编的"],"a":0,"why":"书里明确：多层图按试验中得到的最低寿命值绘制，安全系数较大。"},{"q":"只承受轴向载荷时，允许位移可在 L₀ 的什么范围选用？","opts":["1%–5%","10%–40%","50%–80%","90%–100%"],"a":1,"why":"书里给的是 10%–40%；有横向力/扭矩时要再减小。"},{"q":"下面哪个不是影响寿命的工况因素？","opts":["工作位移","压力性质","介质温度","包装颜色"],"a":3,"why":"包装颜色与疲劳无关；位移、压力、温度、介质、频率、冲击都相关。"}]}},"13":{"title":"液压成形：一根管子怎么被“吹”成波纹","sub":"液压成形是波纹管最常用的工艺，但报价不是“按公斤算”。这一课按书里 §2.4.2.1 讲清：管坯多长、定位器多高、要多大压力、模具怎么分片，以及为什么同尺寸有人报 800、有人报 3000。","tags":["第2章","制造","液压成形","模具","管坯","报价"],"objectives":["说清液压成形的四个步骤：起鼓、定位、压合、卸压","会用式 2-64/2-65 估算 U 型单波展开长和管坯总长","知道成形压力 p=2hσ_b/d 和成形力 F=A_e·p 的物理意义","分清多波一次成形和单波连续成形的适用场景","知道模具、分片、设备吨位为什么推高成本","拿到图纸能判断“这个波能不能液压成形、要不要焊接”"],"blocks":[{"t":"lead","x":"客户问：“这个波纹管多少钱？”图纸上 D=40、d=32、t=4.8、n=12、h₀=0.12。你不能只算材料费。液压成形要先算管坯多长、要几套模具、要多大吨位、分片怎么分；这些工装费摊到批量上，才是报价的大头。"},{"t":"figure","name":"hydroSteps","cap":"管坯→装模→加压→成形"},{"t":"callout","kind":"note","title":"这一课接在哪","x":"第 12 课讲寿命；这一课讲寿命是怎么做出来的：一根管子怎么被液压“吹”成波纹。"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["L₁","L 下标 1","mm","单波展开长度"],["L","大写 L","mm","成形管坯总长度"],["n","小写 n","个","波数"],["H","大写 H","mm","定位器高度"],["p","小写 p","MPa","成形压力"],["F","大写 F","kN","成形力"],["A_e","A 下标 e","cm²","有效面积"]]},{"t":"h2","x":"一、液压成形：用油把管子胀进模具"},{"t":"p","x":"（书 §2.4.2.1）液压成形是金属波纹管应用最广泛、最常见的一种成形方法，主要用来制造环形波纹管，可成形壁厚 0.08–4 mm 的波纹管。管坯在内壁液体压力下，应力超过屈服强度后，在专用模具内成形为波纹管。"},{"t":"list","ordered":true,"items":["**起鼓**：成形模片按单波展开长定位，管坯内充液压，局部鼓起。","**压合**：卸除定位器，成形机活塞推动模片下移，管坯在成形压力下变形成波。","**贴靠**：活塞继续推动模片贴靠，卸压，一个波成形完毕。","**循环**：多波一次成形是一次压合所有波；单波连续成形是逐波进给、逐波压合。"]},{"t":"callout","kind":"key","title":"不是“吹气球”","x":"管子起鼓后，模具的波距、波高、圆角决定最终形状。压力太小，波高不够；压力太大，波峰减薄甚至胀裂。成形压力要按材料抗拉强度和壁厚算，再按批次调整。"},{"t":"h2","x":"二、管坯多长：先算单波展开长"},{"t":"p","x":"（书 §2.4.2.1）U 型波的单波展开长按式 2-64 计算。思路是把一个波展开成“两段圆弧 + 两段直线”，再乘 2。"},{"t":"callout","kind":"key","title":"式 2-64","x":"L₁ = D − d + 1.14a − 3.14h₀。L₁ 是单波展开长（mm）；D 外径；d 内径；a 波厚；h₀ 壁厚。"},{"t":"p","x":"式子的来源：D₂=D−h、d₂=d+h、2r=a−h；单波展开长 = D₂−d₂+1.14(2r) = D−d+1.14a−3.14h。不用背推导，但要记住：波越深（D−d 大）、波厚越大（a 大），管坯越长；壁厚越大，展开长略短。"},{"t":"p","x":"例（教学示例）：D=40、d=32、a=3、h₀=0.12。L₁=40−32+1.14×3−3.14×0.12=8+3.42−0.377≈11.04 mm。12 个波约 12×11.04≈132.5 mm，再加两端接口和工艺余量。"},{"t":"p","x":"（书 §2.4.2.1）管坯总长按式 2-65：L = nL₁ + L₂ + L₃。L₂ 是内配合接口展开长，L₂=D₁−d+H′+C；L₃ 是工艺密封长度；C 是工艺翻边附加量，取 1–2 mm。"},{"t":"callout","kind":"warn","title":"管坯短了，波高不够；长了，端部起皱","x":"L₁ 算错，后面全错。书里提醒：定位器高度 H=L₁−H_m（式 2-66），H_m 是模片厚度；多波一次成形时所有定位器高度必须一致；单波连续成形时每次定位重复性要好。定位器高度直接决定波高。"},{"t":"h2","x":"三、要多大压力：p=2hσ_b/d"},{"t":"p","x":"（书 §2.4.2.1）成形压力是管坯在液体压力下发生塑性变形、形成波的压力。简化计算只考虑切向拉应力，忽略较小的母线方向应力，取一个圆环带分析，得 p=2hσ₁/d；考虑加工硬化，用抗拉强度 σ_b 代替屈服强度，得到式 2-67。"},{"t":"callout","kind":"key","title":"式 2-67","x":"p = 2·h·σ_b / d。p 是成形压力（MPa）；h 是壁厚（mm）；σ_b 是抗拉强度（MPa）；d 是内径（mm）。"},{"t":"p","x":"例：h=0.12、σ_b=900 MPa（不锈钢）、d=32，则 p=2×0.12×900/32≈6.75 MPa。实际成形压力要按批次调整：材料硬、模具间隙小，压力高一点；材料软、润滑好，压力可低一点。书里明确：成形压力与每批管坯原料状态有关。"},{"t":"p","x":"（书 §2.4.2.1）成形力按式 2-68：F=A_e·p。成形过程中有效面积不断变化，直到成形完毕达到最大；只要活塞推力能克服最大有效面积和成形压力构成的反力，成形就能完成。F 的单位是 kN，A_e 用 cm²，p 用 MPa。"},{"t":"callout","kind":"warn","title":"压力不是越高越好","x":"压力过高：波峰减薄、胀裂、模具磨损；压力过低：波高不足、回弹大、波距不均。公式是起点，不是终点；调机师傅的经验和试模同样重要。"},{"t":"h2","x":"四、两种工艺：多波一次 vs 单波连续"},{"t":"table","head":["工艺","怎么成形","适合","优缺点"],"rows":[["多波一次成形","所有模片一次压合，所有波同时成形","中小型、批量大、波数不太多","效率高；模具/设备吨位大，调机难"],["单波连续成形","管坯逐波进给，模具重复分合、逐波压合","U 型长波纹管、金属软管","设备小；效率低，波距一致性靠送进精度"],["螺旋波纹管","圆柱弹簧模，多波一次","大中尺寸、波数不多的螺旋管","模具特殊；小尺寸多波用机械法"]]},{"t":"p","x":"（书 §2.4.2.1）多波一次成形的自动机程序是：装料→合模→分片→充压→保压→成形进缸→卸压→退缸→分模→卸件。单波连续成形的程序是：合模→充压→推进压合→卸压→开模→退压合→退芯轴→合模→进芯轴。程序不同，节拍和工装完全不同。"},{"t":"h2","x":"五、模具：为什么同尺寸工装费差几倍"},{"t":"p","x":"（书 §2.4.2.1）液压成形模具有两种基本结构：整体结构和铰链结构。"},{"t":"kv","items":[["整体结构","结构简单、制造方便，靠模套与模具外边缘滑动配合；适合手动、多层、量小、多规格"],["铰链结构","模片+模板，铰链连接；结构复杂、精度要求高，适合自动机、大批量 U 型"],["模腔外径","D₂=D+(3–6) mm（式2-69）"],["模腔内径","d₂=d₁+2h+(0.1–0.2) mm（式2-70）"],["模腔圆角","R=(t−2h)/4（式2-71）"],["斜角 α","通常 2°–8°"],["模片厚度 H_m","按波距 t 的 0.85–0.9 取"],["模具硬度","HRC 35–45"]]},{"t":"p","x":"分片机构是把多个模片按单波展开长均匀定位的装置。书里列了人工分片、阶梯轴分片、套轴连动分片、螺旋分片、梳形分片、电磁分片。自动成形最常用阶梯轴分片：四根高精度台阶轴，两根正分片、两根反分片，结构简单、定位可靠。套轴连动分片适应不同展开长，换型只需调套垫高度，能降工装成本。"},{"t":"callout","kind":"key","title":"报价里最容易漏的三项","x":"① 模具：整体模便宜、铰链模贵；多规格要换模片。② 分片/调机：波数越多、定位越多，调机时间越长。③ 设备吨位：成形力 F=A_e·p，大口径/厚壁要更大吨位，外协价差很大。"},{"t":"h2","x":"六、液压成形的边界：什么时候不该用"},{"t":"list","ordered":true,"items":["**k=D/d 太大**：k≥2 液压成形困难，书里建议改焊接波纹管；k=1.6–1.9 可能两次成形。","**壁厚太薄/太厚**：书里给的范围是 0.08–4 mm；超出要评估。","**波数太多、L₀ 太长**：多波一次模具过长，单波连续效率低；还要考虑 L₀/D 稳定。","**多层**：多层液压成形可行，但层间容易夹液、错位，封焊/检漏成本高。","**小直径/异形**：外径小于 6 mm 液压成形很困难，电沉积更合适。","**超高精度波距**：液压回弹、模具磨损影响一致性，可能要整形/稳定化。"]},{"t":"p","x":"（书 §2.4.2.1）液压成形后还要整形、热处理、表面处理、稳定化。书里说成形后由于弹性回弹，波距、波型与设计有差异，必须整形。所以“成形”只是中间工序，报价不能只算成形。"},{"t":"h2","x":"七、现场常见缺陷：先看是哪一类"},{"t":"table","head":["缺陷","常见原因","责任归属"],"rows":[["波高不够","压力低、管坯短、定位器低、材料硬","工艺/模具"],["波峰减薄/胀裂","压力高、材料塑性差、圆角小","工艺/材料"],["波距不均","分片定位不准、送进重复性差、回弹","设备/模具"],["端部起皱","管坯长、端部约束不足、润滑差","工艺"],["波侧划伤","模具表面粗糙、润滑不足、有异物","模具/现场"],["层间错位（多层）","多层管坯松动、成形时层间摩擦","工艺/工装"]]},{"t":"callout","kind":"warn","title":"别把“调机问题”当“材料问题”","x":"同样一批材料，换一套模具/调一次压力就好了，说明不是材料。报价时若客户说“上次做的波高不够”，先问：是首件还是批量？是全部还是局部？压力/管坯/定位器有没有记录？"},{"t":"h2","x":"八、自测"}],"sources":["书 §2.4.2.1 液压成形","式 2-64～2-71","图 2-52、2-53、2-54、2-55"],"exam":{"pass":70,"minutes":15,"intro":"11 道题，覆盖本课的概念、数字与现场判断。答错会看到解释。","questions":[{"q":"液压成形 U 型单波展开长公式是：","opts":["L₁=D−d+1.14a−3.14h₀","L₁=D+d+1.14a","L₁=πD","L₁=n·t"],"a":0,"why":"书里式 2-64：L₁=D−d+1.14a−3.14h₀。"},{"q":"管坯总长 L 的组成是：","opts":["nL₁+L₂+L₃","nL₁−L₂","L₁+L₂","πDn"],"a":0,"why":"式 2-65：n 个单波展开长 + 内配合接口展开长 L₂ + 工艺密封长度 L₃。"},{"q":"成形压力 p 的简化公式是：","opts":["p=2hσ_b/d","p=σ_b d/h","p=Eh/d","p=F/A_e"],"a":0,"why":"式 2-67：p=2hσ_b/d；F=A_e·p 是成形力，不是压力。"},{"q":"定位器高度 H 与单波展开长 L₁、模片厚度 H_m 的关系是：","opts":["H=L₁+H_m","H=L₁−H_m","H=H_m−L₁","H=L₁×H_m"],"a":1,"why":"式 2-66：H=L₁−H_m；定位器高度直接决定波高。"},{"q":"多波一次成形最适合：","opts":["单件、超大直径","中小型、批量大、波数不太多","所有螺旋管","外径小于 1 mm"],"a":1,"why":"多波一次效率高，但模具/设备吨位大；超大直径/小直径另有工艺。"},{"q":"k=D/d≥2 时，书里建议优先考虑：","opts":["液压成形","焊接波纹管","滚压成形","橡胶成形"],"a":1,"why":"书里明确：k≥2 液压成形困难，宜用焊接波纹管。"},{"q":"整体结构模具与铰链结构模具的主要差别是：","opts":["整体模适合手动/多规格，铰链模适合自动/大批量","整体模更贵","铰链模不能换模片","两者完全一样"],"a":0,"why":"整体模结构简单、适合手动和多规格；铰链模精度高、适合自动机大批量 U 型。"},{"q":"成形力 F 的单位组合，正确的是：","opts":["A_e(cm²)×p(MPa)=kN","A_e(mm²)×p(MPa)=N","A_e(m²)×p(Pa)=kN","以上都不对"],"a":0,"why":"书里式 2-68 用 A_e(cm²)、p(MPa)，得到 F(kN)。"},{"q":"下面哪项不是液压成形的典型缺陷？","opts":["波高不够","波峰胀裂","波距不均","材料牌号写错"],"a":3,"why":"牌号写错是文件/采购问题，不是成形缺陷。"},{"q":"为什么液压成形后还要整形？","opts":["为了好看","弹性回弹导致波距/波型与设计有差异","为了增加壁厚","为了换材料"],"a":1,"why":"书里明确：成形后弹性回弹使波距、波型与设计有差异，必须整形。"},{"q":"客户给 D=40、d=32、a=3、h₀=0.12，单波展开长约：","opts":["8 mm","11 mm","14 mm","20 mm"],"a":1,"why":"L₁=40−32+1.14×3−3.14×0.12≈11.04 mm。"}]}},"14":{"title":"滚压、旋压、焊接管坯：不是所有波纹都靠“吹”","sub":"液压成形能做 U 型，但大口径、厚壁、螺旋、膨胀节、金属软管，往往走机械成形或焊接管坯。这一课按书里 §2.4.1 和 §2.4.2.2，讲清四条路线的边界、焊缝和成本。","tags":["第2章","制造","滚压","旋压","焊接","管坯","工艺边界"],"objectives":["分清机械旋压、机械胀形、滚压、橡胶成形的适用边界","知道焊接管坯为什么适合大口径/薄壁/膨胀节，以及焊缝是薄弱点","记住不锈钢/碳钢的波深系数上限：K<1.3 / K<1.2","看懂焊接管坯的四个关键：下料、翻边、收弧间隙、夹具散热","知道多层管坯的套管间隙为什么按 0.10–0.5 mm 分级","拿到图纸能判断“液压、机械、焊接”三条路线该走哪条"],"blocks":[{"t":"lead","x":"客户给了一张大口径膨胀节图纸：D=800、壁厚 1.0、波数 4。你按液压成形去报价，发现设备吨位不够、模具太大；换焊接管坯+机械胀形，成本反而低。这一课讲的就是：同样叫“波纹管”，成形路线不止一条，选错路线报价一定错。"},{"t":"figure","name":"rollSpinWeld","cap":"滚压、旋压、焊接；三条路线各有边界"},{"t":"callout","kind":"note","title":"这一课接在哪","x":"第 13 课讲液压成形；这一课讲另外三条路：滚压、旋压、焊接管坯。不是所有波纹都靠“吹”。"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["k","小写 k","无量纲","k=D/d"],["K","大写 K","N/mm","刚度"],["φ","希腊字母 phi","mm","直径，常写 φ60"],["D/d","大写 D 除以小写 d","—","外径/内径"],["t","小写 t","mm","波距；不是壁厚"]]},{"t":"h2","x":"一、四条路线：液压、机械、橡胶、焊接"},{"t":"table","head":["路线","怎么成形","最适合","主要限制"],"rows":[["液压成形","内压起鼓+模具压合","中小口径 U 型、批量","k≥2 困难；模具/吨位"],["机械旋压","旋转螺旋模，轴向+径向挤压","φ60 以下螺旋波纹软管","波深受限；表面较粗"],["机械胀形","锥芯+扇形凸模，径向顶开","φ100–1500 膨胀节","K 受延伸率限制"],["滚压","主/从动轮径向进给","大直径、厚壁、少波","不锈钢 K<1.3；碳钢 K<1.2"],["橡胶成形","橡胶凸模+凹模","单波连续、中小口径","橡胶寿命/压力限制"],["焊接管坯","板卷+纵缝焊，再成形","大口径、薄壁、膨胀节/软管","焊缝质量、变形"]]},{"t":"p","x":"（书 §2.4.2.2）机械成形包括旋压、滚压和机械膨胀。一般来说，机械成形工艺简单、工装制造容易、生产效率高；同时也存在产品制造比较粗糙、性能不高等缺点。它较多应用于螺旋波纹管、波纹膨胀节、大直径厚壁波纹管的制造。"},{"t":"h2","x":"二、机械旋压：φ60 以下螺旋管的常用法"},{"t":"p","x":"（书 §2.4.2.2）机械旋压成形是管坯在旋转的、径向和轴向都由螺旋面构成的成形模具内进给时，轴向和径向受到挤压应力变形成波的一种连续成形方法。它是成形 φ60 mm 以下螺旋波纹软管常用的工艺方法。"},{"t":"p","x":"工艺关键在于螺旋成形模的设计、调整、旋压进给速度和润滑。模具由模座、成形片、调整块组成。因为只有一个旋转运动就能完成进料、成形、出料，所以很容易自动化；书里提到，国外不少厂家用精密定宽成卷带料，连续自动卷筒、连续自动焊接后，自动连续螺旋成形。"},{"t":"callout","kind":"key","title":"旋压的“边界”","x":"旋压适合细长的螺旋软管，不适合大波深、厚壁、少波的环形件。它的波深受材料延伸率和模具螺旋角限制；表面质量不如液压成形，通常用于金属软管，不用于高精度仪表件。"},{"t":"h2","x":"三、机械胀形：大口径膨胀节的主力"},{"t":"p","x":"（书 §2.4.2.2）机械胀形利用分块凸模，由锥形芯体顶开，使管坯胀出波形。它广泛用于膨胀节用金属波纹管，目前常用于制造通径 φ100–1500 mm 的波纹管。"},{"t":"p","x":"机构由锥形芯轴、多个扇形凸模、波距定位装置、凸模导向柱、复位弹簧组成；可以做成正压式（放在压力机上）或反推式（模具自身与拉杆/油缸形成封闭系统，不需要压力机）。成形时芯轴受集中力 F 进给，凸模在斜面水平分力作用下被推出，克服变形力和摩擦力，靠限位器控制波高。"},{"t":"p","x":"（书 §2.4.2.2）机械胀形力可按式 2-72 估算：F=2πHhσ_b(μ+tanβ)/(1−μ²−2μtanβ)。F 是胀形力（N）；β 是芯轴半锥角；σ_b 抗拉强度；h 管坯总壁厚；H 波展开长。这个式子的工程意义：锥角越大、摩擦越大，需要的力越大；但锥角太大，导向/自锁会出问题。"},{"t":"p","x":"胀形波高受材料极限延伸率限制，用胀形系数 K=d_max/d 表示。书里表 2-16：0Cr19Ni9/00Cr17Ni14Mo2，厚度 0.5 mm 时 K=1.26–1.32，1.0 mm 时 K=1.28–1.34；低碳钢 0.5 mm 时 K=1.2，1.0 mm 时 K=1.24。超过这个系数，材料会裂。"},{"t":"callout","kind":"warn","title":"胀形系数不是波深系数","x":"胀形系数 K=d_max/d 是“胀后最大直径/管坯直径”，波深系数 k=D/d 是“波纹管外径/内径”。两个 K 容易混。报价时若客户说“k=1.8”，你要判断是波深还是胀形；胀形系数 1.8 对不锈钢已经远超极限。"},{"t":"h2","x":"四、滚压：大直径、厚壁、少波"},{"t":"p","x":"（书 §2.4.2.2）滚压成形是管坯在主动轮和一对从动轮带动旋转下，靠径向进给使管坯成形。主动轮由机械/液压马达驱动，一对从动轮由液压缸推动上下进给，并能水平移动；成形时从动轮间距调到波展开长，主/从动轮压紧管坯，管坯随主动轮同步旋转，从动轮逐渐上升加力并向主动轮靠拢，管坯塑性变形成波。"},{"t":"p","x":"（书 §2.4.2.2）滚压适用于制造大直径、大壁厚、波数少的环形波纹管。由于受材料允许变形程度限制，滚压和胀形一样，波深系数较小：不锈钢通常 K<1.3，碳钢 K<1.2。"},{"t":"callout","kind":"key","title":"为什么滚压做不了深波","x":"滚压是局部连续塑性变形，材料在轮下被“擀”薄；波越深，需要的延伸率越大，表面也越容易起皮/开裂。深波、薄壁、高精度，还是液压成形更合适。"},{"t":"h2","x":"五、橡胶成形：软凸模，单波连续"},{"t":"p","x":"（书 §2.4.2.2）橡胶成形是胀形工艺的一种：以橡胶为成形凸模，在压力作用下橡胶变形，把管坯按凹模型腔成形。通常采用单波连续成形。"},{"t":"p","x":"橡胶成形的优点是模具简单、对材料表面损伤小；缺点是橡胶寿命有限、压力不能太高、波深受限。适合中小口径、批量不大、表面要求较高的场合。报价时要问：橡胶模多久换一次？换模摊到单价里是多少？"},{"t":"h2","x":"六、焊接管坯：大口径/薄壁的必经之路"},{"t":"p","x":"（书 §2.4.1）用焊接方法制造波纹管管坯，生产效率高、成本低、壁厚容易控制、适应性强。目前多用于制造膨胀节用大直径波纹管管坯和制造软管用管坯。焊接方法主要是气体保护直流氩弧焊、微弧等离子焊、激光焊；焊接厚度 0.16–1.0 mm；材料为 1Cr18Ni9Ti、0Cr18Ni9、00Cr17Ni14Mo2、GH169 等。"},{"t":"p","x":"（书 §2.4.1）焊接管坯的四个关键：① 剪板下料尺寸精度 ±0.2–0.5 mm（大直径取大值，小直径取小值），裁边平直无毛刺；② 厚度小于 0.2 mm 时，焊边翻边对接，翻边量 0.3–0.7 mm，增加板边刚度、减小变形、提高电流、减小电弧漂移；③ 收弧端预留 1–2 mm 间隙，补偿焊缝冷却收缩，防止搭叠；④ 夹具要可靠约束近缝区并迅速均匀散热，整体式压板比琴键式更常用。"},{"t":"table","head":["板厚/mm","焊口形式","电流/A","电弧长/mm","速度/(mm/min)","氩气/(L/min)"],"rows":[["0.16","翻边对焊","7–7.5","0.5–0.8","600","10–15"],["0.20","翻边对焊","8–10","0.5–0.8","500–600","10–15"],["0.30","平边对焊","15–20","0.5–0.8","450–550","10–15"],["0.40","平边对焊","25–30","0.5–0.8","400–500","10–15"],["0.50","平边对焊","35–40","0.5–0.8","350–450","10–15"]]},{"t":"callout","kind":"warn","title":"焊缝是薄弱点，不是“多一道工序”","x":"焊接管坯的纵缝会保留到成品上，焊缝的晶粒、残余应力、错边、气孔都是疲劳源。客户如果要求高寿命/高真空，焊接管坯的焊缝要全检（RT/UT/PT/氦检），成本要算进去。不要拿“液压成形无缝”的价格去报焊接管坯。"},{"t":"h2","x":"七、多层管坯：套管间隙为什么分级"},{"t":"p","x":"（书 §2.4.1）多层波纹管耐压高、刚度小、位移大，常用来制造膨胀节和无泄漏阀门用波纹管。多层管坯的制造有两种思路：分别做出各层管坯，按间隙顺序套管；或者用同一基本管坯，缩径/扩径改制成各层。"},{"t":"kv","items":[["膨胀节多层（内径>φ80）","焊接管坯预留套管间隙 0.2–0.5 mm"],["阀用多层（内径<φ60）","轧制/旋压分层，间隙 0.10–0.15 mm"],["改制层（缩径/扩径）","间隙 0.15–0.2 mm，直径公差略低"],["套管状态","硬态套管后热处理/酸洗，层间清洁度难保证；软态先热处理酸洗再套管，层间质量更可靠"]]},{"t":"p","x":"这段对报价很实用：多层不是“多几层材料”那么简单，套管、封焊、检漏、层间清洁都是工时。客户说“做三层”，你要问：层间要不要抽真空/充气？要不要逐层检漏？端部怎么封？"},{"t":"h2","x":"八、四条路线怎么选：一张判断表"},{"t":"table","head":["图纸特征","优先路线","理由"],"rows":[["D<60、U 型、批量、k<1.8","液压成形","精度/效率/成本平衡"],["D<60、螺旋软管","机械旋压","连续成形、适合细长"],["D=100–1500、少波、膨胀节","机械胀形/焊接管坯","设备吨位/模具限制"],["D 大、壁厚、波数少","滚压","局部连续变形"],["D 大、薄壁、长、膨胀节","焊接管坯+液压/机械","板幅/管坯来源"],["k≥2、深波","焊接波纹管（第4章）","液压/机械都困难"],["外径<6、异形","电沉积（第3章）","模具/成形极限"]]},{"t":"callout","kind":"key","title":"报价前先问“管坯怎么来”","x":"同样一张图，用无缝管坯和焊接管坯，材料利用率、焊缝检测、热处理、报废率都不同。客户只给成品图，你要主动问：允许纵缝吗？有缝/无缝？焊缝等级？这决定成本，不是细节。"},{"t":"h2","x":"九、自测"}],"sources":["书 §2.4.1 管坯制造（含焊接管坯）","书 §2.4.2.2 机械成形","式 2-72、2-73","表 2-15、2-16"],"exam":{"pass":70,"minutes":15,"intro":"11 道题，覆盖本课的概念、数字与现场判断。答错会看到解释。","questions":[{"q":"机械旋压最适合：","opts":["φ60 以下螺旋波纹软管","φ800 膨胀节","深波 U 型仪表件","外径 1 mm 电沉积件"],"a":0,"why":"书里明确：机械旋压是成形 φ60 mm 以下螺旋波纹软管的常用工艺。"},{"q":"机械胀形常用于：","opts":["φ100–1500 mm 膨胀节","φ1 mm 以下","所有仪表件","只用于铜合金"],"a":0,"why":"书里：机械胀形广泛用于膨胀节用波纹管，通径 φ100–1500 mm。"},{"q":"不锈钢滚压成形的波深系数通常限制在：","opts":["K<1.1","K<1.3","K<1.6","K<2.0"],"a":1,"why":"书里：不锈钢通常 K<1.3，碳钢 K<1.2。"},{"q":"胀形系数 K 的定义是：","opts":["D/d","d_max/d","L₀/D","h₀/d"],"a":1,"why":"K=d_max/d，胀后最大直径/管坯直径；不是波深系数 D/d。"},{"q":"焊接管坯的收弧端为什么要留 1–2 mm 间隙？","opts":["为了好看","补偿焊缝冷却收缩，防止搭叠","为了省材料","为了增加壁厚"],"a":1,"why":"书里：结晶金属冷却收缩会使焊接末端收拢，严重时搭叠；收弧端预留间隙并随时调整压紧。"},{"q":"厚度小于 0.2 mm 的焊接管坯，通常采用：","opts":["平边对焊","翻边对焊","搭接焊","钎焊"],"a":1,"why":"书里：小于 0.2 mm 采用焊边翻边对接，翻边量 0.3–0.7 mm，增加板边刚度、减小变形。"},{"q":"膨胀节用多层管坯（内径>φ80）的套管间隙一般取：","opts":["0.01–0.05 mm","0.2–0.5 mm","1–2 mm","5 mm"],"a":1,"why":"书里：膨胀节多层管坯预留间隙 0.2–0.5 mm；阀用多层 0.10–0.15 mm。"},{"q":"多层管坯“软态套管”比“硬态套管”好的主要原因是：","opts":["更便宜","先热处理酸洗，层间表面光洁、无多余物","更硬","不用封焊"],"a":1,"why":"书里：硬态套管后还要热处理/酸洗，层间清洁度难保证；软态先处理干净再套管，层间质量更可靠。"},{"q":"下面哪项不是机械成形的共同缺点？","opts":["产品较粗糙","性能不如液压","工装复杂","适合大直径厚壁"],"a":3,"why":"“适合大直径厚壁”是优点/适用场景，不是缺点；机械成形缺点是粗糙、性能较低。"},{"q":"客户图纸 D=900、壁厚 1.0、波数 4、膨胀节，最优先考虑：","opts":["液压成形整体模","焊接管坯+机械胀形/滚压","电沉积","机械旋压"],"a":1,"why":"大口径、薄壁、少波膨胀节，焊接管坯+机械胀形/滚压更现实；整体液压模吨位/模具不经济。"},{"q":"焊缝为什么是高寿命产品的薄弱点？","opts":["颜色不同","晶粒/残余应力/错边/气孔是疲劳源","焊缝更厚","焊缝不导电"],"a":1,"why":"焊缝组织与母材不同，残余应力和缺陷会降低疲劳强度；高真空/高寿命要全检。"}]}},"15":{"title":"热处理与稳定化：为什么同样尺寸，寿命差一倍","sub":"波纹管成形后有残余应力，尺寸会“回弹”，弹性会漂移。这一课按书里 §2.4.5–§2.4.6 讲清：整形、热稳定、机械稳定、时效，各自解决什么问题，温度和时间为什么不能拍脑袋。","tags":["第2章","制造","热处理","稳定化","整形","残余应力"],"objectives":["分清整形、热稳定、机械稳定、时效四件事","记住书里表 2-18 的三组热稳定参数，并知道它不是“固溶”","知道机械稳定的频率、幅度、次数：14–40 次/min、0–w_max、200 次","理解为什么去应力温度不能太高：会软化、会晶粒长大","知道表面处理/钝化对耐蚀和洁净的作用","拿到技术要求，能判断“去应力/固溶/时效”该不该报进成本"],"blocks":[{"t":"lead","x":"同样一张图、同样材料，A 厂报 1200、B 厂报 800。差别可能不在材料，而在热处理：A 厂做了去应力+机械稳定，B 厂只做了成形。客户用三个月就发现零位漂了、寿命不够，回头找的是你。这一课把“热处理”从一句“按图做”拆成可验收的工序。"},{"t":"figure","name":"heatTreat","cap":"去应力管尺寸，稳定化管刚度/寿命"},{"t":"callout","kind":"note","title":"这一课接在哪","x":"第 14 课讲成形；这一课讲成形之后为什么要热处理和稳定化，为什么同样尺寸寿命差一倍。"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["T","大写 T","°C","热处理温度"],["t","小写 t","h","保温时间"],["w_max","w 下标 max","mm","最大位移，机械稳定用"],["σ","希腊字母 sigma","MPa","残余应力"]]},{"t":"h2","x":"一、四件事：整形、热稳定、机械稳定、时效"},{"t":"table","head":["工序","解决什么","典型对象","书里位置"],"rows":[["整形","回弹导致波距/波型不对","液压/机械成形件","§2.4.5"],["热稳定","消除残余应力、稳定弹性/尺寸","加工硬化型材料","§2.4.6"],["机械稳定","强制位移循环，稳定几何/弹性","有特殊要求件","§2.4.6"],["时效","析出强化相、定型","弥散硬化型材料","§2.4.5/§2.4.6"]]},{"t":"p","x":"（书 §2.4.5）波纹管成形后，由于弹性回弹，波距、波型都与设计要求有差异，必须整形。加工硬化材料一般用手工/机械整形；弥散硬化材料装入时效夹具内时效，使波纹管定型，同时达到整形效果。"},{"t":"callout","kind":"key","title":"整形不是“掰一掰”","x":"手工整形用芯轴+两半垫片，压缩到波距/波厚；机械整形用内外滚轮，适合 φ55–200 mm，特别是多层。整形会引入新的冷作应力，所以后面还要稳定处理。"},{"t":"h2","x":"二、热稳定：温度低、时间长，不是固溶"},{"t":"p","x":"（书 §2.4.6）波纹管在加工过程中会产生内应力，使弹性和几何尺寸不稳定。稳定处理的目的是消除应力、稳定性能、稳定几何尺寸。一般只做热稳定，有特殊要求才做机械稳定。"},{"t":"table","head":["材料","加热温度/℃","保温时间/h"],"rows":[["黄铜 H80","80±5","8"],["锡磷青铜 QSn6.5-0.1","180±5","6"],["不锈钢","250–300","3–4"]]},{"t":"callout","kind":"warn","title":"这不是固溶，也不是退火","x":"不锈钢 250–300℃ 只能去应力，不能溶解碳化物、不能软化；固溶是 1000℃ 以上快冷，完全不同的工序。客户图纸写“去应力”你按固溶报价，成本会高一个量级；写“固溶”你按去应力做，耐蚀性不够。"},{"t":"p","x":"（书 §2.4.6）弥散硬化型材料（如 QBe2、3J1、Ni36CrTiAl）的时效热处理，使不稳定的过饱和固溶体在加热温度下析出弥散相，既强化材料又稳定组织，同时消除加工应力。所以时效就是这类材料的热稳定处理。"},{"t":"p","x":"热稳定要在烘箱或真空炉内做，温度和保温时间要均匀；装炉方式要防止波纹管变形。书里给的是工艺参数，不是“随便烤一下”；温度高了会软化、晶粒长大，温度低了应力去不干净。"},{"t":"h2","x":"三、机械稳定：用 200 次循环把尺寸“走熟”"},{"t":"p","x":"（书 §2.4.6）机械稳定参照有关标准：频率 14–40 次/min，幅度 0–w_max（最大允许位移），稳定次数 200 次。幅度指从原始长度到最大允许位移。波纹管固定在专用夹具上，在疲劳试验机上进行。"},{"t":"kv","items":[["频率","14–40 次/min"],["幅度","0 → w_max（最大允许位移）"],["次数","200 次"],["目的","让残余应力/微观塑性提前释放，稳定零位和刚度"],["代价","要上疲劳试验机，工时/设备成本；不是所有件都做"]]},{"t":"p","x":"机械稳定和“疲劳寿命试验”不是一回事：前者是工艺手段，200 次就够；后者是验证手段，要跑到客户要求的次数。报价时客户说“要稳定处理”，先问是热稳定还是机械稳定，两者成本差很多。"},{"t":"h2","x":"四、表面处理：不只是“洗干净”"},{"t":"p","x":"（书 §2.4.4）铜合金表面处理包括除油、疏松氧化皮、弱酸洗、光亮酸洗、钝化；不锈钢也有除油、酸洗、钝化。钝化的目的是形成致密氧化膜，提高耐蚀性；酸洗是去除氧化皮/游离铁；除油是保证后续镀层/焊接/洁净。"},{"t":"list","ordered":true,"items":["**除油**：碱性或乳化液，温度/时间按配方；油不除干净，酸洗不均、钝化不上。","**酸洗**：去除氧化皮和表面贫铬层；过度酸洗会过腐蚀、尺寸变薄。","**钝化**：硝酸/柠檬酸体系，形成钝化膜；不钝化的不锈钢在氯离子环境更容易点蚀。","**洁净**：真空/半导体件还要去离子水冲洗、烘干、包装；颗粒/油分是放气源。"]},{"t":"callout","kind":"key","title":"表面处理影响报价的三点","x":"① 是否电解抛光（比钝化贵）；② 是否无尘清洗/包装；③ 是否有盐雾/蓝点/颗粒检测。客户只说“不锈钢”，不等于只做钝化。"},{"t":"h2","x":"五、热处理常见错误：温度、时间、装炉、气氛"},{"t":"table","head":["错误","后果","怎么避免"],"rows":[["温度过高","软化、晶粒长大、刚度下降","按表 2-18；用炉温记录仪"],["时间不足","残余应力去不净、零位漂","保温时间从到温算，不是从进炉算"],["装炉挤压","波形变形、波距不均","专用夹具/自由放置"],["气氛不纯","氧化、增碳、腐蚀","真空/保护气氛；不锈钢避免氯"],["反复热处理","晶粒粗化、性能下降","合并工序；记录次数"],["把去应力当固溶","耐蚀性不够/成本错","看图纸标准；问客户意图"]]},{"t":"p","x":"书里还提到：加工硬化材料冷作后，要在足够高的温度下保温，使加工硬化组织恢复；但温度不能高到再结晶，否则弹性下降。这个“窗口”就是热处理的难点：既要去应力，又不能软化。"},{"t":"h2","x":"六、验收：怎么证明热处理做了"},{"t":"list","ordered":true,"items":["**炉温曲线**：每炉带热电偶/记录仪，温度-时间曲线可追溯。","**硬度/刚度**：热处理前后抽检刚度，判断是否软化。","**尺寸**：波距、波厚、L₀、自由长度；热处理后复测。","**外观/金相**：无氧化、无晶粒粗大（必要时抽检）。","**泄漏/气密**：稳定化后按图纸做气密/氦检。","**记录**：材料批号、炉号、温度、时间、操作者。"]},{"t":"callout","kind":"warn","title":"客户说“按图做”，你要看图里有没有这些字","x":"“去应力”“稳定化”“固溶”“时效”“真空热处理”“保护气氛”“无氧化”——每一个词都对应不同工序和成本。图里没写，不等于不用做；问客户使用场景，比事后返工便宜。"},{"t":"h2","x":"七、自测"}],"sources":["书 §2.4.4 表面处理","书 §2.4.5 整形","书 §2.4.6 稳定处理","表 2-18"],"exam":{"pass":70,"minutes":15,"intro":"10 道题，覆盖本课的概念、数字与现场判断。答错会看到解释。","questions":[{"q":"书里不锈钢波纹管的热稳定参数是：","opts":["80±5℃/8h","180±5℃/6h","250–300℃/3–4h","1050℃/1h 水冷"],"a":2,"why":"表 2-18：不锈钢 250–300℃，保温 3–4 h；这是去应力，不是固溶。"},{"q":"机械稳定的书里参数是：","opts":["14–40 次/min，0–w_max，200 次","1–5 次/min，0–w，50 次","50–100 次/min，0–w，1000 次","任意"],"a":0,"why":"书里：频率 14–40 次/min，幅度 0–w_max，稳定次数 200 次。"},{"q":"整形的主要原因是：","opts":["材料太贵","弹性回弹导致波距/波型与设计有差异","客户要求好看","为了增加壁厚"],"a":1,"why":"书里明确：成形后弹性回弹使波距、波型与设计有差异，必须整形。"},{"q":"弥散硬化材料的热稳定处理本质上是：","opts":["固溶","时效","退火","正火"],"a":1,"why":"时效析出弥散相，既强化又稳定组织，同时消除加工应力。"},{"q":"不锈钢 250–300℃ 保温的作用是：","opts":["固溶碳化物","去应力/稳定尺寸","提高硬度到 HRC60","改变材料牌号"],"a":1,"why":"这个温度只能去应力，不能固溶；固溶需要 1000℃ 以上快冷。"},{"q":"下面哪项不是表面处理的目的？","opts":["除油","去氧化皮","钝化提高耐蚀","增加壁厚"],"a":3,"why":"表面处理不增加壁厚；酸洗过度还会减薄。"},{"q":"机械稳定与疲劳寿命试验的区别是：","opts":["完全一样","机械稳定是工艺手段（200次），寿命试验是验证手段（跑到要求次数）","机械稳定次数更多","寿命试验只做 200 次"],"a":1,"why":"前者稳定尺寸/应力，后者验证寿命；目的和次数不同。"},{"q":"热处理温度过高，最可能：","opts":["去应力更彻底且无害","软化/晶粒长大，刚度下降","提高耐压","减少成本"],"a":1,"why":"超过再结晶/固溶温度会软化、晶粒长大，弹性下降。"},{"q":"客户图纸写“固溶”，你按“去应力”做，主要风险是：","opts":["尺寸变大","耐蚀性/组织不达标","颜色变深","重量增加"],"a":1,"why":"固溶是为了溶解碳化物、恢复耐蚀/韧性；去应力达不到。"},{"q":"热稳定保温时间应该从什么时候算？","opts":["进炉开始","到温开始","出炉开始","装夹具开始"],"a":1,"why":"保温时间从炉温到温开始算；进炉到到温是升温时间，不算保温。"}]}},"16":{"title":"设计选型：从七项工况，推到一张能报价的图","sub":"客户给的是“通径 32、行程 8、压力 0.6 MPa、10 万次”，不是图纸。这一课按书里 §2.6 的选型顺序，把七项输入推成 d、D、h₀、t、a、n、L₀、端部，再判断要不要多层、导向、加强环。","tags":["第2章","设计","选型","几何参数","多层","导向"],"objectives":["记住选型的七项输入：空间/通径、载荷、位移、温度、介质、精度、寿命","会按 k、t、a、L₀、n 的顺序推几何参数，而不是先画图","知道 k=1.3–1.6 常规、1.6–1.8 高灵敏，以及它的工艺上限","会算 L₀≥w/(0.15–0.35)，并检查 L₀≤1.3D；超 1.8D 必须导向","知道多层/加强环/并联弹簧各自解决什么问题","能判断“该选标准件，还是必须新设计”"],"blocks":[{"t":"lead","x":"客户说：“通径 32，行程 8 mm，压力 0.6 MPa，要 10 万次，温度 150℃，介质是热油。”这不是一张图，是七项输入。你要在半小时内判断：能不能做、大概什么结构、报价区间。书里 §2.6 给的正是这个顺序：先定材料和结构，再定几何，最后校核性能。顺序反了，图越画越错。"},{"t":"figure","name":"designFlow","cap":"七项输入推九步，最后才是价格"},{"t":"callout","kind":"note","title":"这一课接在哪","x":"第 15 课讲热处理；这一课把前面所有参数收拢，从七项工况推到一张能报价的图。"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["k","小写 k","无量纲","先定 k=D/d"],["t","小写 t","mm","波距，按 d 取"],["a","小写 a","mm","波厚"],["L₀","L 下标 0","mm","有效长度"],["n","小写 n","个","波数"],["D₁/d₁","D 下标 1 / d 下标 1","mm","端部配合直径"]]},{"t":"h2","x":"一、七项输入：少一项，后面全在猜"},{"t":"table","head":["输入","客户常给的","你必须追问的"],"rows":[["空间/通径","“装得下就行”","最大外径、最大长度、接口形式"],["载荷","压力 0.6 MPa","内压/外压、恒定/交变、有无冲击"],["位移","行程 8 mm","压缩/拉伸、单程/循环、是否横向"],["温度","150℃","最高/最低、升温速率、是否交变"],["介质","热油","腐蚀性、是否含氯/硫、是否真空"],["精度","“差不多”","刚度允差、零位、迟滞、重复性"],["寿命","10 万次","压力/位移幅值、频率、允许泄漏率"]]},{"t":"p","x":"（书 §2.6.1）设计选型的依据就是系统给定的条件：最大空间尺寸或通径、工作载荷的性质和大小、工作位移量、工作温度范围、工作介质的性质、精度要求、使用寿命。这七项不是“参考”，是输入；缺一项，输出就不可靠。"},{"t":"h2","x":"二、先选材料，再定结构"},{"t":"p","x":"（书 §2.6.2）材料选择根据用途、载荷、精度、介质、温度、寿命，并考虑成形/焊接工艺性和市场来源。结构选择包括：波型、层数、是否与其它弹性元件联用、端部形式、是否导向、是否加强环。"},{"t":"kv","items":[["常规腐蚀/常温","304/304L、316L"],["含氯/海水","316L、双相钢、C-22（按介质选）"],["高温","321/316Ti、Inconel 625/718"],["高灵敏/仪表","3J1、3J21、3J53、QBe2"],["低成本/导热","H80、QSn6.5-0.1"],["真空/洁净","316L、电解抛光、低放气处理"]]},{"t":"p","x":"（书 §2.6.2）在总壁厚相等时，多层刚度约为单层的 1/Z^1.5（或 1/Z²）；多层变形应力小、寿命长，但成本高。工作压力较高时一般选多层；层数和单层壁厚要合理匹配。"},{"t":"callout","kind":"key","title":"先问“有没有标准件”","x":"书里明确：一般情况下，用户应从有关标准和制造单位的产品样本中选择波纹管，而不是设计新产品；这样问题最少、成本最低、周期最短。客户要新设计，往往是因为标准件装不下/寿命不够/介质特殊。先查样本，再谈开模。"},{"t":"h2","x":"三、九步推图：从 d 到端部"},{"t":"list","ordered":true,"items":["**定内径 d**：由系统通径定；d 是基准，其他尺寸按比例。","**定外径 D**：由最大空间定；用 k=D/d 关联，常规 1.3–1.6，高灵敏 1.6–1.8。","**定壁厚 h₀**：由刚度/耐压/位移反复算；公差一般 ±10%，h₀≤0.1 时 ±0.01 mm。","**定层数 Z**：高压/低刚度/长寿命时用多层；Z 由刚度公式反算。","**定波距 t、波厚 a**：d<40 时 t=(0.11–0.18)d；d=40–150 时 t=(0.08–0.11)d；a≈0.6t 或 0.5(t−h₀)。","**定有效长度 L₀**：L₀≥w/(0.15–0.35)，寿命要求高取小分母；同时 L₀≤1.3D。","**定波数 n**：按端部组合选公式；WW/WD/QdQd：n=1+(L₀−a)/t；NN/QDQD：n=(L₀+a)/t−1；WN/ND/QdQD：n=L₀/t。","**定端部 D₁/d₁/L₁/L₂**：D₁≈(0.8–0.9)D；d₁=(1.00–1.06)d+2h₀；L₁/L₂ 按焊接/法兰标准。","**定总长 L**：L=n·t+端部；再复查 L₀/D、刚度、耐压、寿命。"]},{"t":"p","x":"（书 §2.6.2）波距 t：d<40 mm 时 t=(0.11–0.18)d；d=40–150 mm 时 t=(0.08–0.11)d；后一数字更适合小尺寸。波厚 a 两种算法：a=0.6t，或 a=0.5(t−h₀)；最好满足 (a−h₀)/d=0.05–0.10。"},{"t":"p","x":"（书 §2.6.2）有效长度 L₀≥w/(0.15–0.35)；寿命长/性能高时分母取小值。同时 L₀≤1.3D；L₀/D>1.8 时，应在波纹管内/外设导向零件。"},{"t":"h2","x":"四、算例：通径 32、行程 8、0.6 MPa"},{"t":"p","x":"客户输入：d=32、w=8、p=0.6、10 万次、150℃、热油。先按常规 k=1.5 试："},{"t":"table","head":["参数","计算","结果","检查"],"rows":[["外径 D","D=k·d=1.5×32","48 mm","空间允许？"],["波距 t","t=(0.11–0.18)×32","3.5–5.8 mm","取 4.8，t/d=15%"],["波厚 a","a≈0.6t","2.88 mm","(a−h₀)/d=(2.88−0.12)/32=0.086，合格"],["有效长度 L₀","L₀≥8/(0.15–0.35)","23–53 mm","取 40；L₀/D=0.83，稳定"],["波数 n","WW：n=1+(40−2.88)/4.8","8.73→9","取整 9"],["内配合 D₁","D₁=(0.8–0.9)D","38.4–43.2 mm","按接口定"],["外配合 d₁","d₁=(1.00–1.06)×32+0.24","32.24–34.16 mm","按焊接/法兰定"]]},{"t":"p","x":"这个例子里，L₀/D=0.83<1.3，不需要导向；k=1.5 在常规区；t/d=15% 在范围内；(a−h₀)/d=0.086 在 0.05–0.10。剩下要校核：h₀=0.12 时刚度/耐压/寿命够不够；0.6 MPa 对 9 波、D48 的 U 型是否偏高；10 万次是否要降位移或多层。"},{"t":"callout","kind":"warn","title":"算例不是答案","x":"上面的 0.12 壁厚是假设，必须用刚度/耐压/寿命公式反算。若 p_n 不够，先加壁厚/加强环/多层；若刚度太大，先减壁厚/加波数/多层。几何参数是互相牵制的，不能一次定死。"},{"t":"h2","x":"五、多层、加强环、并联弹簧：三个“加法”"},{"t":"table","head":["手段","解决什么","代价","什么时候用"],"rows":[["多层","降刚度、降变形应力、提耐压/寿命","层间封焊/检漏/清洁，成本高","高压+大位移+长寿命"],["加强环","局部提高承压，抑制波峰/波谷变形","局部应力集中、工艺复杂","高压但不想多层"],["并联弹簧","提高测量精度/承受高压/抗冲击","结构复杂、体积大","仪表、高压差、冲击载荷"],["导向装置","防柱失稳","摩擦/磨损、结构长度","L₀/D>1.3，尤其>1.8"]]},{"t":"p","x":"（书 §2.6.2）波纹管与螺旋弹簧并联使用的情况：提高测量精度、工作压力较高、有冲击载荷。加强环是局部加强，多层是整体加强，两者可以组合。导向装置用于长波纹管，阀用波纹管一般都设导向。"},{"t":"h2","x":"六、选型检查表：报价前过一遍"},{"t":"list","ordered":true,"items":["k=D/d 是否在 1.3–1.8？超过 1.8 是否评估焊接/电沉积？","h₀/d 是否在 0.0006–0.05？公差是否 ±10% 或 ±0.01 mm？","t/d 是否在 8%–18%？(a−h₀)/d 是否 0.05–0.10？","L₀/w 是否≥1/(0.35–0.15)？L₀/D 是否≤1.3？>1.8 是否加导向？","n 是否按端部组合公式取整？端部 D₁/d₁ 是否匹配客户接口？","p_g≤0.5p_n？w_g≤0.5w？不满足是否降工况/改结构？","10 万次是否需要多层/降位移/加波数？","介质/温度是否匹配材料？氯离子/高温/真空是否特殊处理？","是否优先选标准件？新设计是否真的必要？","报价是否含模具/工装/热处理/检测/包装？"]},{"t":"callout","kind":"warn","title":"五个常见选型错误","x":"① 先画图后算性能；② k 超出工艺上限还按液压报；③ L₀/D 超 1.3 不加导向；④ 只算刚度不算耐压/寿命；⑤ 客户给“通径”就当内径，忽略接口/壁厚。每一个都能让图报废。"},{"t":"h2","x":"七、自测"}],"sources":["书 §2.6.1 选型依据","书 §2.6.2 选型内容与原则","式 2-64～2-71 相关参数"],"exam":{"pass":70,"minutes":15,"intro":"10 道题，覆盖本课的概念、数字与现场判断。答错会看到解释。","questions":[{"q":"书里说选型的第一依据是：","opts":["材料价格","系统给定的条件（空间、载荷、位移、温度、介质、精度、寿命）","工厂习惯","竞争对手的图纸"],"a":1,"why":"§2.6.1 明确七项给定条件；不是先选材料。"},{"q":"常规波深系数 k=D/d 的范围是：","opts":["1.0–1.2","1.3–1.6","1.8–2.2","2.5–3.0"],"a":1,"why":"书里：一般 k=1.3–1.6；高灵敏 1.6–1.8。"},{"q":"d=32 时，波距 t 的推荐范围是：","opts":["1.6–3.2 mm","3.5–5.8 mm","6–8 mm","10–12 mm"],"a":1,"why":"d<40：t=(0.11–0.18)d=3.52–5.76 mm。"},{"q":"有效长度 L₀ 与位移 w 的关系，书里给的是：","opts":["L₀≥w/(0.15–0.35)","L₀≤w","L₀=w","L₀≥10w"],"a":0,"why":"寿命/性能要求高时分母取小值；同时 L₀≤1.3D。"},{"q":"L₀/D>1.8 时，应该：","opts":["不用管","在波纹管内/外设导向零件","把壁厚减半","改材料"],"a":1,"why":"书里：长径比大时容易柱失稳，>1.8 应考虑导向。"},{"q":"多层波纹管在总壁厚相同时，刚度约为单层的：","opts":["1/Z","1/Z^1.5","Z 倍","不变"],"a":1,"why":"书里：约 1/Z^1.5（或 1/Z²），所以多层更软、应力更小。"},{"q":"WW 型端部的波数公式是：","opts":["n=1+(L₀−a)/t","n=(L₀+a)/t−1","n=L₀/t","n=L₀·t"],"a":0,"why":"WW/WD/QdQd 用 n=1+(L₀−a)/t；NN/QDQD 用 n=(L₀+a)/t−1；WN/ND/QdQD 用 n=L₀/t。"},{"q":"客户给“通径 32”，你首先应该：","opts":["直接当内径 d=32","确认通径是内径还是接口通径，再定 d","直接报 32 元","选最大壁厚"],"a":1,"why":"通径≠内径；要确认接口/配合，再以 d 为基准推其他尺寸。"},{"q":"下面哪项不是“加法”手段？","opts":["多层","加强环","并联弹簧","降低材料牌号"],"a":3,"why":"多层/加强环/并联弹簧是结构手段；降牌号是降性能，不是加法。"},{"q":"书里建议优先：","opts":["新设计","从标准/样本选","先开模","先做 1000 件库存"],"a":1,"why":"标准/样本选型问题最少、成本最低、周期最短；新设计是不得已。"}]}},"17":{"title":"六个应用场景：同一根波纹管，为什么要求完全不同","sub":"仪表要灵敏度，真空开关要寿命，阀门要密封，膨胀节要补偿，软管要挠性，换热器要换热。这一课按书里 §2.5 的六种应用，讲清“同一个产品，换一个场景就要换一套判据”。","tags":["第2章","应用","仪表","真空开关","阀门","膨胀节","软管","换热器"],"objectives":["说出六种应用的第一个性能指标，而不是笼统说“密封”","知道仪表用力平衡式波纹管为什么应力小、精度高","知道真空开关的寿命=灭弧室机械寿命，行程=触头开距","知道阀门波纹管行程约为通径的 1/4，且必须机械限位","知道膨胀节/软管/换热器各自的核心失效模式","拿到客户场景，能问出决定选型的三个问题"],"blocks":[{"t":"lead","x":"同一张 D=40、d=32、h₀=0.12 的图，用在仪表上要“软、准”，用在真空开关上要“10 万次不漏”，用在阀门上要“耐压、抗扭”，用在膨胀节上要“大位移、抗失稳”。材料可能一样，判据完全不一样。这一课把书里 §2.5 的六个场景拆开，让你在报价前先问“它到底在干什么”。"},{"t":"figure","name":"applications","cap":"应用决定先保哪个指标"},{"t":"callout","kind":"note","title":"这一课接在哪","x":"第 16 课讲怎么设计；这一课讲同样一根波纹管，装在仪表、真空开关、阀门、膨胀节、软管、换热器里，要求为什么完全不同。"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["行程","—","mm","阀门/开关的移动距离"],["通径","—","mm","管道内径，决定流量"],["漏率","—","mbar·L/s","密封性指标，越小越难做"],["寿命","—","次","到泄漏或失效为止的循环次数"]]},{"t":"h2","x":"一、仪表：把压力变成位移，或变成力"},{"t":"p","x":"（书 §2.5.1）仪表用波纹管是弹性敏感元件，基本功能是把压力变为位移输出，或把压力变为集中力输出。对弹性特性要求很高：线性、迟滞、后效、零位都要小。"},{"t":"p","x":"书里有一个关键区分：把压力变为集中力输出的波纹管，变形很小或几乎没有位移，波纹上的应力比输出位移的小；弹性后效、滞后的影响可以说没有。所以力平衡式波纹管做敏感元件的仪表，可靠性和精度可以很高。这就是测量仪表多用力平衡式的原因。"},{"t":"kv","items":[["第一指标","弹性特性（线性/迟滞/重复性）"],["设计取向","刚度尽量小；力平衡式可做到高精度"],["常见失效","零位漂移、迟滞变大、疲劳"],["报价关注","材料弹性、热处理、老化/稳定化"],["不要只说","“密封不漏”——仪表还要准"]]},{"t":"callout","kind":"key","title":"力平衡 vs 位移输出","x":"位移输出：压力推着波纹管走，位移被读出；波纹弯曲应力大，迟滞/后效影响大。力平衡：波纹管几乎不动，压力变成集中力去平衡杠杆/弹簧；应力小、精度高。客户说“高精度”，先问是哪种。"},{"t":"h2","x":"二、真空开关：寿命就是灭弧室的机械寿命"},{"t":"p","x":"（书 §2.5.2）真空开关在真空中通断电流，主触头在真空灭弧室内；波纹管是关键元件：只有它能让外部机械力驱动动触头，同时保持外壳完全密封。每一次通/断，波纹管都做一次大幅度位移；频繁的大位移容易疲劳。"},{"t":"p","x":"书里讲得很直接：波纹管是灭弧室外壳的一部分，它损坏，灭弧室就因漏气而寿命终止；其它零件正常运行不容易坏，所以波纹管的疲劳寿命决定灭弧室的机械寿命。触头开距与波纹管实际轴向位移相等，所以波纹管的轴向允许位移决定最大触头开距。"},{"t":"kv","items":[["第一指标","轴向位移 + 真空密封 + 疲劳寿命"],["寿命逻辑","波纹管寿命 = 灭弧室机械寿命"],["行程逻辑","触头开距 = 波纹管轴向位移"],["失效","疲劳漏气；行程越大寿命越短"],["工艺选择","普通真空开关多用液压成形；超长寿命+大行程才用焊接"],["材料","1Cr18Ni9Ti、00Cr17Ni14Mo2、0Cr18Ni9"]]},{"t":"callout","kind":"warn","title":"不要用“加大行程”换开距","x":"客户想提高开距，最直接的办法是加大波纹管行程；但书里明确：行程越大，疲劳寿命越短。正确做法是改结构/改波数/改材料，或者接受寿命下降并验证。销售不能为了接单随便承诺。"},{"t":"h2","x":"三、阀门：无填料密封，行程约 1/4 通径"},{"t":"p","x":"（书 §2.5.3）波纹管阀门（截止、节流、调节、减压等）用波纹管作阀杆的无填料密封隔离元件。工作时波纹管随阀杆轴向位移并复位，同时承受流体压力并绝对密封。"},{"t":"p","x":"书里给了两个硬约束：平面密封截止阀，波纹管工作行程一般为通径的 1/4；行程应通过阀杆移动的机械限位来限程，不允许波纹压靠产生塑性变形，还要防止扭曲变形。主要性能是耐压力、工作位移、疲劳寿命；失效形式是疲劳破裂、应力腐蚀、失稳。"},{"t":"kv","items":[["第一指标","耐压 + 密封 + 疲劳寿命"],["行程","约 1/4 通径（平面密封截止阀）"],["必须","机械限位，禁止压靠/扭曲"],["失效","疲劳破裂、应力腐蚀、失稳"],["影响寿命","压力、位移、温度、介质、波形、材料、冲击、振动、装配"],["对比","比填料密封更可靠、寿命更长；核/石化/医药/航空航天常用"]]},{"t":"callout","kind":"key","title":"阀门报价先问“行程怎么限”","x":"如果客户的结构没有机械限位，波纹管可能被压到塑性；这不是波纹管的问题，是阀门设计的问题。销售要提醒客户：限位、导向、防扭，缺一个都会导致早期失效。"},{"t":"h2","x":"四、膨胀节：补偿温度/压力引起的位移"},{"t":"p","x":"（书 §2.5.4）金属波纹膨胀节用于管路系统，补偿温度/压力波动造成的轴向、横向、角位移。核心零件是波纹管；其它零件是结构件，起导向、支撑、连接、导流作用。按需要焊成轴向、横向、角向等不同类型。"},{"t":"kv","items":[["第一指标","补偿量（轴向/横向/角向）+ 耐压"],["核心","波纹管；其它件是导向/支撑/连接/导流"],["常见失效","疲劳、失稳、腐蚀"],["设计重点","L₀/D、导向、固定/活动端、预变形"],["报价关注","口径、波数、层数、法兰/接管、导流筒、防腐"]]},{"t":"p","x":"膨胀节的“位移”不是单波位移，是整个系统的补偿量；波数、层数、长度、导向一起决定。客户只给“补偿 50 mm”，你要问：轴向还是横向？温度多少？固定点在哪？有没有预拉伸？"},{"t":"h2","x":"五、金属软管：挠性连接，L/D>3"},{"t":"p","x":"（书 §2.5.5）金属软管用挠性补偿安装偏差、满足工作端各向位移，并承受流体压力。核心零件是波纹管；这种波纹管的长度/内径一般大于 3；波型分环形和螺旋形，环形弯曲刚度比螺旋形小；为提高承压，常在波纹管外铠装金属丝或编织网套。"},{"t":"kv","items":[["第一指标","挠性（弯曲/横向位移）+ 耐压"],["几何特征","L/d>3；环形/螺旋形"],["环形 vs 螺旋","环形弯曲刚度更小，更柔"],["承压","外加金属丝/编织网套"],["常见失效","疲劳、网套磨损、腐蚀"],["报价关注","长度、弯曲半径、网套、接头、介质"]]},{"t":"callout","kind":"warn","title":"软管不是“越长越软”","x":"长度增加能降低弯曲应力，但太长会失稳、振动、流阻/积液。选型要看最小弯曲半径、工作压力、介质、接头，不是只报长度。"},{"t":"h2","x":"六、换热器：波纹管是换热元件，不是密封件"},{"t":"p","x":"（书 §2.5.6）波纹管式换热器是高效强化换热器，波纹管作为换热管束，主要起强化换热作用，同时起热补偿和抗振动作用。失效形式主要是疲劳破裂、应力腐蚀破裂、腐蚀破裂；主要性能是换热效率、疲劳寿命、耐压、耐温、耐蚀、抗振、热补偿。"},{"t":"kv","items":[["第一指标","换热效率（波形相关）"],["同时要求","耐压/耐温/耐蚀/抗振/热补偿"],["失效","疲劳、应力腐蚀、腐蚀"],["设计重点","波形、流速、污垢、振动"],["报价关注","材质、壁厚、管束数量、焊接、试压"]]},{"t":"p","x":"换热器的波纹管和密封波纹管不是一回事：它不要求“零泄漏的位移密封”，而要求“高效换热+长期不裂”。拿阀门波纹管的判据去套换热器，会抓错重点。"},{"t":"h2","x":"七、同一根管，六套判据：一张对照表"},{"t":"table","head":["场景","第一指标","关键几何","典型失效","最容易问错的问题"],"rows":[["仪表","弹性特性/精度","刚度小、力平衡","零位漂、迟滞","“漏不漏？”"],["真空开关","寿命+真空密封","行程=触头开距","疲劳漏气","“能开多大？”"],["阀门","耐压+密封+寿命","行程≈1/4 通径","疲劳/应力腐蚀/失稳","“压力够不够？”"],["膨胀节","补偿量+耐压","波数/层数/导向","疲劳/失稳","“多长？”"],["金属软管","挠性+耐压","L/d>3、网套","疲劳/磨损","“多长？”"],["换热器","换热效率","波形/管束","疲劳/腐蚀","“漏不漏？”"]]},{"t":"callout","kind":"key","title":"场景决定“第一指标”","x":"同一根波纹管，仪表看“准”，真空开关看“寿命”，阀门看“密封+耐压”，膨胀节看“补偿”，软管看“柔”，换热器看“换热”。第一指标错了，后面全错。"},{"t":"h2","x":"八、销售怎么问：三个问题锁定场景"},{"t":"list","ordered":true,"items":["**它在系统里干什么？** 测压力/开关/密封/补偿/连接/换热——先定场景。","**坏了会怎样？** 漏气、关不死、测不准、管子裂——定失效模式和第一指标。","**行程/压力/温度/介质/寿命哪个是硬的？** 定约束，排优先级。"]},{"t":"p","x":"客户常常一上来就给尺寸，不说场景。你先问这三句，比后面返工便宜。尤其是“坏了会怎样”：真空开关漏气=灭弧室报废；阀门漏=介质外泄；仪表漂=整机精度失效。后果不同，设计余量不同。"},{"t":"h2","x":"九、自测"}],"sources":["书 §2.5.1 仪表","书 §2.5.2 真空开关","书 §2.5.3 阀门","书 §2.5.4 膨胀节","书 §2.5.5 金属软管","书 §2.5.6 换热器"],"exam":{"pass":70,"minutes":15,"intro":"11 道题，覆盖本课的概念、数字与现场判断。答错会看到解释。","questions":[{"q":"仪表用波纹管的第一指标是：","opts":["耐压最高","弹性特性/精度","长度最长","颜色"],"a":1,"why":"仪表是弹性敏感元件，线性/迟滞/重复性/零位是核心。"},{"q":"力平衡式波纹管为什么精度高？","opts":["材料更贵","位移几乎为零，弯曲应力小，后效/滞后影响小","壁厚更厚","不需要密封"],"a":1,"why":"书里：力平衡式变形很小，应力小，弹性后效/滞后几乎没有。"},{"q":"真空开关的波纹管寿命决定了：","opts":["外壳颜色","灭弧室的机械寿命","触头材料","绝缘气体压力"],"a":1,"why":"书里：波纹管损坏则灭弧室漏气报废，其它零件不易坏，所以波纹管寿命=机械寿命。"},{"q":"平面密封截止阀的波纹管工作行程一般约为：","opts":["通径的 1/10","通径的 1/4","通径的 1 倍","通径的 4 倍"],"a":1,"why":"书里：平面密封截止阀，工作行程一般为通径的 1/4。"},{"q":"阀门波纹管为什么必须机械限位？","opts":["为了好看","防止波纹压靠产生塑性变形/扭曲","为了增加流量","为了降成本"],"a":1,"why":"书里：行程通过阀杆机械限位，禁止压靠塑性变形和扭曲。"},{"q":"膨胀节的核心零件是：","opts":["法兰","波纹管","导流筒","螺栓"],"a":1,"why":"波纹管提供可变形性和耐压密封；其它是结构件。"},{"q":"金属软管的长度/内径一般：","opts":["<1",">3","=1","无关"],"a":1,"why":"书里：软管波纹管长度和内径之比一般大于 3。"},{"q":"环形与螺旋形软管，弯曲刚度更小的是：","opts":["环形","螺旋形","一样","取决于颜色"],"a":0,"why":"书里：环形弯曲刚度比螺旋形小，更柔。"},{"q":"换热器波纹管的第一指标是：","opts":["零泄漏位移密封","换热效率","外观","颜色"],"a":1,"why":"换热器核心是强化换热，同时要耐压/耐温/耐蚀/抗振/热补偿。"},{"q":"客户只给尺寸不说场景，你最该先问：","opts":["包装","它在系统里干什么、坏了会怎样","运输","付款方式"],"a":1,"why":"场景和失效后果决定第一指标与设计余量。"},{"q":"真空开关想增大触头开距，最直接的代价是：","opts":["寿命下降","颜色变化","重量减轻","成本降低"],"a":0,"why":"触头开距=波纹管轴向位移；行程越大，疲劳寿命越短。"}]}},"18":{"title":"第2章复盘：拿到一张图，怎么在 20 分钟内判断能不能做","sub":"这一课不引入新公式，只做一件事：把第 2 章的几何、性能、刚度、强度、寿命、工艺、选型串成一条判断链。用一个完整案例，走一遍“读图→算比值→查风险→给结论”的流程。","tags":["第2章","复盘","案例","读图","校核","报价"],"objectives":["把第 2 章的 8 个几何参数、5 个性能参数、3 个比值串成一张检查表","会用 k、h₀/d、t/d、L₀/D 四个比值做第一轮筛选","会判断图上的 n、L₀、t 是否自洽（几何闭合）","能按“强度→耐压→稳定→位移→寿命→工艺”的顺序给结论","能写出“能做/不能做/需要客户确认”的三段式回复","知道哪些结论必须留余量，不能拍胸脯"],"blocks":[{"t":"lead","x":"客户发来一张图：D=40、d=32、h₀=0.12、t=4.8、n=12、L₀=60、w=8、p=0.6 MPa、10 万次、150℃、316L。你只有 20 分钟，要判断“能不能做、大概什么价、哪里要改”。这一课不教新公式，教你把第 2 章串起来用。"},{"t":"figure","name":"decision20","cap":"五道门，任何一道不过就停"},{"t":"callout","kind":"note","title":"这一课接在哪","x":"第 17 课看应用；这一课复盘第 2 章：拿到一张图，20 分钟内判断能不能做、该报什么价。"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["k","小写 k","无量纲","k=D/d"],["h₀/d","h 下标 0 除以 d","无量纲","壁厚比"],["t/d","t 除以 d","无量纲","波距比"],["L₀/D","L 下标 0 除以 D","无量纲","长径比"],["p_n","p 下标 n","MPa","耐压力"],["n","小写 n","个","波数"]]},{"t":"h2","x":"一、先读图：八个字母，四个比值"},{"t":"table","head":["参数","图上值","先算什么","结果"],"rows":[["d 内径","32","—","基准"],["D 外径","40","k=D/d","1.25（浅波）"],["h₀ 壁厚","0.12","h₀/d","0.00375（范围内）"],["t 波距","4.8","t/d","15%（范围内）"],["a 波厚","未给","a≈0.6t","2.88（假设）"],["n 波数","12","几何闭合","与 L₀ 矛盾（见下）"],["L₀ 有效长度","60","L₀/D","1.5（>1.3，需导向）"],["w 位移","8","w/L₀","13.3%（在 10–40% 内）"]]},{"t":"p","x":"第一轮四个比值：k=1.25 浅波，液压成形容易、承压好、位移小；h₀/d=0.00375 在 0.0006–0.05 内；t/d=15% 在 8%–18% 内；L₀/D=1.5 超过 1.3，但没到 1.8，属于“要导向/要校核”的区间。四个比值里，三个合格，一个要处理。"},{"t":"callout","kind":"warn","title":"先查几何闭合，不要急着算性能","x":"图给 n=12、t=4.8、a≈2.88、L₀=60。按 WW 型公式 n=1+(L₀−a)/t=1+(60−2.88)/4.8=12.9，应取 13 波，不是 12。反算 L₀=a+(n−1)t=2.88+11×4.8=55.68 mm。图上的 12 波和 60 mm 对不上。这是第一个必须让客户确认的点。"},{"t":"h2","x":"二、几何闭合：n、L₀、t、a 是一组，不是四个独立数"},{"t":"p","x":"（书 §2.6.2）波数 n 按端部组合公式计算：WW/WD/QdQd 用 n=1+(L₀−a)/t；NN/QDQD 用 n=(L₀+a)/t−1；WN/ND/QdQD 用 n=L₀/t。图上没写端部代号，n 就无法唯一确认。"},{"t":"list","ordered":true,"items":["先问端部代号：N/W/D/QD/Qd，两端各是什么。","用对应公式反算 n，取整后再反算 L₀。","检查 L₀ 与客户给的 60 是否一致；不一致以哪个为准？","检查 t/d、a/t 是否在推荐范围；a 未给时先按 0.6t 假设，再让客户确认。","几何不闭合，后面的刚度/寿命都是空中楼阁。"]},{"t":"callout","kind":"key","title":"销售最容易漏的一步","x":"很多人拿到图直接算刚度，算完才发现 n 和 L₀ 对不上。正确顺序是：先闭合几何，再算性能。几何不闭合，报价一定返工。"},{"t":"h2","x":"三、耐压/强度：0.6 MPa 在不在窗口"},{"t":"p","x":"用书里式 2-50 估算（L≤1.5D；这里 L₀/D=1.5，正好边界）：p_n=K₁K₂K₃σ_s h₀/D。取 316L 近似 σ_s≈205 MPa（按材料标准，具体以质保书为准），K₁ 按不锈钢取 10.4，K₂=d/D=0.8，K₃=(a−h₀)/d=(2.88−0.12)/32=0.0863。"},{"t":"p","x":"p_n≈10.4×0.8×0.0863×205×0.12/40≈0.44 MPa。工作压力 0.6 MPa 已经超过 p_n，更超过 0.5p_n 的红线。结论：按这组几何/材料，0.6 MPa 不够，必须加壁厚、加加强环、多层，或降压力。注意：这是用 316L 屈服 205 MPa 的保守估算；若用 1Cr18Ni9Ti（588 MPa）结果会高很多。材料牌号必须确认。"},{"t":"callout","kind":"warn","title":"材料牌号差三倍，别用错","x":"316L 屈服约 205 MPa，1Cr18Ni9Ti 约 588 MPa（书里值）。同样几何，p_n 差近三倍。客户图写 316L，你不能拿书里的 1Cr18Ni9Ti 参数直接算。牌号、状态、质保书，一个都不能少。"},{"t":"h2","x":"四、稳定：L₀/D=1.5，必须导向"},{"t":"p","x":"（书 §2.3.4）L₀≤1.3D 是稳定红线；1.3–1.8 要校核；>1.8 必须设导向。这里 L₀/D=1.5，且客户给 10 万次、有压力，柱失稳风险不能忽略。建议：波纹管内/外设导向，或缩短 L₀、增加支撑。"},{"t":"p","x":"临界力 F_k=π²B/(k₄L₀)²。B 是弯曲刚度，L₀ 从 60 降到 40，临界力提高 (60/40)²=2.25 倍。所以“缩短有效长度”比“加厚壁厚”对稳定更有效；但缩短 L₀ 会减少波数/位移，要一起权衡。"},{"t":"h2","x":"五、位移/寿命：8 mm 是不是太大"},{"t":"p","x":"（书 §2.3.4）w=8、L₀=60，w/L₀=13.3%，在 10%–40% 的轴向允许范围内，看起来不大。但寿命还要看 w/w_y 和 p/p_n：如果 p_n 只有 0.44，p/p_n>1，已经不合格，寿命无从谈起；如果加壁厚把 p_n 提到 1.2，p/p_n=50%，正好红线，10 万次仍要降位移或多层。"},{"t":"kv","items":[["位移比","w/L₀=13.3%，在 10–40% 内"],["压力比","0.6/0.44>1（当前几何），不合格"],["目标","p_g≤0.5p_n 且 w_g≤0.5w，才有 5 万次左右的基础"],["10 万次","要更保守：降 w、降 p、加波数/多层，或做寿命试验"],["不能承诺","只凭查图/经验就给 10 万次保证"]]},{"t":"callout","kind":"key","title":"寿命是“条件”，不是“属性”","x":"同样这根管，w=4、p=0.3 可能 50 万次；w=8、p=0.6 可能 1 万次。客户要 10 万次，你要把 w、p、温度、介质、频率一起写进技术协议，不能只写“10 万次”。"},{"t":"h2","x":"六、工艺：k=1.25 好做，但 L₀ 长/导向是难点"},{"t":"p","x":"k=1.25 属于浅波，液压成形容易，模具/吨位不高；h₀=0.12、d=32 也在液压成形范围内。难点在 L₀/D=1.5：液压成形后要加导向/支撑，或者把 L₀ 缩短；另外 10 万次/150℃ 要考虑材料疲劳、热处理、稳定化。"},{"t":"list","ordered":true,"items":["液压成形：可行；k 浅，波高容易；注意回弹/整形。","焊接：若客户允许纵缝且批量大，焊接管坯+液压也可评估；但 316L 薄壁焊缝要控制。","热处理：316L 去应力（250–300℃）或固溶（按耐蚀要求）；150℃ 工作要考虑长期时效。","稳定化：10 万次建议机械稳定 200 次 + 热稳定；是否做按客户规范。","检测：气密/氦检、刚度、尺寸；真空/高纯还要清洁度/放气。"]},{"t":"h2","x":"七、结论怎么写：三段式，不拍胸脯"},{"t":"table","head":["段落","写什么","示例"],"rows":[["事实","图面参数、材料、工况","D40/d32/h₀0.12/t4.8/n12/L₀60；316L；0.6 MPa；8 mm；10 万次；150℃"],["判断","四个比值、耐压/稳定/寿命结论","k=1.25 可液压；L₀/D=1.5 需导向；按 316L 估算 p_n≈0.44，0.6 MPa 不够；n 与 L₀ 不闭合"],["边界/请示","需要客户确认/我们建议","请确认端部代号与 n/L₀；建议加壁厚/加强环/多层或降压力；10 万次需寿命试验，不能直接承诺"]]},{"t":"p","x":"这三段式的好处：事实可核对、判断有依据、边界清楚。客户不会因为你说“不够”而生气，反而会觉得你专业；最怕的是“能做”，最后做不出来。"},{"t":"h2","x":"八、20 分钟检查表（打印版）"},{"t":"list","ordered":true,"items":["① 端部代号？N/W/D/QD/Qd，两端各是什么？","② 几何闭合？n、L₀、t、a 用公式对一遍。","③ k=D/d？1.3–1.6 常规，1.6–1.8 高灵敏，≥2 焊接。","④ h₀/d？0.0006–0.05；公差 ±10%/±0.01。","⑤ t/d？8%–18%；(a−h₀)/d？0.05–0.10。","⑥ L₀/D？≤1.3；1.3–1.8 校核；>1.8 导向。","⑦ 材料/温度/介质？牌号、状态、耐蚀、放气。","⑧ p_n/p_g？p_g≤0.5p_n；w_g≤0.5w。","⑨ 寿命？次数、幅值、频率、试验要求。","⑩ 工艺/检测/包装？模具、热处理、检漏、清洁度。"]},{"t":"h2","x":"九、自测"}],"sources":["第2章 §2.1–§2.6 综合","式 2-50、2-52、2-54","表 2-1、2-3、2-6"],"exam":{"pass":70,"minutes":15,"intro":"11 道题，覆盖本课的概念、数字与现场判断。答错会看到解释。","questions":[{"q":"D=40、d=32，k 是多少？属于哪类？","opts":["1.25，浅波","1.6，深波","2.0，很深","0.8，负波深"],"a":0,"why":"k=D/d=40/32=1.25，1.3–1.5 为浅波（1.25 更浅）。"},{"q":"L₀=60、D=40，L₀/D 是多少？该怎么处理？","opts":["1.5，>1.3，需导向/校核","1.5，不用管","0.67，安全","6，必须分段"],"a":0,"why":"L₀/D=1.5；1.3–1.8 要校核，建议导向。"},{"q":"图上 n=12、t=4.8、a=2.88、L₀=60，按 WW 公式 n 应约：","opts":["12","13","10","15"],"a":1,"why":"n=1+(60−2.88)/4.8≈12.9，取 13；图上 12 与 L₀ 不闭合。"},{"q":"按 316L（σ_s≈205）估算 p_n≈0.44，工作 0.6 MPa，结论是：","opts":["合格","超过耐压，必须改结构/降压力","刚好 50%","无法判断"],"a":1,"why":"0.6>0.44，已超过耐压；更超过 0.5p_n 红线。"},{"q":"同样几何，把材料从 316L 换成 1Cr18Ni9Ti（σ_s≈588），p_n 大约：","opts":["不变","降到 1/3","升到约 2.9 倍","升到 10 倍"],"a":2,"why":"p_n∝σ_s，588/205≈2.87；但不能拿旧牌号直接替代，要按标准/质保书。"},{"q":"L₀ 从 60 降到 40，柱失稳临界力大约：","opts":["不变","提高 2.25 倍","降低 2.25 倍","提高 10 倍"],"a":1,"why":"F_k∝1/L₀²，(60/40)²=2.25。"},{"q":"20 分钟检查表的第一步应该是：","opts":["算价格","确认端部代号与几何闭合","选颜色","写合同"],"a":1,"why":"几何不闭合，后面都白算；端部代号决定 n 公式。"},{"q":"客户要 10 万次，最稳妥的回复是：","opts":["“没问题”","“按当前 p/w 只能估算，需降工况/改结构并做寿命试验”","“加钱就能 10 万次”","“别人能做我们也能”"],"a":1,"why":"寿命是条件函数；要说明工况、结构、验证，不能拍胸脯。"},{"q":"三段式回复的顺序是：","opts":["判断→事实→边界","事实→判断→边界/请示","边界→判断→事实","价格→交期→付款"],"a":1,"why":"先事实（可核对），再判断（有依据），最后边界/请示（不越权）。"},{"q":"下面哪个不是第2章的核心比值？","opts":["k=D/d","h₀/d","L₀/D","价格/重量"],"a":3,"why":"前三个是几何判据；价格/重量不是设计判据。"},{"q":"图上 a 没给，先按什么假设？","opts":["a=t","a≈0.6t","a=0","a=10t"],"a":1,"why":"书里给 a≈0.6t 或 0.5(t−h₀)；先假设再让客户确认。"}]}},"19":{"title":"标准与验收：图纸上那行小字，决定谁承担返工","sub":"同样写“按 GB/T 12777”，2019 版和 1991 版差很多；同样写“氦检”，漏率 1E-9 和 1E-6 差三个数量级。这一课按书里 §1.7 的标准框架，讲清标准怎么选、怎么查现行版、验收怎么落到合同。","tags":["第2章","标准","验收","GB/T 12777","GB/T 14525","ISO 10380","合同"],"objectives":["分清国家标准、行业标准、企业标准、国际标准、客户规范的关系","知道波纹管最常用的三本现行标准：GB/T 12777-2019、GB/T 14525-2010、ISO 10380:2012","会用“标准号+年份+条款”读图，不用旧版报价","知道验收要写清：方法、判定、抽样、报告、复检","知道标准冲突时的优先级：合同/客户规范 > 国标 > 行标","能识别图纸上五个最常见的标准陷阱"],"blocks":[{"t":"lead","x":"客户图纸技术要求最后一行写：“未注公差按 GB/T 1804-m；波纹管按 GB/T 12777；软管按 GB/T 14525；氦检漏率≤1×10⁻⁹ Pa·m³/s。”这几行字，决定了材料、试验、判定、谁承担返工。你看不懂，报价就是盲报；你写错版本，验收就是扯皮。"},{"t":"figure","name":"standards","cap":"标准有优先级，验收有十道门"},{"t":"callout","kind":"note","title":"这一课接在哪","x":"第 18 课做完整判断；这一课讲标准与验收：图纸上那行小字，决定谁承担返工。"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["RT","R 加 T","—","射线检测，看内部气孔/未焊透"],["UT","U 加 T","—","超声检测，看内部缺陷"],["PT","P 加 T","—","渗透检测，看表面裂纹"],["MT","M 加 T","—","磁粉检测，只用于铁磁材料"],["1E-9","10 的负 9 次方","mbar·L/s","漏率量级，比 1E-6 严 1000 倍"]]},{"t":"h2","x":"一、标准不是“一张纸”，是五层约束"},{"t":"table","head":["层级","例子","作用","冲突时"],"rows":[["合同/技术协议","客户采购规范、数据表","最高优先级，写清特殊要求","优先"],["客户/企业标准","客户企标、MW 企标","客户内部统一","高于国标（合同引用时）"],["国家标准","GB/T 12777、GB/T 14525","通用底线","被合同引用才强制"],["行业标准","JB/T、EJMA、ASME","专业领域补充","按合同引用"],["国际标准","ISO 10380、ISO 14644","外贸/高端客户常用","按合同引用"]]},{"t":"p","x":"（书 §1.7）书里列的是 1990 年代的标准体系：GB/T 12777-91、GB/T 14525-93、JB/T 6169-92 等。这些标准有的已换版，有的已被替代。**不能拿书里的年份直接报价**；要查现行版，或在合同里写“以现行有效版本为准”。"},{"t":"h2","x":"二、三本最常用的现行标准"},{"t":"table","head":["标准","管什么","典型用途","注意"],"rows":[["GB/T 12777-2019","金属波纹管膨胀节通用技术条件","膨胀节设计、材料、制造、检验","替代旧版；具体条款以标准正文为准"],["GB/T 14525-2010","波纹金属软管通用技术条件","金属软管/软管总成","长度、弯曲、耐压、泄漏"],["ISO 10380:2012","Corrugated metal hoses and hose assemblies","出口/外资客户软管","与 GB/T 14525 思路接近，细节不同"],["EJMA 标准（现行版）","膨胀节设计与计算","高端/出口膨胀节","不是国标，合同引用才用"],["ASME B31.3 / VIII","管道/压力容器","石化/高压系统","按合同/法规引用"],["ISO 14644","洁净室等级","半导体/医疗洁净","洁净度不是漏率"],["ASTM E595","材料放气","真空/航天","TML/CVCM 指标"],["ASTM G28 A","镍合金晶间腐蚀","C-22/625 等","不是所有不锈钢都适用"]]},{"t":"callout","kind":"warn","title":"标准号后面的年份很重要","x":"GB/T 12777-2019 与 1991 版在材料、计算、检验上都有变化。图纸只写“GB/T 12777”没写年份，合同应约定“现行有效版”；若客户指定旧版，要评估旧版的公差/试验是否还满足使用。"},{"t":"p","x":"怎么查现行版？不要凭记忆。国内标准去“全国标准信息公共服务平台”（std.samr.gov.cn）查标准号/年份/状态（现行/废止/被替代）；国际标准去 iso.org 或客户提供的标准文本。查不到，就在合同里写“以甲方提供标准文本为准”，不要自己猜。"},{"t":"h2","x":"三、验收：标准只给框架，合同要给判定"},{"t":"p","x":"标准通常规定“怎么做试验”，但“合格判定/抽样/复检”要在合同/技术协议里写清。否则同一个漏率，你说合格、客户说不合格，最后扯皮。"},{"t":"table","head":["验收项","必须写清","常见坑"],"rows":[["尺寸","量具、基准、抽检比例","只写“按图”，没写关键尺寸"],["外观","目视/放大倍数、允许缺陷","“无缺陷”无法判定"],["耐压","试验压力、保压时间、介质、温度","用工作压力代替试验压力"],["气密/氦检","漏率单位、方法、校准、判定","Pa·m³/s 与 mbar·L/s 混用"],["刚度","测点、位移、允差","只写“按样本”，没写测法"],["寿命","循环次数、幅值、频率、判定","只写“10 万次”，没写幅值"],["清洁度","等级、取样、检测方法","洁净室等级≠颗粒限值"],["材质","牌号、状态、质保书、复验","只写“不锈钢”"],["无损检测","RT/UT/PT/MT、比例、验收级别","写了方法没写级别"],["包装","防潮/防尘/防碰、标识","运输损坏算谁的"]]},{"t":"callout","kind":"key","title":"漏率单位：三个数量级的差别","x":"1×10⁻⁹ Pa·m³/s 与 1×10⁻⁶ Pa·m³/s 差 1000 倍；1 mbar·L/s≈0.1 Pa·m³/s。客户写“1E-9”没写单位，必须问清。真空/半导体常用 1E-9～1E-10 Pa·m³/s；一般气密可能只要求 1E-3～1E-6。"},{"t":"h2","x":"四、标准冲突：谁大谁小"},{"t":"list","ordered":true,"items":["**合同/技术协议**：最高；写清“高于标准”的条款优先。","**客户规范/企标**：合同引用后，高于通用国标。","**国家标准**：合同未特别约定时的底线。","**行业/国际标准**：合同引用时生效；不引用不自动强制。","**图纸标注**：与合同冲突时，通常以合同为准，但要发澄清函。"]},{"t":"p","x":"现实中最常见的是“图纸写国标、客户采购规范写更严的企标”。这时按更严的执行，除非客户书面同意偏离。销售不要自己判断“差不多”，要让技术/质量发偏差申请（deviation）或澄清。"},{"t":"h2","x":"五、图纸上的五个标准陷阱"},{"t":"table","head":["陷阱","例子","后果","怎么处理"],"rows":[["旧版标准","GB/T 12777-91","材料/检验按旧版，客户按新版拒收","查现行版；合同写现行有效"],["只写标准号不写年份","GB/T 12777","双方理解不同","合同约定版本/条款"],["漏率单位缺失","≤1E-9","差 1000 倍","问清 Pa·m³/s 还是 mbar·L/s"],["材料只写“不锈钢”","SS304/316 未定","耐蚀/成本差很多","定牌号+状态+质保书"],["无检测比例/级别","RT/UT 未写比例","全检/抽检成本差几倍","写清比例、级别、验收标准"]]},{"t":"callout","kind":"warn","title":"不要用“按图做”当免责","x":"图纸写“按图做”，但图里标准号/材料/检测不全，责任仍可能落到制造方。正确做法：报价前发《技术澄清单》，把标准版本、材料状态、检测比例、漏率单位、验收判定列出来，让客户签字/邮件确认。"},{"t":"h2","x":"六、合同里怎么写验收条款（模板）"},{"t":"list","ordered":true,"items":["**标准**：产品按 GB/T 12777-2019 / GB/T 14525-2010 / ISO 10380:2012 及本协议执行；标准冲突时以较严者为准。","**材料**：316L，固溶状态，提供质保书；必要时按 ASTM A262/E595 复验。","**尺寸**：关键尺寸 100% 检，其余按 GB/T 2828.1 抽样（AQL 由双方约定）。","**耐压**：1.5 倍设计压力，保压 1 min，无渗漏/无塑性变形。","**氦检**：漏率≤1×10⁻⁹ Pa·m³/s，氦质谱检漏，校准可追溯。","**刚度**：按图/样本，允差±X%；测点/位移写清。","**寿命**：10 万次，幅值/频率/压力按协议；首件做寿命试验。","**清洁度/包装**：按客户规范；防潮/防尘/防碰。","**不合格**：返工/让步/退货的判定与费用承担。"]},{"t":"p","x":"这段不是让你背，而是让你知道：标准只是骨架，合同才是血肉。客户说“按国标”，你要把国标里没写死的抽样、判定、复检补进合同；否则出了问题，双方都能引用标准，但谁也说服不了谁。"},{"t":"h2","x":"七、自测"}],"sources":["书 §1.7 标准简介","GB/T 12777-2019","GB/T 14525-2010","ISO 10380:2012","ASTM E595、ASTM G28"],"exam":{"pass":70,"minutes":15,"intro":"11 道题，覆盖本课的概念、数字与现场判断。答错会看到解释。","questions":[{"q":"波纹管膨胀节最常用的现行国标是：","opts":["GB/T 12777-2019","GB/T 12777-91","GB/T 14525-2010","ISO 9001"],"a":0,"why":"GB/T 12777-2019 是现行版；1991 版已旧，不能直接按旧版报价。"},{"q":"波纹金属软管的现行国标是：","opts":["GB/T 12777-2019","GB/T 14525-2010","GB/T 1804","ASTM E595"],"a":1,"why":"GB/T 14525-2010 管波纹金属软管；ISO 10380 是国际对应标准。"},{"q":"ASME B31.3 主要管：","opts":["洁净室","管道系统","食品包装","颜色"],"a":1,"why":"B31.3 是工艺管道标准；合同/法规引用时适用。"},{"q":"标准冲突时，通常优先级最高的是：","opts":["国标","合同/技术协议","行业标准","网络文章"],"a":1,"why":"合同/技术协议最高；客户规范被引用后高于通用标准。"},{"q":"图纸只写“GB/T 12777”不写年份，正确做法是：","opts":["按最旧版","按最新版","合同约定现行有效版/具体版本","随便"],"a":2,"why":"写清版本/条款，避免双方理解不同；不能靠猜。"},{"q":"漏率 1×10⁻⁹ 与 1×10⁻⁶ 差多少倍？","opts":["3 倍","100 倍","1000 倍","一样"],"a":2,"why":"10⁻⁹ 比 10⁻⁶ 小 1000 倍，要求更严。"},{"q":"ASTM E595 测的是：","opts":["盐雾","材料放气（TML/CVCM）","硬度","冲击"],"a":1,"why":"E595 是真空/航天材料放气测试。"},{"q":"下面哪项不是验收条款必须写清的？","opts":["试验方法","判定标准","抽样比例","销售员生日"],"a":3,"why":"方法/判定/抽样/报告/复检是验收五要素。"},{"q":"图纸写“按图做”，但检测比例没写，你应该：","opts":["按全检报价","发澄清单确认比例/级别","按不检","让客户自己检"],"a":1,"why":"检测比例影响成本，必须澄清并写入合同。"},{"q":"查国内标准现行状态，最可靠的渠道是：","opts":["百度百科","全国标准信息公共服务平台","论坛","记忆"],"a":1,"why":"std.samr.gov.cn 可查标准号、状态、替代关系；不要凭记忆。"},{"q":"洁净室等级（ISO 14644）与漏率的关系是：","opts":["同一件事","不同指标，不能互相替代","洁净度越高漏率越大","无关"],"a":1,"why":"洁净度管颗粒，漏率管泄漏；真空/半导体件两者都可能要求。"}]}},"20":{"title":"电沉积波纹管：把金属一层一层“长”出来","sub":"前面三种工艺都是“把管子变形”；电沉积反过来：先做一个和波纹管内腔一模一样的芯模，再往上镀金属，最后把芯模化掉。它专做别的工艺做不了的小、薄、软。这一课按书第 3 章讲清原理、能力边界、公式和报价。","tags":["第3章","电沉积","镍","芯模","微型波纹管","半导体","医疗"],"objectives":["用一句话说清电沉积和电镀的区别","能画出“芯模→镀镍→脱模”的三步流程","知道电沉积最适合什么尺寸、什么刚度、什么位移","记住常规镍与无硫镍的温度/强度差别","会用式 3-1～3-5 估算位移、耐压、刚度、有效面积","知道外径/壁厚/d/D 的设计极限，报价前能判断“做不做得了”"],"blocks":[{"t":"lead","x":"客户要一根内径 0.8 mm、壁厚 0.02 mm、总长 2 mm 的波纹管，还要漏率 1E-9。液压成形做不了，焊接也做不了。这时只剩一条路：电沉积。它不是在管子上“压”出波纹，而是把金属一层一层“长”成波纹管。"},{"t":"figure","name":"electroCell","cap":"芯模阴极，镍阳极；脱模后就是波纹管"},{"t":"callout","kind":"note","title":"这一课接在哪","x":"第 19 课讲验收；这一课讲电沉积：当液压、焊接都做不了时，怎么把金属一层一层“长”成波纹管。"},{"t":"table","head":["符号","怎么读","单位","在本课里指什么"],"rows":[["D/d","大写 D / 小写 d","mm","外径/内径"],["h₀","h 下标 0","mm","沉积层壁厚"],["n","小写 n","个","波数"],["w","小写 w","mm","允许位移"],["p_n","p 下标 n","MPa","耐压力"],["K","大写 K","N/mm","刚度"],["A_e","A 下标 e","cm²","有效面积"]]},{"t":"h2","x":"一、一句话：电沉积不是“电镀装饰”，是“造零件”"},{"t":"p","x":"（书 §3.1）电沉积波纹管，是在一个具有波纹管内形的芯模上，用电化学方法沉积金属，达到所需厚度后，再把芯模除去，留下来的金属壳就是波纹管。它和普通电镀的最大区别：普通电镀的镀层附着在零件表面，是装饰/防护；电沉积的沉积层要和芯模分离，自己成为结构件，厚度从几微米到几百微米。"},{"t":"callout","kind":"key","title":"记住三个关键词","x":"芯模（决定波纹形状）、电沉积（决定壁厚/材料）、脱模（把芯模化掉，留下壳体）。三个环节任何一个出问题，管子就废。"},{"t":"h2","x":"二、原理：镍离子怎么变成金属"},{"t":"p","x":"把镍板作阳极，芯模作阴极，放进镍盐电解液。通电后，阳极的镍溶解成 Ni²⁺，阴极的 Ni²⁺得到两个电子，变成金属镍沉积在芯模表面：Ni²⁺ + 2e⁻ → Ni。沉积时间越长，壁厚越厚；芯模什么形状，沉积层就复制什么形状。"},{"t":"list","ordered":true,"items":["**芯模**：铝合金/塑料等可加工、可溶解的材料，外形与波纹管内腔一致；表面要导电（或先做导电层）。","**前处理**：清洗、除油、活化，保证沉积层均匀附着。","**电沉积**：控制电流密度、温度、搅拌、电解液成分；沉积速度与电流/面积有关。","**脱模**：用化学溶解/熔融等方式去掉芯模，留下镍壳。","**后处理**：退火/稳定化、清洗、检漏、整形。"]},{"t":"callout","kind":"warn","title":"壁厚均匀是最大难点","x":"电流在芯模表面分布不均，波峰/波谷/端部的壁厚会不一样；深波、尖角、遮挡处更明显。所以电沉积件的刚度/耐压离散度比液压件大，报价和验收都要留余量。"},{"t":"h2","x":"三、它为什么存在：四个“别的工艺做不到”"},{"t":"table","head":["能力","电沉积","液压/焊接（对比）"],"rows":[["最小内径","可到 0.75 mm","一般 ≥3–5 mm 就很难"],["最小长度","可到 1 mm","夹持/模具限制"],["壁厚","可到 0.01–0.02 mm 级","薄壁液压/焊接更难"],["刚度","同尺寸约为液压成形的 5%","相对大"],["位移","可达自由长度 40%","受波高/壁厚限制"],["漏率","一般 ≤3×10⁻⁹ Pa·m³/s","取决于焊缝/母材"],["异形/多层","可做 NN/WW/NW、U/V 型","受模具/焊接限制"]]},{"t":"p","x":"（书 §3.1）书里给了一个很直观的例子：外径 0.94 mm、长 1 mm 的电沉积波纹管，0.04 N 的力就能全压缩。这种“极小、极软、行程相对大”的场景，液压和焊接基本做不到。半导体、医疗、航天的小型密封/补偿件，是它的典型战场。"},{"t":"h2","x":"四、代价：为什么它贵、慢"},{"t":"list","items":["**周期长**：沉积速度有限，厚壁要几小时到几十小时；模具/脱模也占时间。","**成本高**：芯模、电解液、贵金属（金/银镀层）、人工、废液处理。","**壁厚不均**：波峰/波谷/端部差异，刚度/耐压离散。","**难大规模**：小批量、多品种更合适；大批量不如冲压/液压。","**维护难**：电解液成分、温度、电流密度都要控；停线/换槽影响大。"]},{"t":"callout","kind":"warn","title":"不是“越小越便宜”","x":"很多人以为小件便宜；电沉积恰恰相反：越小、越薄、越异形，芯模/脱模/检测越难，单价越高。报价前先问：尺寸、壁厚、数量、材料、漏率、清洁度。"},{"t":"h2","x":"五、材料：常规镍 vs 无硫镍"},{"t":"table","head":["材料","含硫","强度/硬度","温度上限","适用"],"rows":[["常规镍","含硫（约 0.02–0.05%）","σ0.2≈770 MPa、σb≈880 MPa、HV≈270、伸长率≈1%","≤180℃","一般用途、成本低"],["无硫镍","S<0.003%","屈服略低、塑性略好","≤250℃","高温/耐蚀/长寿命"],["镀金/银","—","导电/接触电阻低","按镀层","电接触/高频"]]},{"t":"p","x":"（书 §3.1）常规镍超过 180℃ 会因硫脆裂；无硫镍把硫降到 0.003% 以下，耐蚀/耐温更好，但屈服略低。低温（液氧/液氢）时镍的强度会升约 30%，但塑形下降，设计要按低温材料数据。"},{"t":"callout","kind":"key","title":"温度是选材的第一道门","x":"客户说 200℃，常规镍就不够；说 250℃，无硫镍也到边界。再高就要换材料/结构，不能靠“试试”。"},{"t":"h2","x":"六、公式：五个数，先算位移和耐压"},{"t":"p","x":"（书 §3.2）电沉积波纹管的公式是经验/半经验式，单位必须统一：mm、MPa、N。下面五个式子，报价前够用；精确设计还要 FEA/试验。"},{"t":"table","head":["式","公式","算什么","单位/注意"],"rows":[["3-1","w=0.001(D−d−h₀)²n/h₀","10 万次轴向压缩位移","mm；拉伸取 75%；V 型只适用压缩"],["3-2","p_n=E h₀²/(D−d)²","耐压力","MPa；E 取 2×10⁵ MPa"],["3-3","K=F/w","刚度定义","N/mm"],["3-4","K=4.3E(D+d)h₀³/(D−d−h₀)³","U 型刚度","N/mm；V 型×1.33"],["3-5","A_e=π/1600(D+d)²","有效面积","cm²；注意单位"]]},{"t":"p","x":"式 3-1 里 0.001 是单位/经验系数；n 是波数，h₀ 是单层壁厚。它说明：波深（D−d）越大、波数越多、壁厚越薄，允许位移越大；但波深/壁厚受工艺限制，不能无限取。"},{"t":"p","x":"式 3-2 说明耐压与 h₀² 成正比、与波深² 成反比：壁厚翻倍，耐压约 4 倍；波深翻倍，耐压约 1/4。式 3-4 说明刚度对 h₀³ 极敏感：壁厚 +20%，刚度约 +73%。这就是为什么电沉积件“软”，也是为什么壁厚公差要卡严。"},{"t":"h2","x":"七、算例：D=10、d=8、h₀=0.05、n=10"},{"t":"kv","items":[["波深","D−d=2 mm"],["式 3-1 位移","w=0.001×(2−0.05)²×10/0.05≈0.76 mm"],["式 3-2 耐压","p_n=2×10⁵×0.05²/2²=125 MPa（理论值，实际受稳定/端部限制）"],["式 3-4 刚度","K≈4.3×2×10⁵×18×0.05³/(1.95)³≈261 N/mm"],["式 3-5 有效面积","A_e=π/1600×18²≈0.636 cm²"],["解读","理论耐压很高，但薄壁/长管先失稳；位移 0.76 mm 是 10 万次条件，不是随便压"]]},{"t":"callout","kind":"warn","title":"公式给的是“上限”，不是“承诺”","x":"式 3-2 的 125 MPa 是材料/几何的理想值；实际受柱失稳、端部、壁厚不均、温度影响，可能只剩几分之一。报价/承诺要按试验/经验打折，不能把公式值直接写进合同。"},{"t":"h2","x":"八、设计极限：外径、壁厚、d/D"},{"t":"p","x":"（书 §3.2）电沉积不是无限大/无限薄。外径一般 ≤35 mm；d/D≥0.6，最佳 0.65（太小波深大，沉积/脱模难）；壁厚下限随外径增大而增大，因为大直径芯模更难做得完美、沉积更不均。"},{"t":"table","head":["外径 D（mm）","最小壁厚 h₀（mm）","说明"],"rows":[["1.6","0.0075","微型"],["3","0.013","微型"],["6","0.018","小型"],["9.5","0.023","小型"],["13","0.025","中小"],["19","0.035","中小"],["25","0.050","中"],["32","0.056","中"],["38","0.060","接近上限"],["50","0.075","超常规，需评估"],["64","0.090","超常规"],["76","0.100","超常规"]]},{"t":"p","x":"这张表的意思是：外径越大，最小壁厚也越大；不是“想镀多薄就多薄”。客户要 D=50、h₀=0.03，理论上就做不到，别再算价格，先谈结构。"},{"t":"h2","x":"九、公差：电沉积的“松”和“紧”"},{"t":"table","head":["项目","公差","备注"],"rows":[["内径 >6.35 mm","±0.125 mm","按书"],["内径 <6.35 mm","0.076 mm","按书"],["波纹长度","±0.25 mm","累积公差"],["管端开口内径","0.04 mm","配合/焊接"],["端部长度","±0.125 mm","装配"],["刚度","±30%（特殊 ±5%）","壁厚不均导致"],["壁厚","±5% 平均壁厚","不是逐点"]]},{"t":"callout","kind":"key","title":"刚度 ±30% 是常态","x":"电沉积件刚度离散大；客户若要求 ±5%，要挑件/逐件测/加成本，不能按常规报价。图纸写“刚度按样本”，你要问清允差和测法。"},{"t":"h2","x":"十、结构：NN/WW/NW，U/V 型"},{"t":"p","x":"（书 §3.1）电沉积可做 NN（两端内配合）、WW（两端外配合）、NW（一内一外）；波型以 U 型为主，V 型用于特殊行程/刚度。端部结构与液压件类似，但电沉积的端部是“长出来”的，不是焊接/翻边，所以壁厚过渡更平滑，但脱模/加工更复杂。"},{"t":"table","head":["结构","特点","典型"],"rows":[["NN","两端内配合，外形小","仪表/传感器"],["WW","两端外配合，工艺性好","通用"],["NW","一内一外，过渡","特殊接口"],["U 型","位移大、刚度低","通用"],["V 型","刚度略高、只建议压缩","特殊"]]},{"t":"h2","x":"十一、和液压/焊接怎么选"},{"t":"table","head":["维度","电沉积","液压成形","焊接"],"rows":[["尺寸","最小（0.75 mm 内径）","中/大","中/大"],["壁厚","最薄（0.01 mm 级）","0.08–0.5 mm","0.1–1.0 mm"],["刚度","最低（约液压 5%）","中","中/高"],["位移","可达 L 的 40%","10–40%","受焊缝限制"],["成本","高（小批量）","低/中","中"],["周期","长","短","中"],["最适合","微型/异形/高灵敏","通用/大位移","大直径/高压/多层"]]},{"t":"callout","kind":"key","title":"销售一句话","x":"“能做液压的，别用电沉积；液压做不了的（太小、太薄、太软），才用电沉积。”这句话能帮你快速判断客户需求，也能解释为什么电沉积贵。"},{"t":"h2","x":"十二、报价前必须问的七个问题"},{"t":"list","ordered":true,"items":["内径/外径/长度是多少？是否在 ≤35 mm、d/D≥0.6 范围？","壁厚要求多少？是否低于对应外径的最小壁厚？","位移/寿命/压力/温度是多少？常规镍还是无硫镍？","介质/清洁度/漏率？是否需要镀金/银？","端部结构 NN/WW/NW？怎么连接（焊接/粘接/压接）？","数量/批次？小批量还是大批量？","验收：刚度允差、壁厚、漏率、外观、报告？"]},{"t":"h2","x":"十三、自测"}],"sources":["第3章 §3.1–§3.2","式 3-1～3-5","表 3-1、3-2"],"exam":{"pass":70,"minutes":15,"intro":"12 道题，覆盖本课的概念、数字与现场判断。答错会看到解释。","questions":[{"q":"电沉积与普通电镀的最大区别是：","opts":["颜色不同","沉积层与芯模分离、成为结构件","不用电","只镀塑料"],"a":1,"why":"电沉积是“造零件”，沉积层要脱模后独立承力；普通电镀是表面附着。"},{"q":"电沉积的三步流程是：","opts":["冲压→焊接→抛光","芯模→电沉积→脱模","拉深→退火→酸洗","切割→卷圆→焊接"],"a":1,"why":"芯模决定形状，电沉积决定壁厚，脱模留下壳体。"},{"q":"阴极/阳极分别是：","opts":["芯模/镍","镍/芯模","都是镍","都是芯模"],"a":0,"why":"芯模为阴极，镍为阳极；Ni²⁺在阴极还原沉积。"},{"q":"电沉积最适合的尺寸是：","opts":["外径 500 mm","内径 0.75 mm、长 1 mm","长度 2 m","壁厚 5 mm"],"a":1,"why":"它专做微型/薄壁/异形；大件用液压/焊接更经济。"},{"q":"常规镍的温度上限约：","opts":["80℃","180℃","400℃","800℃"],"a":1,"why":"常规镍含硫，超过 180℃ 有脆裂风险；无硫镍到 250℃。"},{"q":"式 3-2 说明耐压与壁厚的关系是：","opts":["正比","平方正比","反比","无关"],"a":1,"why":"p_n=E h₀²/(D−d)²，与 h₀² 成正比。"},{"q":"式 3-4 说明刚度对壁厚 h₀ 是：","opts":["线性","平方","三次方","无关"],"a":2,"why":"K∝h₀³；壁厚 +20%，刚度约 +73%。"},{"q":"外径 50 mm 的电沉积件，最小壁厚约：","opts":["0.01 mm","0.03 mm","0.075 mm","0.5 mm"],"a":2,"why":"按书表，D=50 对应最小壁厚约 0.075 mm；更薄做不了。"},{"q":"电沉积件刚度公差常见是：","opts":["±5%","±30%","±100%","±0.1%"],"a":1,"why":"壁厚不均导致刚度离散，常规 ±30%；±5% 要特殊控制/挑件。"},{"q":"客户要 D=10、d=8、h₀=0.05、n=10，按式 3-1 位移约：","opts":["0.076 mm","0.76 mm","7.6 mm","76 mm"],"a":1,"why":"0.001×(2−0.05)²×10/0.05≈0.76 mm（10 万次条件）。"},{"q":"下面哪种情况最该推荐电沉积？","opts":["D=200、批量 1 万","D=2、壁厚 0.02、要求高灵敏","只要便宜","要 10 m 长"],"a":1,"why":"微型/薄壁/高灵敏是电沉积的强项；大件/大批量不经济。"},{"q":"电沉积报价前，最重要的三个参数是：","opts":["颜色/包装/品牌","尺寸/壁厚/数量","销售员/日期/发票","重量/体积/运费"],"a":1,"why":"尺寸决定芯模/脱模，壁厚决定时间/成本，数量决定分摊。"}]}}});
